window.ZHIFOU_ZHANYI={"hook":"中国历史上有哪些改变走向的战役？","answer":"这一页按战役讲：52场战役从牧野排到甲午，每场一张卡——起因、经过、结果，史书记载的兵力数字，关联的都城和人物。","tags":["改朝换代","统一战争","边疆与对外","内战叛乱","水战","攻城守城","关键转折","战法典型"],"tagCount":{"改朝换代":15,"统一战争":5,"边疆与对外":16,"内战叛乱":5,"水战":7,"攻城守城":13,"关键转折":22,"战法典型":11},"cityShow":{"丰镐":"西安（丰镐）","临淄":"临淄","二里头":"偃师（二里头）","会宁":"阿城（金上京）","兴庆府":"银川","凤阳":"凤阳","北京（蓟、幽州、燕京、中都、大都、北平、京师）":"北京","南京（建业、建康、金陵、应天、天京）":"南京","咸阳":"咸阳","哈拉和林":"哈拉和林","大理":"大理","平城":"大同","开封（汴州、东京、大梁）":"开封","开平／元上都":"正蓝旗（元上都）","成都":"成都","新郑":"新郑","晋阳":"太原","曲阜":"曲阜","杭州（临安）":"杭州","殷墟":"安阳（殷墟）","江陵":"荆州（江陵）","沈阳":"沈阳","洛阳（成周、王城）":"洛阳（先秦）","洛阳（秦汉至隋唐）":"洛阳（汉至唐）","渤海上京龙泉府":"宁安（渤海上京）","番禺":"广州","统万城":"靖边（统万城）","苏州（姑苏）":"苏州","许昌":"许昌","赫图阿拉":"新宾（赫图阿拉）","辽上京":"巴林左旗（辽上京）","辽中京大定府":"宁城（辽中京）","辽阳":"辽阳","逻些（拉萨）":"拉萨","邯郸":"邯郸","邺城":"临漳（邺城）","郑州商城":"郑州","郢":"荆州（纪南城）","长安":"西安（汉唐）","雍城":"凤翔（雍城）"},"intro":[{"t":"从牧野到甲午黄海，战争改变了王朝的兴亡，也改变了边疆、都城与百姓的生活。这五十二场战事按时间排列，既有决定政权存亡的决战，也有影响统一进程、边疆关系和作战方式的交锋。秦灭六国、隋灭陈涉及多路军队和多个地区；第一次鸦片战争则跨越数年，沿海与长江战场彼此相连。","s":["《史记·秦始皇本纪》","《隋书·韩擒虎、贺若弼传》","《清史稿·宣宗本纪》"]},{"t":"古书中的“战”，可以指一次交锋，也可以泛指争战。这里以“战役”组织材料，讲述围绕一定目标展开、在时间与地域上相连的一组行动。“战争”的范围往往更大，包含政治动员和多个战场。长平经历相持、换将、断粮、突围与投降；赤壁也有初战、火攻和退军追击。顺着这些先后关系，才能看清一场仗如何走到结局。","s":["《史记·白起王翦列传》","《三国志·周瑜传》"]},{"t":"战争留下的记录有奏报、传记、编年与后世追述，详细程度各不相同。兵力尤其容易混淆：有的是出征总数，有的是某路军队，有的是“号称”，有的是杀伤与俘获合计。《武帝纪》说官渡曹军“不满万”，裴松之已据作战经过提出质疑；《后汉书》在昆阳叙事里又分别记新军百万、甲士四十二万和先到的围城部队。数字放回各自语境，读者才能理解它所描绘的规模与局限。","s":["《三国志·武帝纪》裴松之注","《后汉书·光武帝纪上》"]},{"t":"每张卡先交代谁在何处交战，再按顺序讲述起因、行动与后果。“改朝换代”“统一战争”“边疆与对外”等标签，帮助读者寻找不同主题；同一场仗也可能同时涉及多种变化。地名兼列今名与古称，坐标用于区域索引。史书的分歧、战场定位与数字疑问集中在“史料说明”，尚待查证的地方保留红色标记。都城与人物索引，则把战场上的行动接回更长的朝代历史。","s":[]}],"table":[{"name":"牧野之战","short":"牧野","time":"约前1046","place":"河南新乡北部一带","sides":"周及盟军／商","result":"商王帝辛败亡","tags":["改朝换代","关键转折"],"line":"周武王率诸侯联军在牧野击败商军，商纣自焚，商朝灭亡，周朝由此建立。","s":["《史记·周本纪》"]},{"name":"长勺之战","short":"长勺","time":"前684","place":"山东济南莱芜一带（定位待核）","sides":"鲁／齐","result":"鲁军获胜","tags":["战法典型"],"line":"齐军进攻鲁国，曹刿协助鲁庄公把握出击和追击时机，鲁军在长勺获胜。","s":["《左传·庄公十年》"]},{"name":"城濮之战","short":"城濮","time":"前632","place":"河南濮阳、山东鄄城交界一带（定位待核）","sides":"晋及盟军／楚及盟军","result":"楚军败退","tags":["战法典型","关键转折"],"line":"晋文公救宋迎战楚军，城濮获胜后召集诸侯会盟，确立了晋国的霸主地位。","s":["《左传·僖公二十八年》"]},{"name":"柏举之战","short":"柏举","time":"前506","place":"湖北东北部（具体地点有争议）","sides":"吴、蔡、唐／楚","result":"吴胜并进占郢","tags":["关键转折","战法典型"],"line":"吴军联合蔡、唐进攻楚国，在柏举获胜后一路追击入郢，楚昭王被迫出走。","s":["《左传·定公四年》"]},{"name":"桂陵之战","short":"桂陵","time":"前353","place":"河南长垣、山东菏泽一带（定位待核）","sides":"齐／魏","result":"魏军战败","tags":["战法典型"],"line":"魏军围攻赵都邯郸，齐军转攻魏国腹地，在桂陵击败回援的魏军，改变战局。","s":["《史记·孙子吴起列传》"]},{"name":"马陵之战","short":"马陵","time":"前341","place":"山东郯城、河南范县等异说（待核）","sides":"齐／魏","result":"魏军败，庞涓死","tags":["战法典型","关键转折"],"line":"齐军以减灶诱使魏军追赶，在马陵设伏，庞涓死、太子申被俘，魏国遭受重创。","s":["《史记·孙子吴起列传》"]},{"name":"长平之战","short":"长平","time":"前260","place":"山西晋城高平市","sides":"秦／赵","result":"赵军投降后遭杀戮","tags":["关键转折","战法典型"],"line":"秦赵争夺上党，白起切断赵军粮道并将其包围，赵军投降后遭到大规模杀戮。","s":["《史记·白起王翦列传》"]},{"name":"秦灭六国之战","short":"秦灭六国","time":"前230—前221","place":"河南、河北、山西、山东、湖北、安徽等","sides":"秦／韩赵魏楚燕齐","result":"六国相继灭亡","tags":["改朝换代","统一战争"],"line":"秦军先后攻灭韩赵魏楚燕齐，结束六国分立的局面，秦王政由此建立统一帝国。","s":["《史记·秦始皇本纪》"]},{"name":"巨鹿之战","short":"巨鹿","time":"前207","place":"河北邢台平乡县一带","sides":"楚、赵及诸侯／秦","result":"王离军败，章邯后降","tags":["改朝换代","关键转折"],"line":"项羽渡河救赵，击破巨鹿的秦军围城体系，随后迫使章邯投降，秦军主力受挫。","s":["《史记·项羽本纪》"]},{"name":"彭城之战","short":"彭城","time":"前205","place":"江苏徐州","sides":"楚／汉及诸侯联军","result":"汉联军败退","tags":["关键转折"],"line":"刘邦率诸侯联军进入彭城，项羽从齐地回师突击，汉军败退，楚汉战争继续。","s":["《史记·项羽本纪》"]},{"name":"垓下之战","short":"垓下","time":"前202","place":"安徽宿州灵璧等异说（待核）","sides":"汉及诸侯／楚","result":"楚军溃，项羽后自杀","tags":["改朝换代","关键转折"],"line":"汉及诸侯军会合垓下，项羽在重围中突围后自杀，西楚败亡，刘邦取得主导地位。","s":["《史记·项羽本纪》"]},{"name":"白登之战","short":"白登","time":"前200","place":"山西大同东北一带","sides":"汉／匈奴","result":"汉高祖被围后脱出","tags":["边疆与对外"],"line":"汉高祖北征时在白登遭匈奴围困，七日后脱险，汉廷随后以和亲处理边境关系。","s":["《史记·匈奴列传》"]},{"name":"漠北之战","short":"漠北","time":"前119","place":"今蒙古国境内等地","sides":"汉／匈奴","result":"汉两路军击败所遇匈奴军","tags":["边疆与对外"],"line":"卫青、霍去病分路深入漠北，打击单于和左贤王部，远征也耗费大量马匹物资。","s":["《史记·卫将军骠骑列传》"]},{"name":"昆阳之战","short":"昆阳","time":"23","place":"河南平顶山叶县","sides":"更始军／新军","result":"新军败，王寻死","tags":["改朝换代","攻城守城"],"line":"新军围攻昆阳，刘秀出城集结援军，与守军合击破围，新朝南下的攻势受挫。","s":["《后汉书·光武帝纪上》"]},{"name":"官渡之战","short":"官渡","time":"200","place":"河南郑州中牟县","sides":"曹操／袁绍","result":"袁军败退","tags":["战法典型","关键转折"],"line":"曹操与袁绍在官渡相持，夜袭乌巢焚毁袁军粮屯，袁军溃退，北方局势转折。","s":["《三国志·武帝纪》"]},{"name":"赤壁之战","short":"赤壁","time":"208","place":"湖北赤壁、嘉鱼等异说","sides":"孙权、刘备／曹操","result":"曹军撤退","tags":["水战","关键转折"],"line":"孙权与刘备联合迎击曹操，黄盖纵火烧毁曹军舟营，曹操北撤，南方局势改变。","s":["《三国志·周瑜传》"]},{"name":"夷陵之战","short":"夷陵","time":"222（出兵始于221）","place":"湖北宜昌夷陵、宜都等地","sides":"吴／蜀汉","result":"蜀汉军败，刘备退白帝","tags":["战法典型","关键转折"],"line":"刘备为夺回荆州东征，陆逊坚守后以火攻反击，蜀军败退白帝，吴蜀随后复交。","s":["《三国志·陆逊传》"]},{"name":"街亭之战","short":"街亭","time":"228","place":"甘肃天水秦安陇城等异说","sides":"魏／蜀汉","result":"马谡败，蜀军退","tags":["关键转折"],"line":"诸葛亮首次北伐时，马谡在街亭被张郃击败，王平收拢败兵，蜀军随后退回汉中。","s":["《三国志·马良传附马谡》"]},{"name":"西晋灭吴之战","short":"灭吴","time":"279—280","place":"长江中下游及江苏南京","sides":"西晋／吴","result":"孙皓降，吴亡","tags":["改朝换代","统一战争","水战"],"line":"西晋水陆各军沿长江进攻，王濬率舟师抵达建业，孙皓投降，三国分立局面结束。","s":["《晋书·王濬传》"]},{"name":"永嘉之乱与洛阳陷落","short":"永嘉之乱","time":"311","place":"河南洛阳汉魏故城","sides":"汉赵（时国号汉）／西晋","result":"洛阳陷，晋怀帝被俘","tags":["改朝换代","攻城守城"],"line":"汉赵军攻陷洛阳，晋怀帝被俘，西晋朝廷遭受重创，残存朝廷后来迁至长安。","s":["《晋书·怀帝纪》"]},{"name":"淝水之战","short":"淝水","time":"383","place":"安徽淮南寿县一带","sides":"东晋／前秦","result":"前秦前线溃败","tags":["战法典型","关键转折"],"line":"前秦南下攻晋，两军隔淝水对峙，秦军后退时阵脚大乱，东晋渡河进攻获胜。","s":["《晋书·苻坚载记下》"]},{"name":"邙山之战","short":"邙山","time":"543","place":"河南洛阳北部","sides":"东魏／西魏","result":"西魏退，东魏保洛阳","tags":["关键转折"],"line":"东西魏在洛阳北面的邙山交战，西魏军失利撤退，东魏保住洛阳，双方继续对峙。","s":["《周书·文帝纪下》"]},{"name":"台城之战","short":"台城","time":"548—549","place":"江苏南京","sides":"侯景军／梁","result":"台城陷，梁武帝受制","tags":["内战叛乱","攻城守城"],"line":"侯景围攻南京台城，梁军多路救援未能解围，城破后梁武帝受制，朝廷权力崩解。","s":["《资治通鉴·卷161—162》","《资治通鉴·卷162》"]},{"name":"隋灭陈之战","short":"灭陈","time":"588—589","place":"长江沿线及江苏南京","sides":"隋／陈","result":"陈后主被俘，陈亡","tags":["改朝换代","统一战争"],"line":"隋军多路渡过长江，在建康城外击败陈军并俘获陈后主，南北分立局面由此结束。","s":["《隋书·韩擒虎、贺若弼传》"]},{"name":"虎牢之战","short":"虎牢","time":"621","place":"河南郑州荥阳汜水一带","sides":"唐／窦建德、王世充","result":"窦被俘，王随后降","tags":["改朝换代","统一战争"],"line":"李世民围攻洛阳，又在虎牢击败前来救援的窦建德，王世充随后投降，唐势扩大。","s":["《资治通鉴·卷189》"]},{"name":"唐灭东突厥之战","short":"灭东突厥","time":"629—630","place":"内蒙古及今蒙古国南部","sides":"唐／东突厥","result":"颉利可汗被俘","tags":["边疆与对外"],"line":"李靖等率唐军北进，突袭东突厥牙帐，颉利可汗随后被俘，汗国原有统治瓦解。","s":["《旧唐书·李靖传》"]},{"name":"白江口之战","short":"白江口","time":"663","place":"韩国锦江河口一带","sides":"唐、新罗／倭、百济复国军","result":"唐、新罗胜","tags":["水战","边疆与对外"],"line":"唐与新罗军在白江口击败倭国和百济复国军，百济复国行动失去重要的海上支援。","s":["《旧唐书·刘仁轨传》"]},{"name":"怛罗斯之战","short":"怛罗斯","time":"751","place":"今哈萨克斯坦、吉尔吉斯斯坦交界地区（定位待核）","sides":"唐及盟军／阿拔斯军及盟军","result":"唐军败退","tags":["边疆与对外"],"line":"高仙芝率唐军西进怛罗斯，与阿拔斯军交战，葛逻禄倒戈后唐军战败，余部东撤。","s":["《资治通鉴·卷216》"]},{"name":"潼关之战","short":"潼关","time":"756","place":"陕西潼关、河南灵宝","sides":"唐／安禄山军","result":"唐军败，潼关失守","tags":["内战叛乱","关键转折"],"line":"哥舒翰率唐军出潼关迎战，灵宝战败后关隘失守，唐玄宗离开长安，局势急转。","s":["《资治通鉴·卷218》"]},{"name":"睢阳之战","short":"睢阳","time":"756—757（核心围城为757）","place":"河南商丘","sides":"唐／安史叛军","result":"睢阳陷","tags":["内战叛乱","攻城守城"],"line":"张巡、许远坚守睢阳，长期围城耗尽城中粮食，城破后二人遇害，守军抵抗结束。","s":["《旧唐书·张巡传》"]},{"name":"黄巢攻陷长安","short":"黄巢入长安","time":"880（旧历纪年；公历跨881年初，详见卡）","place":"陕西西安","sides":"黄巢军／唐","result":"长安陷，后立大齐","tags":["内战叛乱","攻城守城"],"line":"黄巢军突破潼关进入长安，唐僖宗奔成都，黄巢建立大齐，唐廷随后组织反攻。","s":["《资治通鉴·卷254》"]},{"name":"高平之战","short":"高平","time":"954","place":"山西晋城高平市","sides":"后周／北汉、辽","result":"后周胜","tags":["关键转折"],"line":"后周军与北汉、辽军在高平交战，周世宗重整退却的部队反击获胜，稳住即位局势。","s":["《资治通鉴·卷291》"]},{"name":"高梁河之战","short":"高梁河","time":"979","place":"北京西北一带","sides":"宋／辽","result":"宋军败退","tags":["边疆与对外"],"line":"宋太宗灭北汉后进攻幽州，在高梁河遭辽军反击，宋军败退，收取幽州的行动受挫。","s":["《辽史·景宗纪下》"]},{"name":"澶州之战","short":"澶州","time":"1004","place":"河南濮阳","sides":"宋／辽","result":"战线对峙后议和","tags":["边疆与对外","攻城守城"],"line":"辽军南下抵达澶州，宋真宗赴前线督战，两军对峙后议和，宋辽订立澶渊之盟。","s":["《宋史·真宗纪》"]},{"name":"好水川之战","short":"好水川","time":"1041","place":"宁夏固原隆德等地（定位待核）","sides":"宋／西夏","result":"宋军败，任福死","tags":["边疆与对外","战法典型"],"line":"宋将任福率军追击西夏军，在好水川陷入包围，任福战死，宋军此次出击遭重创。","s":["《宋史·任福传》"]},{"name":"靖康之战与汴京陷落","short":"靖康之战","time":"1126—1127","place":"河南开封","sides":"金／北宋","result":"宋徽宗、钦宗被俘","tags":["改朝换代","攻城守城"],"line":"金军两度围攻汴京，城破后掳走宋徽宗、钦宗，北宋朝廷覆亡，南宋随后建立。","s":["《宋史·钦宗纪》"]},{"name":"郾城之战","short":"郾城","time":"1140","place":"河南漯河郾城区","sides":"南宋／金","result":"岳飞军守住郾城","tags":["边疆与对外","战法典型"],"line":"金军进攻郾城，岳飞率军迎战并守住阵地，宋金在河南的战事随后仍然继续。","s":["《宋史·岳飞传》"]},{"name":"采石之战","short":"采石","time":"1161","place":"安徽马鞍山采石一带","sides":"南宋／金","result":"金军渡江受阻","tags":["水战","边疆与对外"],"line":"完颜亮率金军南下，虞允文在采石组织宋军水陆迎击，金军渡江受阻，战局生变。","s":["《宋史·虞允文传》"]},{"name":"钓鱼城之战","short":"钓鱼城","time":"1259","place":"重庆合川","sides":"南宋／蒙古","result":"蒙古攻城未克，蒙哥死后撤军","tags":["攻城守城","边疆与对外"],"line":"蒙古军围攻钓鱼城，守将王坚据城抵抗，蒙哥在围城期间去世，蒙古军随后撤退。","s":["《元史·宪宗纪》"]},{"name":"襄阳之战","short":"襄阳","time":"1268—1273","place":"湖北襄阳","sides":"南宋／蒙古（1271后称元）","result":"樊城陷，襄阳降","tags":["攻城守城","关键转折"],"line":"蒙古军长期围困襄樊，攻破樊城后迫使吕文焕献襄阳投降，南宋长江防线出现缺口。","s":["《元史·阿术传》"]},{"name":"崖山海战","short":"崖山","time":"1279","place":"广东江门新会","sides":"元／南宋","result":"宋军败，宋末帝死","tags":["改朝换代","水战"],"line":"南宋最后的朝廷退至崖山，张弘范率元军进攻，宋军战败，陆秀夫负宋末帝投海。","s":["《宋史·陆秀夫传》"]},{"name":"鄱阳湖之战","short":"鄱阳湖","time":"1363","place":"江西鄱阳湖","sides":"朱元璋／陈友谅汉","result":"陈友谅死，其军败","tags":["水战","关键转折"],"line":"朱元璋与陈友谅在鄱阳湖交战，火攻和封锁相继展开，陈友谅战死，陈汉主力受挫。","s":["《明史·太祖本纪》"]},{"name":"明军攻占大都","short":"攻占大都","time":"1368","place":"北京","sides":"明／元","result":"明占大都，元帝北走","tags":["改朝换代","统一战争","攻城守城"],"line":"徐达率明军北伐进入大都，元顺帝北走，元朝在中原的统治结束，北方政权继续。","s":["《明史·徐达传》"]},{"name":"靖难之役","short":"靖难","time":"1399—1402","place":"河北、山东至江苏南京","sides":"燕王朱棣／建文朝廷","result":"朱棣入南京即位","tags":["内战叛乱","关键转折"],"line":"燕王朱棣起兵与建文朝廷争夺皇位，转战河北山东后攻入南京，随后即皇帝位。","s":["《明史·成祖本纪》"]},{"name":"土木堡之战","short":"土木堡","time":"1449","place":"河北张家口怀来县","sides":"瓦剌／明","result":"明军败，明英宗被俘","tags":["边疆与对外","关键转折"],"line":"明英宗亲征瓦剌，回师途中在土木堡被围，明军溃败、皇帝被俘，北京面临危机。","s":["《明史·英宗前纪》"]},{"name":"萨尔浒之战","short":"萨尔浒","time":"1619","place":"辽宁抚顺","sides":"后金／明及盟军","result":"后金击败明多路军","tags":["边疆与对外","关键转折"],"line":"明军分路进攻后金，努尔哈赤集中兵力逐路迎击，明军多路战败，辽东攻守局势改变。","s":["《明史·杨镐传》"]},{"name":"李自成攻陷北京","short":"陷北京","time":"1644","place":"北京","sides":"大顺／明","result":"北京陷，崇祯帝死","tags":["改朝换代","攻城守城"],"line":"李自成军攻入北京，崇祯帝自缢，明朝北京朝廷覆亡，明宗室随后在南方继续建政。","s":["《明史·庄烈帝纪》"]},{"name":"山海关之战","short":"山海关","time":"1644","place":"河北秦皇岛山海关","sides":"清、吴三桂／大顺","result":"大顺败退","tags":["改朝换代","关键转折"],"line":"吴三桂与大顺军在山海关交战，清军入战后击败大顺，随后进占北京，局势转折。","s":["《清史稿·世祖本纪》"]},{"name":"收复台湾之战","short":"收复台湾","time":"1661—1662","place":"台湾台南","sides":"郑成功军／荷兰东印度公司","result":"荷方据点投降","tags":["边疆与对外","攻城守城"],"line":"郑成功渡海进攻台湾，围攻荷兰东印度公司据点，荷方在次年投降，郑军控制台南。","s":["《清史稿·郑成功传》"]},{"name":"第一次鸦片战争","short":"鸦片战争","time":"1839—1842（前奏始于1839）","place":"广东、浙江、江苏等沿海沿江","sides":"清／英国","result":"清战败议和","tags":["边疆与对外"],"line":"英国舰队沿中国海岸和长江进攻，清军多处失利，清廷最终议和并签订南京条约。","s":["《清史稿·宣宗本纪》"]},{"name":"天京陷落","short":"天京陷落","time":"1864","place":"江苏南京","sides":"清／太平天国","result":"清军入城，太平天国都城失守","tags":["改朝换代","攻城守城"],"line":"湘军围攻天京并破城，太平天国都城失守、中央政权瓦解，各地部队仍继续作战。","s":["《清史稿·曾国藩传》"]},{"name":"甲午黄海海战","short":"黄海海战","time":"1894","place":"黄海北部","sides":"清北洋水师／日本联合舰队","result":"北洋多舰损失，双方脱离","tags":["水战","边疆与对外"],"line":"北洋水师与日本联合舰队在黄海交战，致远等舰沉没，北洋舰队受损后返回基地。","s":["《清史稿·卷462·丁汝昌传》"]}],"groups":[{"title":"第一组·先秦","battles":["牧野之战","长勺之战","城濮之战","柏举之战","桂陵之战","马陵之战","长平之战","秦灭六国之战"]},{"title":"第二组·秦汉","battles":["巨鹿之战","彭城之战","垓下之战","白登之战","漠北之战","昆阳之战"]},{"title":"第三组·三国至南北朝","battles":["官渡之战","赤壁之战","夷陵之战","街亭之战","西晋灭吴之战","永嘉之乱与洛阳陷落","淝水之战","邙山之战","台城之战","隋灭陈之战"]},{"title":"第四组·隋唐五代","battles":["虎牢之战","唐灭东突厥之战","白江口之战","怛罗斯之战","潼关之战","睢阳之战","黄巢攻陷长安","高平之战"]},{"title":"第五组·两宋辽金元","battles":["高梁河之战","澶州之战","好水川之战","靖康之战与汴京陷落","郾城之战","采石之战","钓鱼城之战","襄阳之战","崖山海战"]},{"title":"第六组·明清","battles":["鄱阳湖之战","明军攻占大都","靖难之役","土木堡之战","萨尔浒之战","李自成攻陷北京","山海关之战","收复台湾之战","第一次鸦片战争","天京陷落","甲午黄海海战"]}],"battles":[{"name":"牧野之战","group":"第一组·先秦","tags":["改朝换代","关键转折"],"g":"部分待核","lat":35.4,"lon":113.9,"f":[{"k":"时间","v":"约前1046，为通行断代方案；古籍记交战在甲子日早晨。","s":["《史记·周本纪》"]},{"k":"地点","v":"河南省新乡市北部一带，古名牧野，具体战场范围有不同定位。〔待核〕","s":[]},{"k":"交战双方","v":"周及参与伐商的盟军对商。","s":["《史记·周本纪》"]},{"k":"兵力与伤亡","v":"《史记·周本纪》记周军戎车三百乘、虎贲三千人、甲士四万五千人，帝辛发兵七十万人；这是书中分列的车辆、兵种与商方动员数字。","s":["《史记·周本纪》"]},{"k":"起因","v":"周文王时期，周的势力逐渐扩展。武王继位后，由吕尚、周公等人辅佐，继续联合诸侯。《周本纪》记载诸侯曾在盟津会合，武王当时认为时机未到，收兵返回。后来商王帝辛与臣下的矛盾加深，武王再次召集盟军，向商王所在的核心地区进发。","s":["《史记·周本纪》","《史记·殷本纪》"]},{"k":"结果与影响","v":"帝辛败亡，商王朝的统治中心落入周军手中，周取得取代商王权的基础。武王安排武庚延续商的祭祀，商人聚落与部分旧贵族仍在。武王死后，武庚又联合管、蔡等起事，周公出兵平定，进一步经营东方。牧野获胜之后，周对商旧地的控制，仍经历了王室安置、再度战争和地方治理的过程。","s":["《史记·周本纪》","《史记·鲁周公世家》"]},{"k":"史料说明","v":"《史记》成书远晚于商周之际，誓辞与倒戈叙事保存了后世对克商的讲述；兵力条目分别记录车辆与不同兵种。","s":["《史记·周本纪》"]}],"steps":[{"t":"武王继位后曾到盟津观兵，诸侯前来会合；这次集结结束后，周军返回西方，等待再度出兵的时机。","s":["《史记·周本纪》"]},{"t":"武王最终决定伐商，率军渡过黄河，经盟津向商都推进。参与的诸侯也带着各自的部队加入盟军。","s":["《史记·周本纪》"]},{"t":"甲子日早晨，周军抵达河南新乡北部一带（牧野）。武王在阵前誓师，随后命吕尚率勇士向商军挑战。","s":["《史记·周本纪》"]},{"t":"周军主力接着投入战斗。《周本纪》记商军发生倒戈，阵列溃乱，周军乘势向前推进。","s":["《史记·周本纪》"]},{"t":"帝辛退回商都，登上鹿台自焚。武王随后进入商都，处置商王室事务，伐商的军事胜利转入战后安排。","s":["《史记·殷本纪》","《史记·周本纪》"]}],"gloss":[],"cities":["丰镐","殷墟"],"people":["周武王","商帝辛","吕尚","周文王"],"src":["《史记·卷3·殷本纪》","《史记·卷4·周本纪》","《史记·卷33·鲁周公世家》"],"line":"周武王率诸侯联军在牧野击败商军，商纣自焚，商朝灭亡，周朝由此建立。","leaders":[{"side":"甲方","t":"周武王、吕尚。","s":["《史记·周本纪》"]},{"side":"乙方","t":"商帝辛。","s":["《史记·殷本纪》"]}],"short":"牧野","timeShort":"约前1046","placeShort":"河南新乡北部一带","sides":"周及盟军／商","result":"商王帝辛败亡","sideA":"甲方","sideB":"乙方"},{"name":"长勺之战","group":"第一组·先秦","tags":["战法典型"],"g":"部分待核","lat":36.3,"lon":117.7,"f":[{"k":"时间","v":"前684，鲁庄公十年春；正月为原书历月。","s":["《左传·庄公十年》"]},{"k":"地点","v":"山东省济南市莱芜区一带，古名长勺，具体定位有不同说法。〔待核〕","s":[]},{"k":"交战双方","v":"鲁国对齐国。","s":["《左传·庄公十年》"]},{"k":"起因","v":"齐桓公即位前，鲁国曾支持公子纠争夺齐国君位，齐鲁随后在乾时交战，鲁军失利。到了鲁庄公十年，齐军再次攻鲁，鲁庄公准备迎战。《左传》没有交代这次出兵的具体打算；两国此前的争位干预和军事冲突，构成了长勺交战的背景。","s":["《左传·庄公九年、十年》"]},{"k":"结果与影响","v":"鲁军在长勺击退齐军，保住了此次作战的主动。《左传》用曹刿与庄公的问答，把战前取信于民、交战时等待敌军士气衰减、追击前观察退军这几步连在一起。“一鼓作气”也出于这段记载。齐鲁之间的竞争仍在继续，齐桓公后来继续经营诸侯关系；长勺的胜利，留下的尤其是一段关于何时进攻、何时追击的战争叙述。","s":["《左传·庄公九年、十年》"]}],"steps":[{"t":"齐军入侵，曹刿请求见鲁庄公。他先询问国君平日如何处理衣食、祭祀与诉讼，再同意随军出战。","s":["《左传·庄公九年、十年》"]},{"t":"两军在山东济南莱芜一带（长勺）接战。鲁庄公准备击鼓进军，曹刿劝他稍等，鲁军暂时按兵。","s":["《左传·庄公九年、十年》"]},{"t":"齐军接连击鼓，第三次击鼓之后，曹刿才说可以进攻。鲁军随即出击，齐军败退。","s":["《左传·庄公九年、十年》"]},{"t":"鲁庄公打算立即追赶，曹刿再次制止。他下车查看齐军车辙，又登车远望齐军旗帜。","s":["《左传·庄公九年、十年》"]},{"t":"看见车辙杂乱、旗帜倒伏，曹刿判断齐军已经溃退，同意追击。战后他向庄公解释：进攻要看士气，追击还要防备敌军设伏。","s":["《左传·庄公九年、十年》"]}],"gloss":[],"cities":["曲阜","临淄"],"people":["齐桓公"],"src":["《左传·庄公九年、十年》"],"line":"齐军进攻鲁国，曹刿协助鲁庄公把握出击和追击时机，鲁军在长勺获胜。","leaders":[{"side":"甲方","t":"鲁庄公；曹刿随行出谋划策。","s":["《左传·庄公十年》"]},{"side":"乙方","t":"齐军，主将姓名原篇未载。","s":["《左传·庄公十年》"]}],"short":"长勺","timeShort":"前684","placeShort":"山东济南莱芜一带（定位待核）","sides":"鲁／齐","result":"鲁军获胜","sideA":"甲方","sideB":"乙方"},{"name":"城濮之战","group":"第一组·先秦","tags":["战法典型","关键转折"],"g":"部分待核","lat":35.6,"lon":115.3,"f":[{"k":"时间","v":"前632，鲁僖公二十八年四月己巳（原书历月日）。","s":["《左传·僖公二十八年》"]},{"k":"地点","v":"河南省濮阳市与山东省菏泽市鄄城县交界一带，古名城濮，具体定位有不同说法。〔待核〕","s":[]},{"k":"交战双方","v":"晋及齐、秦、宋等盟军对楚及陈、蔡等军。","s":["《左传·僖公二十八年》"]},{"k":"起因","v":"楚军围攻宋国，宋向晋求援。晋文公出兵攻打与楚关系密切的曹、卫，想借此牵动楚军，也争取齐、秦等国支持。楚成王主张收兵，子玉仍要求决战。援救宋国、改变诸侯结盟和争夺中原主导权，使晋楚两军逐步走向正面交锋。","s":["《左传·僖公二十七年、二十八年》"]},{"k":"结果与影响","v":"晋军获胜，宋国的围困得到解除。晋文公在践土召集诸侯，与周王室发生更密切的政治联系，晋在中原的主导地位由此确立。楚军虽败，子玉所部中军仍得以退走，楚国仍是晋的重要对手。战场上的陈、蔡先溃、晋军佯退和侧面夹击，与战后的诸侯会盟相接，显示军事胜负如何改变列国的结盟与权力格局。","s":["《左传·僖公二十七年、二十八年》"]}],"steps":[{"t":"晋军进入曹、卫，攻城并展开交涉。楚方试图以退兵交换晋军恢复曹、卫，两国未能谈妥。","s":["《左传·僖公二十七年、二十八年》"]},{"t":"晋军退避三舍，楚军继续追进。晋文公与将领商议后，在河南濮阳、山东鄄城交界一带（城濮）准备迎战。","s":["《左传·僖公二十七年、二十八年》"]},{"t":"交战时，胥臣先攻击楚军右翼的陈、蔡部队。陈、蔡军败退，使楚军一侧先出现缺口。","s":["《左传·僖公二十七年、二十八年》"]},{"t":"狐毛举旗佯退，栾枝让战车拖着柴草扬起尘土，制造晋军退走的景象，楚军随即向前追击。","s":["《左传·僖公二十七年、二十八年》"]},{"t":"晋军转而从侧面夹击追来的楚军，楚军左右两部分别受挫。子玉所领中军仍保持队伍，掩护退却。","s":["《左传·僖公二十七年、二十八年》"]},{"t":"晋军获胜后在战地停留整顿，随后与诸侯会盟于践土。子玉退军后受到楚王责问，最终自杀。","s":["《左传·僖公二十七年、二十八年》"]}],"gloss":[],"cities":["郢","曲阜","临淄"],"people":["晋文公","先轸","狐偃"],"src":["《左传·僖公二十七年、二十八年》"],"line":"晋文公救宋迎战楚军，城濮获胜后召集诸侯会盟，确立了晋国的霸主地位。","leaders":[{"side":"甲方","t":"晋文公、先轸、栾枝、胥臣、狐毛、狐偃。","s":["《左传·僖公二十八年》"]},{"side":"乙方","t":"子玉、子西、子上。","s":["《左传·僖公二十八年》"]}],"short":"城濮","timeShort":"前632","placeShort":"河南濮阳、山东鄄城交界一带（定位待核）","sides":"晋及盟军／楚及盟军","result":"楚军败退","sideA":"甲方","sideB":"乙方"},{"name":"柏举之战","group":"第一组·先秦","tags":["关键转折","战法典型"],"g":"部分待核","lat":31.0,"lon":114.6,"f":[{"k":"时间","v":"前506，鲁定公四年十一月（原书历月），随后吴军入郢。","s":["《左传·定公四年》"]},{"k":"地点","v":"湖北省东北部，古名柏举，有红安、麻城、汉川等不同定位说法。〔待核〕","s":[]},{"k":"交战双方","v":"吴、蔡、唐联军对楚。","s":["《左传·定公四年》"]},{"k":"起因","v":"吴楚长期交战，蔡、唐又因受到楚国压迫而转向吴国。《左传》记蔡侯受辱后求援，蔡、唐由此加入伐楚行动；《史记》则着重记伍子胥奔吴、推动吴王攻楚。吴国与盟友准备深入楚境，楚军必须在正面迎战和侧后截击之间协调行动。","s":["《左传·定公四年、五年》","《史记·伍子胥列传》"]},{"k":"结果与影响","v":"吴军攻入郢，楚王室失去都城，楚昭王被迫出走求援。秦后来出兵帮助楚国，吴国内部又发生夫概争位，越国也趁机攻吴，深入楚境的吴军最终撤离。楚昭王得以返回，楚国继续存在。柏举获胜打开了通向楚都的道路，但吴军占领都城之后，还要面对秦的援军、楚的反击以及本国后方的变动。","s":["《左传·定公四年、五年》"]},{"k":"史料说明","v":"《左传》详记吴、蔡、唐联军及夫概的作战，《史记》另叙伍子胥、孙武参与伐楚；两书叙述的重点不同。","s":["《左传·定公四年、五年》","《史记·伍子胥列传》","《史记·孙子吴起列传》"]}],"steps":[{"t":"吴军联合蔡、唐深入楚境，在汉水方向与楚军相持。沈尹戌提出绕到吴军后方、破坏其归路的计划，自己领兵执行。","s":["《左传·定公四年、五年》"]},{"t":"沈尹戌离开后，囊瓦改变原来的部署，向吴军推进。楚军接连受挫，退到湖北东北部（柏举）迎战。","s":["《左传·定公四年、五年》"]},{"t":"夫概请求先攻，吴王阖闾未同意。他仍率所部出击，楚军前阵溃乱，吴军主力随即跟进。","s":["《左传·定公四年、五年》"]},{"t":"楚军退到清发渡水，夫概等待其一部分渡过后发起攻击。渡河中的楚军再败，吴军继续追赶。","s":["《左传·定公四年、五年》"]},{"t":"沈尹戌回军救援，与吴军多次交战，最终伤重而死。吴军又在楚军进食时赶到，楚军被迫仓促撤走。","s":["《左传·定公四年、五年》"]},{"t":"吴军连续推进，进入楚都郢。楚昭王离开都城辗转避难，战事由柏举的正面交锋扩大为楚国腹地的危机。","s":["《左传·定公四年、五年》"]}],"gloss":[],"cities":["苏州（姑苏）","郢"],"people":["吴王阖闾","伍子胥","孙武","申包胥"],"src":["《左传·定公四年、五年》","《史记·卷65·孙子吴起列传》","《史记·卷66·伍子胥列传》"],"line":"吴军联合蔡、唐进攻楚国，在柏举获胜后一路追击入郢，楚昭王被迫出走。","leaders":[{"side":"甲方","t":"吴王阖闾、夫概；《史记》另记伍子胥、孙武参与伐楚。","s":["《左传·定公四年》","《史记·伍子胥列传》","《史记·孙子吴起列传》"]},{"side":"乙方","t":"囊瓦、沈尹戌；囊瓦率正面部队，沈尹戌另行迂回。","s":["《左传·定公四年》"]}],"short":"柏举","timeShort":"前506","placeShort":"湖北东北部（具体地点有争议）","sides":"吴、蔡、唐／楚","result":"吴胜并进占郢","sideA":"甲方","sideB":"乙方"},{"name":"桂陵之战","group":"第一组·先秦","tags":["战法典型"],"g":"部分待核","lat":35.2,"lon":115.0,"f":[{"k":"时间","v":"前353，为通行系年；邯郸围攻与归还另有跨年记载。","s":["《史记·六国年表》","《史记·孙子吴起列传》"]},{"k":"地点","v":"河南省长垣市、山东省菏泽市相关地区，古名桂陵，具体定位有不同说法。〔待核〕","s":[]},{"k":"交战双方","v":"齐国对魏国；赵国是被援救的一方。","s":["《史记·孙子吴起列传》"]},{"k":"起因","v":"魏军进攻赵国，围住河北邯郸，赵向齐求救。齐国任田忌为将，孙膑协助谋划。田忌原想直接赶赴赵国，孙膑提出，魏军主力在外，国内防备相对薄弱，攻向魏都便能迫使对方回援。齐军于是把救赵的行动转向魏国腹地，争取调动围城的魏军。","s":["《史记·孙子吴起列传》"]},{"k":"结果与影响","v":"齐军在桂陵击败魏军，救援赵国的行动取得战果。攻向魏国腹地，使围攻赵都的魏军不得不应对身后的威胁，成为后世“围魏救赵”的典型叙述。魏国此后仍有强大的军事力量，齐、赵、魏的竞争继续展开。关于邯郸何时陷落、何时归还，纪传和年表分别保存了相关记载，也让这次救援的战后进程显得更为复杂。","s":["《史记·孙子吴起列传》","《史记·六国年表》","《史记·赵世家》"]},{"k":"史料说明","v":"《孙子吴起列传》把桂陵获胜与赵围解除相连；《赵世家》《六国年表》另记魏攻取、归还邯郸的年份，各条纪年与解围过程的对应仍有疑问。〔待核〕","s":["《史记·孙子吴起列传》","《史记·赵世家》","《史记·六国年表》"]}],"steps":[{"t":"魏军围攻邯郸，赵国向齐求援。齐军准备出发时，田忌提出直接前往赵国迎战。","s":["《史记·孙子吴起列传》"]},{"t":"孙膑劝田忌攻击魏军必须回救的地方，把进军目标放在河南开封（大梁）方向。田忌采纳这一建议。","s":["《史记·孙子吴起列传》"]},{"t":"齐军进入魏境，向魏都施加压力。魏军于是离开原来的作战方向，回师应对齐军。","s":["《史记·孙子吴起列传》"]},{"t":"两军在桂陵交战，齐军击败魏军。《孙子吴起列传》把这一胜利与解除赵国压力相连。","s":["《史记·孙子吴起列传》"]},{"t":"此后赵、魏仍围绕邯郸归属交涉。《赵世家》《六国年表》另记魏取邯郸及后续归还的过程，战场胜利之后还有外交收尾。","s":["《史记·赵世家》","《史记·六国年表》"]}],"gloss":[],"cities":["临淄","邯郸","开封（汴州、东京、大梁）"],"people":["齐威王","魏惠王","田忌","孙膑","庞涓"],"src":["《史记·卷15·六国年表》","《史记·卷43·赵世家》","《史记·卷65·孙子吴起列传》"],"line":"魏军围攻赵都邯郸，齐军转攻魏国腹地，在桂陵击败回援的魏军，改变战局。","leaders":[{"side":"甲方","t":"田忌、孙膑。","s":["《史记·孙子吴起列传》"]},{"side":"乙方","t":"魏军，主将姓名在所引本传中未明载。","s":[]}],"short":"桂陵","timeShort":"前353","placeShort":"河南长垣、山东菏泽一带（定位待核）","sides":"齐／魏","result":"魏军战败","sideA":"甲方","sideB":"乙方"},{"name":"马陵之战","group":"第一组·先秦","tags":["战法典型","关键转折"],"g":"部分待核","lat":34.7,"lon":118.3,"f":[{"k":"时间","v":"前341，为通行系年，各篇王年与相对年数记法存在差异。","s":["《史记·六国年表》","《史记·孙子吴起列传》"]},{"k":"地点","v":"山东省临沂市郯城县、河南省濮阳市范县等地有不同定位说法，古名马陵。〔待核〕","s":[]},{"k":"交战双方","v":"齐国对魏国；韩国为此轮战争中受攻求援的一方。","s":["《史记·孙子吴起列传》"]},{"k":"起因","v":"魏与赵出兵攻韩，韩国向齐请求援助。齐国再次派田忌、孙膑出兵，进军方向仍指向河南开封（大梁），迫使魏军回师。桂陵之后，齐魏之间的军事竞争仍在继续。《孙子吴起列传》记庞涓认为齐军怯战，孙膑便利用这一判断，安排减灶示弱，诱使魏军加快追赶。","s":["《史记·孙子吴起列传》"]},{"k":"结果与影响","v":"魏军遭受重创，庞涓死亡，太子申被俘，齐国的军事声势上升。《史记》把齐军的减灶、魏军的轻兵追赶和马陵设伏连成一条作战经过：先改变敌将的判断，再利用追兵进入狭窄道路的机会进攻。魏国的王权仍然延续，但其与齐、秦等国竞争的处境发生变化。桂陵、马陵两次败仗，也成为《魏世家》叙述魏国由盛转衰的重要环节。","s":["《史记·孙子吴起列传》","《史记·魏世家》"]},{"k":"史料说明","v":"减灶及马陵伏击的细节主要见《孙子吴起列传》，营灶数字反映书中的诱敌计策，实际兵力尚缺独立核实。","s":["《史记·孙子吴起列传》"]}],"steps":[{"t":"齐军出兵救韩，进入魏国腹地。魏军转身回援，原先对韩的攻势变成追逐齐军的行动。","s":["《史记·孙子吴起列传》"]},{"t":"孙膑让齐军营灶逐日减少。庞涓看到灶数下降，认为齐军士卒大量逃亡，决定加紧追击。","s":["《史记·孙子吴起列传》"]},{"t":"庞涓留下步兵，带轻锐部队兼程追赶。魏军前锋与后续部队的距离随之拉开。","s":["《史记·孙子吴起列传》"]},{"t":"孙膑估计追兵夜间能够到达马陵，选择道路狭窄、两旁险阻的地段布置伏兵，等待魏军进入。","s":["《史记·孙子吴起列传》"]},{"t":"庞涓夜间到达伏击地，齐军发起攻击，魏军队伍陷入混乱。庞涓在败局中自杀，追击行动转为溃败。","s":["《史记·孙子吴起列传》"]},{"t":"齐军乘胜追击，俘获魏太子申。魏军失去重要统帅，齐军取得这一轮交战的胜利。","s":["《史记·孙子吴起列传》"]}],"gloss":[],"cities":["临淄","开封（汴州、东京、大梁）"],"people":["魏惠王","田忌","孙膑","庞涓"],"src":["《史记·卷15·六国年表》","《史记·卷44·魏世家》","《史记·卷65·孙子吴起列传》"],"line":"齐军以减灶诱使魏军追赶，在马陵设伏，庞涓死、太子申被俘，魏国遭受重创。","leaders":[{"side":"甲方","t":"田忌、孙膑。","s":["《史记·孙子吴起列传》"]},{"side":"乙方","t":"庞涓、太子申。","s":["《史记·孙子吴起列传》"]}],"short":"马陵","timeShort":"前341","placeShort":"山东郯城、河南范县等异说（待核）","sides":"齐／魏","result":"魏军败，庞涓死","sideA":"甲方","sideB":"乙方"},{"name":"长平之战","group":"第一组·先秦","tags":["关键转折","战法典型"],"g":"部分待核","lat":35.8,"lon":112.9,"f":[{"k":"时间","v":"前260，秦昭襄王四十七年；相关上党争夺始于此前。","s":["《史记·白起王翦列传》"]},{"k":"地点","v":"山西省晋城市高平市及丹河流域，古名长平。","s":["《史记·白起王翦列传》"]},{"k":"交战双方","v":"秦国对赵国。","s":["《史记·白起王翦列传》"]},{"k":"兵力与伤亡","v":"《史记·白起王翦列传》记赵军降卒四十万人，前后“斩首虏”四十五万人；前者指降卒，后者指全役杀俘合计，口径重叠。","s":["《史记·白起王翦列传》"]},{"k":"起因","v":"秦进攻韩国，攻取野王，使上党与韩国本土之间的通道被切断。上党守冯亭决定把土地交给赵国，赵廷接受，于是秦赵直接争夺这一地区。秦军进攻上党后，赵军驻守长平。廉颇在初战受损后转入固守，战事拖长，赵王对前线迟迟未能取胜越来越不满。","s":["《史记·白起王翦列传》","《史记·赵世家》"]},{"k":"结果与影响","v":"秦军赢得长平决战，赵国在上党的军队遭到毁灭性打击，大批投降士卒又被杀害。秦由此扩大了对上党的控制，赵国则必须重新组织防御。随后秦继续进攻邯郸，赵的抵抗和诸侯援军使战争延续。长平留下的后果，既有两国军事力量的变化，也有杀降造成的巨大人员损失；赵国此后仍延续数十年，直到秦再度大举进攻。","s":["《史记·白起王翦列传》","《史记·赵世家》"]},{"k":"史料说明","v":"书中“坑”记载的是大规模杀降，具体处死方式仍有讨论；降卒四十万与前后杀俘四十五万属于不同叙述层次。","s":["《史记·白起王翦列传》"]}],"steps":[{"t":"秦军攻入上党，赵军在山西高平（长平）迎战。廉颇所部初战损失将领与营垒，随后筑垒固守。","s":["《史记·白起王翦列传》"]},{"t":"秦国散布消息，声称只怕赵括。赵王换下廉颇，让赵括统军；秦则秘密以白起代王龁指挥，严禁泄露。","s":["《史记·白起王翦列传》","《史记·廉颇蔺相如列传》"]},{"t":"赵括改变固守的部署，出兵进攻。秦军佯装败退，把赵军引离营垒，再用坚固阵地挡住其攻势。","s":["《史记·白起王翦列传》"]},{"t":"白起派奇兵切断赵军后路，又以骑兵阻断各营联系。赵军被分成两部分，粮道也遭到截断。","s":["《史记·白起王翦列传》"]},{"t":"秦王到河内征发民众赴前线，并加紧截断赵国援兵与粮食。赵军困在包围中，饥饿日益严重。","s":["《史记·白起王翦列传》"]},{"t":"《白起王翦列传》记赵军绝食四十六日，分队反复突围，仍未成功。赵括亲率精锐出战，被秦军射杀。","s":["《史记·白起王翦列传》"]},{"t":"赵军余部投降。白起随后大规模杀害降卒，只放回少量年幼者，赵国因而损失大批军人。","s":["《史记·白起王翦列传》"]}],"gloss":[],"cities":["咸阳","邯郸"],"people":["秦昭襄王","白起","廉颇","赵括","范雎"],"src":["《史记·卷43·赵世家》","《史记·卷73·白起王翦列传》","《史记·卷81·廉颇蔺相如列传》"],"line":"秦赵争夺上党，白起切断赵军粮道并将其包围，赵军投降后遭到大规模杀戮。","leaders":[{"side":"甲方","t":"王龁先统军，白起随后接替。","s":["《史记·白起王翦列传》"]},{"side":"乙方","t":"廉颇、赵括；赵括继廉颇统军。","s":["《史记·廉颇蔺相如列传》"]}],"short":"长平","timeShort":"前260","placeShort":"山西晋城高平市","sides":"秦／赵","result":"赵军投降后遭杀戮","sideA":"甲方","sideB":"乙方"},{"name":"秦灭六国之战","group":"第一组·先秦","tags":["改朝换代","统一战争"],"g":"部分待核","lat":34.3,"lon":108.7,"f":[{"k":"时间","v":"前230—前221，从韩国灭亡至齐国投降。","s":["《史记·秦始皇本纪》"]},{"k":"地点","v":"河南、河北、山西、山东、湖北、安徽及辽宁等地，涉及新郑、邯郸、大梁、寿春、蓟、临淄与辽东。","s":["《史记·秦始皇本纪》"]},{"k":"交战双方","v":"秦国对韩、赵、魏、楚、燕、齐及赵代残余政权。","s":["《史记·秦始皇本纪》"]},{"k":"起因","v":"秦长期经营关中、巴蜀，逐步向东方扩张。秦王政掌权后，一面进攻诸侯，一面利用各国之间的矛盾。韩、赵、魏等国已多次与秦交战，各自的土地和军事力量受到削弱。秦接着把进攻推进到诸侯都城，逐国俘获其国君，最后将齐国也纳入统治，完成了连续十年的主要兼并。","s":["《史记·秦始皇本纪》"]},{"k":"结果与影响","v":"六国国君先后被俘，原来并立的王权被秦取代。秦王政称皇帝，在统一疆域内推行郡县治理，并着手整合文字、度量衡等制度。各地由征服转向治理，仍需处置旧王族、地方势力及抵抗力量。赵王迁被俘后尚有代王嘉，燕都失守后尚有辽东王室，说明秦统一的过程包含多次进攻与善后，直至齐王投降才完成主要兼并。","s":["《史记·秦始皇本纪》"]},{"k":"史料说明","v":"《秦始皇本纪》与《白起王翦列传》对俘楚王、项燕败亡及平定楚地的叙事分段不同，楚亡通行系年作前223年。","s":["《史记·秦始皇本纪》","《史记·白起王翦列传》"]}],"steps":[{"t":"前230年，内史腾率秦军攻韩，俘获韩王安。韩国王权覆灭，秦在其故地设置郡县。","s":["《史记·秦始皇本纪》"]},{"t":"前228年，秦军攻取河北邯郸，俘获赵王迁。赵公子嘉带领宗族退到代地，自立为代王，继续抵抗。","s":["《史记·秦始皇本纪》"]},{"t":"前226年，秦军攻下北京一带（蓟），燕王喜退往辽东。燕国失去原有都城，王室仍在东北继续活动。","s":["《史记·秦始皇本纪》"]},{"t":"前225年，王贲率军攻魏，用水灌河南开封（大梁）。魏王投降，秦军控制魏都与王室。","s":["《史记·秦始皇本纪》"]},{"t":"李信攻楚失利后，秦改派王翦、蒙武。前224至前223年，秦军击败楚军，俘获楚王，并继续平定楚地。","s":["《史记·秦始皇本纪》","《史记·白起王翦列传》"]},{"t":"前222年，王贲进攻辽东，俘获燕王喜；随后又攻代，俘获代王嘉，燕、赵王室残余势力相继结束。","s":["《史记·秦始皇本纪》"]},{"t":"前221年，王贲从北面进攻齐国，俘齐王建。秦王政随后采用皇帝称号，建立统一的帝国政权。","s":["《史记·秦始皇本纪》"]}],"gloss":[],"cities":["咸阳","新郑","邯郸","开封（汴州、东京、大梁）","郢","北京（蓟、幽州、燕京、中都、大都、北平、京师）","临淄"],"people":["秦始皇","王翦","李牧","燕王喜","太子丹"],"src":["《史记·卷6·秦始皇本纪》","《史记·卷73·白起王翦列传》","《史记·卷81·廉颇蔺相如列传》"],"line":"秦军先后攻灭韩赵魏楚燕齐，结束六国分立的局面，秦王政由此建立统一帝国。","leaders":[{"side":"甲方","t":"内史腾、王翦、王贲、李信、蒙武。","s":["《史记·秦始皇本纪》","《史记·白起王翦列传》"]},{"side":"乙方","t":"李牧、司马尚、项燕等；各分属不同国家与阶段。","s":["《史记·白起王翦列传》","《史记·廉颇蔺相如列传》"]}],"short":"秦灭六国","timeShort":"前230—前221","placeShort":"河南、河北、山西、山东、湖北、安徽等","sides":"秦／韩赵魏楚燕齐","result":"六国相继灭亡","sideA":"甲方","sideB":"乙方"},{"name":"巨鹿之战","group":"第二组·秦汉","tags":["改朝换代","关键转折"],"g":"部分待核","lat":37.1,"lon":115.0,"f":[{"k":"时间","v":"前207，秦二世三年；秦当时以十月为岁首。","s":["《史记·项羽本纪》"]},{"k":"地点","v":"河北省邢台市平乡县一带，古名巨鹿，具体城址与围城范围仍有定位问题。〔待核〕","s":[]},{"k":"交战双方","v":"项羽所领楚军、赵军及诸侯援军对秦军。","s":["《史记·项羽本纪》"]},{"k":"兵力与伤亡","v":"《史记·项羽本纪》记黥布、蒲将军先率两万人渡河，这是楚军先遣部队的数字，项羽随后率主力跟进。","s":["《史记·项羽本纪》"]},{"k":"起因","v":"秦将章邯在定陶击败项梁后，转兵进攻赵国。赵王歇与张耳退守河北平乡一带（巨鹿），王离等围城，章邯在外围修筑甬道，向围城部队输送粮食。楚怀王派宋义、项羽救赵，又命刘邦西进。巨鹿城外聚集了多路诸侯军，但各军起初都没有打破秦军的包围。","s":["《史记·项羽本纪》"]},{"k":"结果与影响","v":"巨鹿解围，秦军在关东的重要作战力量遭到重创。项羽凭战功取得诸侯军的主导权，又在后续交战和谈判中接受章邯投降。秦廷由此失去镇压东方诸侯的主要支柱。另一方向，刘邦继续向关中推进，秦王子婴后来投降，秦朝覆亡。巨鹿的胜利与入关受降前后相接，反秦诸军也随之进入争夺战后秩序的新阶段。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]}],"steps":[{"t":"楚援军行至安阳，宋义停留不进。项羽与他发生争执，杀死宋义，控制军队，随后得到楚怀王任命。","s":["《史记·项羽本纪》"]},{"t":"项羽先派黥布、蒲将军率两万人渡河。先遣军交战后，赵方继续求援，项羽决定带主力渡河。","s":["《史记·项羽本纪》"]},{"t":"楚军渡河后沉船、破釜，烧掉营舍，只携带三日粮食。项羽将军队投入对秦军的连续攻击。","s":["《史记·项羽本纪》"]},{"t":"楚军多次作战，切断秦军输粮的甬道。王离的围城部队受到打击，苏角战死，王离被俘，涉间自焚。","s":["《史记·项羽本纪》"]},{"t":"在旁观望的诸侯军看到楚军获胜，转而服从项羽。巨鹿的围城体系被打破，项羽取得联军的主导地位。","s":["《史记·项羽本纪》"]},{"t":"章邯率另一支秦军继续与项羽相持，后来派人谈判。双方又经交战与交涉，章邯最终率部投降。","s":["《史记·项羽本纪》"]}],"gloss":[],"cities":["咸阳","邯郸"],"people":["项羽","章邯","秦二世","汉高祖"],"src":["《史记·卷7·项羽本纪》","《史记·卷8·高祖本纪》"],"line":"项羽渡河救赵，击破巨鹿的秦军围城体系，随后迫使章邯投降，秦军主力受挫。","leaders":[{"side":"甲方","t":"项羽、黥布、蒲将军；张耳、陈余分别参与守城及外围行动。","s":["《史记·项羽本纪》"]},{"side":"乙方","t":"王离、涉间等围城，章邯率部在外围输粮支援。","s":["《史记·项羽本纪》"]}],"short":"巨鹿","timeShort":"前207","placeShort":"河北邢台平乡县一带","sides":"楚、赵及诸侯／秦","result":"王离军败，章邯后降","sideA":"甲方","sideB":"乙方"},{"name":"彭城之战","group":"第二组·秦汉","tags":["关键转折"],"g":"部分待核","lat":34.3,"lon":117.2,"f":[{"k":"时间","v":"前205，汉二年四月（原书历月）。","s":["《史记·项羽本纪》"]},{"k":"地点","v":"江苏省徐州市及周边，古名彭城，追击涉及睢水等地。","s":["《史记·项羽本纪》"]},{"k":"交战双方","v":"项羽的楚军对刘邦率领的汉军及诸侯联军。","s":["《史记·项羽本纪》"]},{"k":"兵力与伤亡","v":"《史记·项羽本纪》记汉及诸侯军共五十六万人，项羽回援精兵三万人；分别是联军集结总数和楚军此次回援部队数。","s":["《史记·项羽本纪》"]},{"k":"起因","v":"项羽分封诸侯后，各地很快重新发生战争。项羽向齐地用兵，刘邦则从关中东进，联合诸侯反楚。趁项羽主力在外，汉及诸侯军进入江苏徐州（彭城），直取西楚的统治中心。项羽得知消息，留下部队继续在齐地作战，亲自带精锐回师，准备夺回彭城。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]},{"k":"结果与影响","v":"项羽夺回彭城，汉及诸侯联军的东进攻势被击溃。刘邦损失部队，家属被俘，盟友关系也受到冲击，未能通过占领楚都迅速结束战争。汉仍控制关中，能够补充兵员与物资，退到荥阳后又建立防线。楚汉战争于是进入长期相持；项羽的快速回师扭转了这一轮局势，刘邦随后仍有机会依靠后方和各路盟军重新组织进攻。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]},{"k":"史料说明","v":"《项羽本纪》分别叙述谷、泗水的杀伤和睢水溺亡，属于追击途中不同阶段的战果记录，伤亡总数尚缺独立核实。","s":["《史记·项羽本纪》"]}],"steps":[{"t":"汉与诸侯联军进入彭城，控制城中府库。项羽从齐地抽出精锐，迅速向南回援，试图打击尚未稳住阵地的联军。","s":["《史记·项羽本纪》"]},{"t":"楚军经鲁地、胡陵，转到萧县方向，从彭城西面发起进攻。清晨交战后，汉军向东退却。","s":["《史记·项羽本纪》"]},{"t":"到中午，楚军已将汉军击破。败军向谷水、泗水方向逃散，楚军紧追，使城内外的溃退继续扩大。","s":["《史记·项羽本纪》"]},{"t":"汉军又被追至睢水一带，大批士卒落水。《项羽本纪》分段记载沿途杀伤与溺亡，联军队伍难以重新集结。","s":["《史记·项羽本纪》"]},{"t":"刘邦带少数骑兵脱出，部分家属落入楚军手中。诸侯见汉军失利，原来的联合阵线也开始动摇。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]},{"t":"刘邦沿途收拢散兵，退到河南荥阳一线。关中的补充兵员随后到来，汉军重新组织防御，与楚军继续相持。","s":["《史记·高祖本纪》"]}],"gloss":[],"cities":["咸阳","长安"],"people":["汉高祖","项羽","吕后"],"src":["《史记·卷7·项羽本纪》","《史记·卷8·高祖本纪》"],"line":"刘邦率诸侯联军进入彭城，项羽从齐地回师突击，汉军败退，楚汉战争继续。","leaders":[{"side":"甲方","t":"项羽。","s":["《史记·项羽本纪》"]},{"side":"乙方","t":"汉高祖及诸侯联军各部。","s":["《史记·高祖本纪》"]}],"short":"彭城","timeShort":"前205","placeShort":"江苏徐州","sides":"楚／汉及诸侯联军","result":"汉联军败退","sideA":"甲方","sideB":"乙方"},{"name":"垓下之战","group":"第二组·秦汉","tags":["改朝换代","关键转折"],"g":"部分待核","lat":33.3,"lon":117.6,"f":[{"k":"时间","v":"前202，汉五年。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]},{"k":"地点","v":"安徽省宿州市灵璧县及蚌埠市固镇县等地有不同定位说法，古名垓下；项羽随后经东城到乌江。〔待核〕","s":[]},{"k":"交战双方","v":"汉及韩信、彭越等协同军对项羽的楚军。","s":["《史记·高祖本纪》"]},{"k":"兵力与伤亡","v":"《史记·项羽本纪》记项羽夜间突围骑兵八百余人，汉派灌婴率五千骑追赶；分别是突围和追击部队的数字。","s":["《史记·项羽本纪》"]},{"k":"起因","v":"楚汉在荥阳、成皋一带长期相持，彭越等又在楚军后方活动，使项羽的补给承受压力。双方一度约定以鸿沟为界，刘邦随后听从张良、陈平建议继续追击，却在固陵受挫。韩信、彭越当时尚未会师，刘邦必须先谈妥分地与协同，才能集中各路军队围攻楚军。","s":["《史记·高祖本纪》"]},{"k":"结果与影响","v":"项羽主力解体，统帅死亡，西楚失去了继续争夺天下的军事支柱。刘邦接收楚地，取得全国政治格局中的主导地位，随后在诸侯拥戴下称帝，汉帝国由此确立。韩信、彭越等仍以诸侯身份掌握封地，新的朝廷还要处理皇帝与异姓诸侯之间的关系。垓下合围结束了楚汉之间的主要决战，也留下一个需要重新整合地方权力的战后局面。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]}],"steps":[{"t":"刘邦追至固陵，韩信、彭越未及时会合，汉军被楚军反击，只得筑垒自守。刘邦向张良询问应对办法。","s":["《史记·高祖本纪》"]},{"t":"张良建议明确战后的分地安排，争取韩信、彭越进军。刘邦遣使约定，各路军队随后向楚军集中。","s":["《史记·高祖本纪》"]},{"t":"汉及诸侯军会合，逼近安徽宿州一带（垓下）。韩信指挥前军，与其他部队相继投入作战，楚军退入营垒。","s":["《史记·高祖本纪》"]},{"t":"楚军兵少粮乏，被汉军多重包围。《项羽本纪》记夜间四面传来楚歌，项羽以为汉已尽得楚地。","s":["《史记·项羽本纪》"]},{"t":"项羽带骑兵夜间突围，汉军随后派骑兵追赶。项羽渡淮后所部继续减少，在东城一带又与追兵交战。","s":["《史记·项羽本纪》"]},{"t":"项羽最终到达乌江，放弃渡江，自杀身亡。汉军继续收取楚地，西楚原有的军事组织随之瓦解。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]}],"gloss":[],"cities":["长安"],"people":["汉高祖","项羽","韩信","张良"],"src":["《史记·卷7·项羽本纪》","《史记·卷8·高祖本纪》"],"line":"汉及诸侯军会合垓下，项羽在重围中突围后自杀，西楚败亡，刘邦取得主导地位。","leaders":[{"side":"甲方","t":"汉高祖、韩信、刘贾、周勃等；彭越等从其他方向参与会合。","s":["《史记·高祖本纪》"]},{"side":"乙方","t":"项羽。","s":["《史记·项羽本纪》"]}],"short":"垓下","timeShort":"前202","placeShort":"安徽宿州灵璧等异说（待核）","sides":"汉及诸侯／楚","result":"楚军溃，项羽后自杀","sideA":"甲方","sideB":"乙方"},{"name":"白登之战","group":"第二组·秦汉","tags":["边疆与对外"],"g":"部分待核","lat":40.1,"lon":113.4,"f":[{"k":"时间","v":"前200，汉高祖七年。","s":["《史记·高祖本纪》","《史记·匈奴列传》"]},{"k":"地点","v":"山西省大同市东北白登山一带，古名白登，具体围困范围仍有定位问题。〔待核〕","s":[]},{"k":"交战双方","v":"汉对匈奴；韩王信投向匈奴是白登之战的背景，与汉匈主力接战是两件事。","s":["《史记·匈奴列传》"]},{"k":"兵力与伤亡","v":"《史记·匈奴列传》记汉军共三十二万人、多为步兵，冒顿以四十万骑围白登；汉方数字是北征全军，白登先行部队另属其中一部分。","s":["《史记·匈奴列传》"]},{"k":"起因","v":"韩王信在北边与匈奴交战，后来转而反汉，与匈奴相联。汉高祖亲自北征，击破部分敌军后继续追赶。时值严冬，汉军遭受冻伤，匈奴又隐藏精锐、让老弱出现在汉军面前。刘邦据此继续深入，先行部队与后续步兵逐渐拉开距离，向山西大同一带（平城）推进。","s":["《史记·匈奴列传》","《史记·韩信卢绾列传》"]},{"k":"结果与影响","v":"汉高祖脱离白登，北征却未能迫使匈奴服从。战后，汉廷通过和亲与边境防守处理双方关系，皇室婚姻和物资赠送成为外交安排的一部分。韩王信反叛引出的军事危机，显示汉初诸侯问题与边疆关系彼此牵连。白登围困又暴露出严寒、敌情误判和部队脱节造成的危险；皇帝先行，后续步兵未齐，给匈奴骑兵留下了包围的机会。","s":["《史记·匈奴列传》"]},{"k":"史料说明","v":"《匈奴列传》详记厚赠阏氏，《陈丞相世家》称陈平以奇计解围，又说计谋秘而未泄，两篇对解围过程保留的信息不同。","s":["《史记·匈奴列传》","《史记·陈丞相世家》"]}],"steps":[{"t":"汉高祖北上追击，匈奴以老弱示人，精锐骑兵隐藏在后。汉军判断敌方可追，继续向平城前进。","s":["《史记·匈奴列传》"]},{"t":"刘邦先到平城，后续步兵尚未全部抵达。冒顿单于出动骑兵，把刘邦所部包围在白登。","s":["《史记·匈奴列传》"]},{"t":"汉军被围七日，城外后续部队与被围军队联系受阻，粮食与救援都难以送入，局势十分紧迫。","s":["《史记·匈奴列传》"]},{"t":"《匈奴列传》记汉方暗中厚赠单于阏氏；《陈丞相世家》则记陈平出奇计解围，具体计谋未公开。","s":["《史记·匈奴列传》","《史记·陈丞相世家》"]},{"t":"冒顿因援军未至等原因产生疑虑，围阵开放一角。汉军张弓戒备，从缺口退出，与大部队会合。","s":["《史记·匈奴列传》"]},{"t":"汉军脱离包围后南撤。此后汉廷通过刘敬等人与匈奴交涉，逐渐实行和亲，边境政策也作出调整。","s":["《史记·匈奴列传》"]}],"gloss":[],"cities":["长安","平城"],"people":["汉高祖","陈平"],"src":["《史记·卷8·高祖本纪》","《史记·卷56·陈丞相世家》","《史记·卷93·韩信卢绾列传》","《史记·卷110·匈奴列传》"],"line":"汉高祖北征时在白登遭匈奴围困，七日后脱险，汉廷随后以和亲处理边境关系。","leaders":[{"side":"甲方","t":"汉高祖；陈平参与解围谋划。","s":["《史记·陈丞相世家》"]},{"side":"乙方","t":"冒顿单于。","s":["《史记·匈奴列传》"]}],"short":"白登","timeShort":"前200","placeShort":"山西大同东北一带","sides":"汉／匈奴","result":"汉高祖被围后脱出","sideA":"甲方","sideB":"乙方"},{"name":"漠北之战","group":"第二组·秦汉","tags":["边疆与对外"],"g":"部分待核","lat":47.0,"lon":107.0,"f":[{"k":"时间","v":"前119，汉武帝元狩四年。","s":["《史记·卫将军骠骑列传》"]},{"k":"地点","v":"主要在今蒙古国境内，涉及漠北多个战场；寘颜山、狼居胥山等古地名的现代对应有不同说法。〔待核〕","s":[]},{"k":"交战双方","v":"汉对匈奴。","s":["《史记·卫将军骠骑列传》"]},{"k":"兵力与伤亡","v":"《史记·卫将军骠骑列传》记卫青、霍去病各领五万骑；卫青一路“斩捕”一万九千，霍去病一路记斩获七万零四百四十三级，属于各路所报杀俘战果。","s":["《史记·卫将军骠骑列传》"]},{"k":"起因","v":"汉武帝时期，汉军先后在河南地、河西作战，汉匈双方的活动范围发生变化。前119年，汉廷组织大规模骑兵远征，准备越过沙漠寻找匈奴主力。卫青、霍去病分别统军，后方还须征集大量马匹、粮食与运输人员。两路军队进入辽阔的漠北，能否找到敌军及维持补给，成为这次行动的关键。","s":["《史记·匈奴列传》","《史记·卫将军骠骑列传》"]},{"k":"结果与影响","v":"汉军分别击败单于与左贤王所部，匈奴主力向更北方活动，漠南一带的军事形势发生变化。远征同时消耗了大量马匹和物资，后续继续出击受到供给能力限制。卫青一路以车阵立足，再借骑兵合围；霍去病一路持续深入，打击另一支匈奴主力。两路作战共同改变汉匈力量布局，也显示远距离骑兵战争必须依赖后方运输和马匹补充。","s":["《史记·匈奴列传》","《史记·卫将军骠骑列传》"]},{"k":"史料说明","v":"狼居胥等古地名的现代对应及两路行军范围仍有讨论；书中战果记录来自不同部队的作战统计。","s":["《史记·卫将军骠骑列传》"]}],"steps":[{"t":"汉廷原拟安排两路军队的出发方向，得到俘虏提供的单于位置消息后调整部署。卫青从定襄出发，霍去病从代郡出发。","s":["《史记·卫将军骠骑列传》"]},{"t":"卫青深入后遇到单于军，先用武刚车环绕成营，派骑兵在外迎战，稳住阵地，准备承受匈奴进攻。","s":["《史记·卫将军骠骑列传》"]},{"t":"交战中风沙大作，汉军从左右两侧包围。单于发现汉军兵势仍强，带骑兵向西北脱离战场。","s":["《史记·卫将军骠骑列传》"]},{"t":"卫青追至赵信城，取得当地储粮供军食用，随后烧掉余粮回师。未能及时会合的李广、赵食其部受到军法追问，李广自杀。","s":["《史记·卫将军骠骑列传》"]},{"t":"另一方向，霍去病进攻左贤王部，继续深入漠北。《史记》记其到达狼居胥、姑衍等地，并举行封禅仪式。","s":["《史记·卫将军骠骑列传》"]},{"t":"两路军队分别回师，取得大量杀俘战果，也损失许多马匹。深入沙漠以北的作战，对汉朝的运输和马匹储备造成沉重负担。","s":["《史记·匈奴列传》","《史记·卫将军骠骑列传》"]}],"gloss":[],"cities":["长安"],"people":["汉武帝","卫青","霍去病","李广"],"src":["《史记·卷110·匈奴列传》","《史记·卷111·卫将军骠骑列传》"],"line":"卫青、霍去病分路深入漠北，打击单于和左贤王部，远征也耗费大量马匹物资。","leaders":[{"side":"甲方","t":"卫青、霍去病；李广、赵食其等分隶具体行军序列。","s":["《史记·卫将军骠骑列传》"]},{"side":"乙方","t":"伊稚斜单于、左贤王等；分别迎战两路汉军。","s":["《史记·匈奴列传》"]}],"short":"漠北","timeShort":"前119","placeShort":"今蒙古国境内等地","sides":"汉／匈奴","result":"汉两路军击败所遇匈奴军","sideA":"甲方","sideB":"乙方"},{"name":"昆阳之战","group":"第二组·秦汉","tags":["改朝换代","攻城守城"],"g":"部分待核","lat":33.6,"lon":113.4,"f":[{"k":"时间","v":"23，更始元年六月为决战月（原书历月）。","s":["《后汉书·光武帝纪上》"]},{"k":"地点","v":"河南省平顶山市叶县，古名昆阳。","s":["《后汉书·光武帝纪上》"]},{"k":"交战双方","v":"更始政权所属绿林诸部及刘秀军对新朝军。","s":["《后汉书·光武帝纪上》"]},{"k":"兵力与伤亡","v":"《后汉书·光武帝纪上》先称新军“将兵百万”，又记“甲士四十二万”，昆阳守军八九千；分别是全军概称、甲士和城内守军的记数。","s":["《后汉书·光武帝纪上》"]},{"k":"起因","v":"新朝末年，各地相继起兵。刘玄被拥立为更始帝，刘縯等围攻南阳宛城，刘秀在颍川一带作战。王莽派王邑、王寻统率大军南下，想压倒更始军。严尤主张直接进攻对方的重要据点宛城，王邑却坚持先拿下河南叶县（昆阳），使一座小城成为大军围攻的目标。","s":["《后汉书·光武帝纪上》"]},{"k":"结果与影响","v":"新军围城失败，王寻战死，大批部队溃散，新朝用重兵压服更始军的计划落空。更始军得以扩大行动，随后起兵者进入长安，王莽被杀，新朝覆亡。昆阳时刘秀仍属更始军，刘玄的朝廷是反新力量中的重要政治中心；刘秀后来另在25年称帝，建立东汉。昆阳打开了继续进军的局面，起兵各部之间的权力争夺则在战后继续发展。","s":["《后汉书·光武帝纪上》","《汉书·王莽传下》"]},{"k":"史料说明","v":"同篇对新军有百万、甲士四十二万、围城先至约十万等不同层次的数字，分别对应全军、兵种和先到部队。","s":["《后汉书·光武帝纪上》"]}],"steps":[{"t":"新军接近昆阳，城内有人想分散退走。刘秀主张集中兵力，认为分散后更容易被分别攻破，守军遂决定据城抵抗。","s":["《后汉书·光武帝纪上》"]},{"t":"王凤、王常留守昆阳，刘秀与宗佻、李轶等带少数骑兵趁夜出城，到郾、定陵收集兵力，准备从外部解围。","s":["《后汉书·光武帝纪上》"]},{"t":"王邑把军队集中在城下，用冲车、楼车和地道进攻。城中一度请求投降，王邑仍要强攻，继续围城。","s":["《后汉书·光武帝纪上》"]},{"t":"刘秀集合援军返回，先率一部迎击新军。接连交战得手后，援军信心增加，向围城军推进。","s":["《后汉书·光武帝纪上》"]},{"t":"刘秀率敢死部队渡水，冲击王邑、王寻的中坚。新军其他营伍未能及时应援，王寻战死，指挥开始崩解。","s":["《后汉书·光武帝纪上》"]},{"t":"昆阳守军同时出击，新军大乱。暴风雨与滍水上涨又使逃兵溺亡，王邑带少数随从退走，围城遂解。","s":["《后汉书·光武帝纪上》"]}],"gloss":[],"cities":["长安","洛阳（秦汉至隋唐）"],"people":["汉光武帝","新帝王莽","刘玄","刘縯","王邑","王寻","王凤","王常","严尤"],"src":["《后汉书·卷1上·光武帝纪上》","《汉书·卷99下·王莽传下》"],"line":"新军围攻昆阳，刘秀出城集结援军，与守军合击破围，新朝南下的攻势受挫。","leaders":[{"side":"甲方","t":"刘秀、王凤、王常；此时刘秀尚未称帝。","s":["《后汉书·光武帝纪上》"]},{"side":"乙方","t":"王邑、王寻、严尤、陈茂。","s":["《后汉书·光武帝纪上》"]}],"short":"昆阳","timeShort":"23","placeShort":"河南平顶山叶县","sides":"更始军／新军","result":"新军败，王寻死","sideA":"甲方","sideB":"乙方"},{"name":"官渡之战","group":"第三组·三国至南北朝","tags":["战法典型","关键转折"],"g":"部分待核","lat":34.8,"lon":114.0,"f":[{"k":"时间","v":"200，汉献帝建安五年，决战在当年秋冬。","s":["《三国志·武帝纪》"]},{"k":"地点","v":"河南省郑州市中牟县及周边，古名官渡；前期交战在白马、延津，袭粮地点为乌巢。","s":["《三国志·武帝纪》"]},{"k":"交战双方","v":"控制汉廷的曹操军对袁绍军，双方当时均非已经建立的魏、蜀、吴国家。","s":["《三国志·武帝纪》"]},{"k":"兵力与伤亡","v":"《三国志·武帝纪》记袁军十余万人，曹军“不满万，伤者十二三”；这是该纪所记对阵兵力与曹军伤员比例，裴松之直接质疑曹军人数过少。","s":["《三国志·武帝纪及裴松之注》"]},{"k":"起因","v":"袁绍击败公孙瓒后，在河北形成强大势力，准备渡过黄河向南进攻。曹操则依托许县的汉廷及其控制地区，守卫通向河南腹地的道路。袁绍内部对进攻时机和部署存在争论，最终仍决定南下。两军从黄河渡口展开争夺，逐渐转入河南中牟（官渡）附近的长期对峙。","s":["《三国志·武帝纪及裴松之注》","《三国志·袁绍传》"]},{"k":"结果与影响","v":"曹操守住官渡，击破袁绍南下的主力，黄河两岸的力量对比发生转折。袁绍退回河北后仍有地盘和军队，曹操又经过多年的战争，才逐步攻取袁氏控制地区。白马、延津的机动交战，官渡营垒的长期攻防，以及乌巢粮屯被焚，构成这次胜负的先后环节；粮食、情报与袁军内部的分裂，都直接影响了决战的结果。","s":["《三国志·武帝纪及裴松之注》","《三国志·袁绍传》"]},{"k":"史料说明","v":"裴松之从曹军能分兵出击、双方营垒相持等情况，质疑“不满万”的记载，认为其中有突出曹操以少获胜的叙事倾向。","s":["《三国志·武帝纪及裴松之注》"]}],"steps":[{"t":"袁绍派颜良攻白马，曹操采纳荀攸建议，先佯装向延津渡河，再迅速回救白马。张辽、关羽出击，颜良被斩，白马解围。","s":["《三国志·武帝纪及裴松之注》","《三国志·荀攸传》","《三国志·关羽传》"]},{"t":"曹操迁走白马居民，沿河西撤。文丑等率军追来，曹军以辎重诱其争抢，趁阵形混乱反击，文丑战死。","s":["《三国志·武帝纪及裴松之注》"]},{"t":"双方主力在官渡筑垒相持。袁军堆土山、挖地道逼近曹营，曹军用器械和对应工事防守，争夺持续数月。","s":["《三国志·武帝纪及裴松之注》"]},{"t":"曹军粮食紧张，曹操一度考虑退回许县。荀彧劝其坚守，徐晃、史涣等又出击焚烧袁军运粮车辆。","s":["《三国志·武帝纪及裴松之注》"]},{"t":"许攸离开袁绍投奔曹操，透露粮屯情况。曹操留下曹洪等守营，亲率步骑五千连夜向乌巢进发。","s":["《三国志·武帝纪及裴松之注》"]},{"t":"曹操到乌巢后纵火进攻。袁绍同时遣军救粮，又令张郃、高览攻击曹营，想趁曹操离营打破其防线。","s":["《三国志·武帝纪及裴松之注》","《三国志·张郃传》"]},{"t":"曹营没有被攻破，乌巢守军却遭击溃。张郃、高览转而投曹，袁军随之溃退，袁绍带少数骑兵渡河北返。","s":["《三国志·武帝纪及裴松之注》","《三国志·张郃传》"]}],"gloss":[{"t":"《三国演义》以一场戏剧性会面表现许攸泄露乌巢粮情；《武帝纪》记许攸投曹并提供袭粮建议，保存的对话与小说写法不同。","s":["《三国演义·第三十回》","《三国志·武帝纪及裴松之注》"]},{"t":"《三国演义》写关羽斩颜良、诛文丑；《关羽传》明记关羽斩颜良，《武帝纪》叙文丑战死，未将其死归于关羽。","s":["《三国演义·第二十五回》","《三国演义·第二十六回》","《三国志·关羽传》","《三国志·武帝纪及裴松之注》"]}],"cities":["许昌","邺城","洛阳（秦汉至隋唐）"],"people":["曹操","袁绍","汉献帝","荀攸","曹仁","徐晃","张辽","张郃","关羽"],"src":["《三国志·卷1·武帝纪》及裴松之注","《三国志·卷6·袁绍传》","《三国志·卷10·荀攸传》","《三国志·卷17·张郃传》","《三国志·卷36·关羽传》"],"line":"曹操与袁绍在官渡相持，夜袭乌巢焚毁袁军粮屯，袁军溃退，北方局势转折。","leaders":[{"side":"甲方","t":"曹操、荀攸、曹仁、徐晃、张辽等，各部任务不同。","s":["《三国志·武帝纪》","《三国志·荀攸传》"]},{"side":"乙方","t":"袁绍、颜良、文丑、淳于琼、张郃、高览。","s":["《三国志·武帝纪》"]}],"short":"官渡","timeShort":"200","placeShort":"河南郑州中牟县","sides":"曹操／袁绍","result":"袁军败退","sideA":"甲方","sideB":"乙方"},{"name":"赤壁之战","group":"第三组·三国至南北朝","tags":["水战","关键转折"],"g":"部分待核","lat":29.9,"lon":113.6,"f":[{"k":"时间","v":"208，汉献帝建安十三年冬。","s":["《三国志·武帝纪》","《三国志·周瑜传》"]},{"k":"地点","v":"湖北省咸宁市赤壁市赤壁镇为通行定位，嘉鱼县等地另有定位说法；黄冈的黄州赤壁是文学纪念地。〔待核〕","s":["关于蒲圻说与黄州赤壁的区分"]},{"k":"交战双方","v":"孙权、刘备联盟对曹操军。","s":["《三国志·周瑜传》"]},{"k":"兵力与伤亡","v":"《三国志·周瑜传》裴注引《江表传》，记曹操来信自称水步八十万，孙权已选三万人交周瑜等率领；分别是来信声称和孙权此次拨军的数字。","s":["《三国志·周瑜、鲁肃传及裴松之注》"]},{"k":"起因","v":"曹操南征荆州，刘琮投降，刘备在败退后寻求与孙权合作。曹操接收荆州军队和舟船，继续沿长江东下，直接威胁孙权控制的江东。孙权阵营围绕迎降或抵抗展开争论，鲁肃、周瑜主张迎战，诸葛亮也参与结盟交涉。孙权最终派军与刘备联合，在长江中游阻击曹军。","s":["《三国志·周瑜、鲁肃传及裴松之注》","《三国志·诸葛亮传及裴松之注》"]},{"k":"结果与影响","v":"曹操此次南征未能控制江东，孙权保住根据地，刘备也从败退中获得重新发展的空间。战后周瑜等继续争夺江陵，刘备逐渐占有荆州部分地区，三方势力开始重新布局。后来魏、蜀、吴先后建国，才形成三国并立。赤壁使曹操沿江东进的攻势中止，也让孙刘联盟有机会把战场胜利转化为对长江流域土地与人口的控制。","s":["《三国志·周瑜、鲁肃传及裴松之注》","《三国志·先主传》"]},{"k":"史料说明","v":"《武帝纪》着重记疾疫和撤军，《周瑜传》详叙黄盖火攻；裴注引曹操致孙权书，又有曹操自称烧船的说法。战场具体定位另有赤壁市、嘉鱼等不同意见。","s":["《三国志·武帝纪及裴松之注》","《三国志·周瑜、鲁肃传及裴松之注》"]}],"steps":[{"t":"孙权决定抵抗，派周瑜、程普率军与刘备会合。孙刘军沿江迎击曹操，双方在湖北长江中游（赤壁）相遇。","s":["《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"《周瑜传》记曹军已有疾疫，初次交战又失利，退到江北。孙刘军驻在南岸，两军隔江相持。","s":["《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"黄盖看到曹军舟船首尾相接，向周瑜建议火攻。他准备装满薪草、浇油的船只，另配小船，方便点火后脱离。","s":["《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"黄盖先送信表示愿意投降，再率船向曹军靠近。曹军以为来船归降，没有及时阻断其接近。","s":["《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"火船接近后同时点燃，风势猛烈，火焰从舟船蔓延到岸上营落。曹军人马烧伤、溺亡，水陆营阵陷入混乱。","s":["《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"孙刘军乘势追击，曹操撤往江陵方向，留曹仁等守江陵后北还。长江沿线的争夺随后转入新的攻守。","s":["《三国志·周瑜、鲁肃传及裴松之注》","《三国志·武帝纪及裴松之注》"]}],"gloss":[{"t":"《三国演义》写诸葛亮草船借箭；《周瑜传》所叙赤壁战事没有这一情节，裴注另载孙权乘船受箭发生在其他战事。","s":["《三国演义·第四十六回》","《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"《三国演义》写诸葛亮设坛借东风；《周瑜传》记黄盖火攻时风势猛烈，没有诸葛亮作法召风的记载。","s":["《三国演义·第四十九回》","《三国志·周瑜、鲁肃传及裴松之注》"]},{"t":"《三国演义》写关羽在华容道释放曹操；《武帝纪》《先主传》记曹操败退与追击，未记关羽在那里俘获后放走曹操。","s":["《三国演义·第五十回》","《三国志·武帝纪及裴松之注》","《三国志·先主传》"]}],"cities":["江陵","许昌","南京（建业、建康、金陵、应天、天京）"],"people":["曹操","吴大帝","蜀汉先主","周瑜","程普","黄盖","鲁肃","诸葛亮"],"src":["《三国志·卷1·武帝纪》","《三国志·卷32·先主传》","《三国志·卷35·诸葛亮传》","《三国志·卷54·周瑜、鲁肃传》及裴松之注"],"line":"孙权与刘备联合迎击曹操，黄盖纵火烧毁曹军舟营，曹操北撤，南方局势改变。","leaders":[{"side":"甲方","t":"周瑜、程普、黄盖、刘备；诸葛亮参与结盟。","s":["《三国志·周瑜传》","《三国志·诸葛亮传》"]},{"side":"乙方","t":"曹操。","s":["《三国志·武帝纪》"]}],"short":"赤壁","timeShort":"208","placeShort":"湖北赤壁、嘉鱼等异说","sides":"孙权、刘备／曹操","result":"曹军撤退","sideA":"甲方","sideB":"乙方"},{"name":"夷陵之战","group":"第三组·三国至南北朝","tags":["战法典型","关键转折"],"g":"部分待核","lat":30.5,"lon":111.4,"f":[{"k":"时间","v":"222，蜀汉章武二年；刘备自221开始东征，核心反攻在222夏季。","s":["《三国志·先主传》","《三国志·陆逊传》"]},{"k":"地点","v":"湖北省宜昌市夷陵区、宜都市等长江沿线，古名夷陵、猇亭、夷道。","s":["《三国志·陆逊传》"]},{"k":"交战双方","v":"吴对蜀汉；孙权此时的称号与229称帝分开，不提前写成已称帝的吴皇帝。","s":["《三国志·陆逊传》"]},{"k":"兵力与伤亡","v":"《三国志·陆逊传》记吴军五万人，反攻破蜀军四十余营，蜀军死者“万数”；分别是所统部队数、破营数和死亡概数。","s":["《三国志·陆逊传》"]},{"k":"起因","v":"孙权方面夺取荆州，关羽败亡，刘备失去东部的重要地盘。刘备称帝后决定东征，希望夺回荆州并向孙权报复。孙权派陆逊统率诸将抵抗，吴军必须协调各部，等待有利时机。与此同时，北面的曹魏也在观察局势，吴方还要防备魏军乘两国交战之机发动进攻。","s":["《三国志·先主传》","《三国志·陆逊传》"]},{"k":"结果与影响","v":"蜀汉东征失败，刘备退守白帝，夺回荆州的目标落空。刘备后来病逝，诸葛亮接掌蜀汉政务，吴蜀也重新发展联盟关系。孙权一方守住了荆州的重要地盘，却仍需应对曹魏进攻。夷陵的相持、火攻与追击，前后都受到三方力量关系的影响；陆逊取得胜利后停止深入，也与防备北方威胁直接相连，战局随后再转向吴、蜀共同抗魏。","s":["《三国志·先主传》","《三国志·陆逊传》"]},{"k":"史料说明","v":"《陆逊传》记蜀军营垒数和死亡概数，未给出一套能与吴军五万人直接对照的双方实到兵力统计。","s":["《三国志·陆逊传》"]}],"steps":[{"t":"刘备沿长江向东推进，进入湖北宜都、夷陵一带。吴军收缩防线，陆逊让各部保持戒备，避免仓促与来军决战。","s":["《三国志·陆逊传》"]},{"t":"刘备在沿线布置营垒，派吴班等到平地挑战，暗中安排伏兵。陆逊没有出击，刘备后来撤出伏兵，诱战未成。","s":["《三国志·陆逊传》"]},{"t":"吴将孙桓在夷道遭围，其他将领请求救援。陆逊判断孙桓城坚粮足，继续集中力量等待主战场的机会。","s":["《三国志·陆逊传》"]},{"t":"相持数月后，陆逊试攻蜀军一营，未能得手。他调整办法，命各部携带茅草，用火攻烧毁营垒。","s":["《三国志·陆逊传》"]},{"t":"吴军各路同时进击，蜀军多个营垒失守，冯习、张南等战死。刘备退到马鞍山，再次遭到吴军包围。","s":["《三国志·陆逊传》"]},{"t":"刘备趁夜退出，沿途撤往白帝。吴军追击后，有将领请求深入，陆逊等顾虑曹魏来攻，主张停止扩大追逐。","s":["《三国志·陆逊传》"]},{"t":"吴军结束深入追击，刘备驻白帝。双方随后恢复交涉，吴蜀关系在共同面对曹魏的局势下逐步缓和。","s":["《三国志·先主传》","《三国志·陆逊传》"]}],"gloss":[{"t":"《三国演义》写关兴斩潘璋报父仇；《潘璋传》记他在夷陵以后继续活动，直到234年去世。","s":["《三国演义·第八十三回》","《三国志·潘璋传》"]},{"t":"《三国演义》写陆逊误入诸葛亮八阵图，由黄承彦引出；《陆逊传》记停追时顾虑曹魏进攻，没有这段遇阵经历。","s":["《三国演义·第八十四回》","《三国志·陆逊传》"]}],"cities":["成都","江陵","南京（建业、建康、金陵、应天、天京）"],"people":["蜀汉先主","吴大帝","陆逊","关羽","诸葛亮"],"src":["《三国志·卷32·先主传》","《三国志·卷55·潘璋传》","《三国志·卷58·陆逊传》"],"line":"刘备为夺回荆州东征，陆逊坚守后以火攻反击，蜀军败退白帝，吴蜀随后复交。","leaders":[{"side":"甲方","t":"陆逊、朱然、韩当、潘璋、孙桓。","s":["《三国志·陆逊传》"]},{"side":"乙方","t":"蜀汉先主、冯习、张南、傅肜。","s":["《三国志·先主传》","《三国志·陆逊传》"]}],"short":"夷陵","timeShort":"222（出兵始于221）","placeShort":"湖北宜昌夷陵、宜都等地","sides":"吴／蜀汉","result":"蜀汉军败，刘备退白帝","sideA":"甲方","sideB":"乙方"},{"name":"街亭之战","group":"第三组·三国至南北朝","tags":["关键转折"],"g":"部分待核","lat":35.0,"lon":106.0,"f":[{"k":"时间","v":"228，蜀汉建兴六年、魏太和二年春。","s":["《三国志·诸葛亮传》","《三国志·张郃传》"]},{"k":"地点","v":"甘肃省天水市秦安县陇城镇为常见定位，另有庄浪等地的不同说法，古名街亭。","s":["甘肃地方资料对陇城说与异说的说明"]},{"k":"交战双方","v":"魏对蜀汉。","s":["《三国志·诸葛亮传》"]},{"k":"起因","v":"诸葛亮首次大举出祁山，陇右的南安、天水、安定等地响应，魏廷随即派军西援。蜀军需要守住前方阵地，阻止魏军重新控制陇右。诸葛亮把前军交给马谡，王平随军协助。魏将张郃率援军迎击，双方在甘肃天水一带（街亭）接战，前线布阵和取水条件很快成为争夺的要害。","s":["《三国志·诸葛亮传及裴松之注》","《三国志·马良传附马谡》","《三国志·张郃传》"]},{"k":"结果与影响","v":"街亭失守，蜀军未能维持首次北伐初期打开的陇右局面，诸葛亮撤回汉中。马谡受到惩处，王平则因收拢败兵、保存部队受到提拔。这次失败把前线是否遵守部署、营地与水源如何安排、败后能否维持队伍等问题都留在了史书中。诸葛亮随后仍继续北伐，街亭成为第一次大举出兵的重要挫折，魏蜀在西线的争夺也没有随之结束。","s":["《三国志·诸葛亮传及裴松之注》","《三国志·马良传附马谡》","《三国志·王平传》"]},{"k":"史料说明","v":"《马谡传》有“下狱物故”的记法，《诸葛亮传》等又有诛谡的表述，对其死亡过程保留了不同叙述。","s":["《三国志·马良传附马谡》","《三国志·诸葛亮传及裴松之注》"]}],"steps":[{"t":"诸葛亮从祁山方向进军，魏廷调张郃等西来应战。马谡率蜀军前部到街亭，负责迎击魏军。","s":["《三国志·诸葛亮传及裴松之注》","《三国志·张郃传》","《三国志·马良传附马谡》"]},{"t":"马谡把部队部署在南山，未按诸葛亮节度下据城邑。王平多次劝阻，马谡没有采纳，双方意见分歧。","s":["《三国志·马良传附马谡》","《三国志·王平传》"]},{"t":"张郃针对蜀军山上阵地切断取水道路。取水受阻后，蜀军陷入被动，张郃随即发动进攻。","s":["《三国志·张郃传》"]},{"t":"马谡军败散，各部失去联系。王平率所部鸣鼓自守，魏军怀疑有伏兵，没有立即逼近。","s":["《三国志·王平传》"]},{"t":"王平乘机收集散兵，带着队伍退走。其余部队未能守住街亭，魏援军得以继续恢复陇右局势。","s":["《三国志·王平传》","《三国志·张郃传》"]},{"t":"诸葛亮撤回汉中，对马谡等追究责任，并上表请求自贬。王平因整队退军受到重用。","s":["《三国志·诸葛亮传及裴松之注》","《三国志·马良传附马谡》","《三国志·王平传》"]}],"gloss":[{"t":"《三国演义》把空城计接在失街亭之后，写诸葛亮以空城退司马懿；《张郃传》所记街亭对手是张郃，裴松之也质疑郭冲所传空城故事的时间、人物与军情。","s":["《三国演义·第九十五回》","《三国志·诸葛亮传及裴松之注》","《三国志·张郃传》"]}],"cities":["成都","长安"],"people":["诸葛亮","马谡","王平","张郃","蜀汉后主","魏明帝"],"src":["《三国志·卷17·张郃传》","《三国志·卷35·诸葛亮传》","《三国志·卷39·马良传附马谡》","《三国志·卷43·王平传》"],"line":"诸葛亮首次北伐时，马谡在街亭被张郃击败，王平收拢败兵，蜀军随后退回汉中。","leaders":[{"side":"甲方","t":"张郃。","s":["《三国志·张郃传》"]},{"side":"乙方","t":"马谡、王平；诸葛亮为此次北伐统帅，街亭具体阵地由马谡部署。","s":["《三国志·马良传附马谡》","《三国志·王平传》"]}],"short":"街亭","timeShort":"228","placeShort":"甘肃天水秦安陇城等异说","sides":"魏／蜀汉","result":"马谡败，蜀军退","sideA":"甲方","sideB":"乙方"},{"name":"西晋灭吴之战","group":"第三组·三国至南北朝","tags":["改朝换代","统一战争","水战"],"g":"部分待核","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"279—280，西晋咸宁五年至太康元年；280三月为吴降之月（原书历月）。","s":["《晋书·武帝纪》","《晋书·王濬传》"]},{"k":"地点","v":"长江上中下游至江苏省南京市，吴都建业在今南京。","s":["《晋书·王濬传》"]},{"k":"交战双方","v":"西晋对吴。","s":["《晋书·武帝纪》"]},{"k":"兵力与伤亡","v":"《晋书·武帝纪》记晋伐吴诸军“东西凡二十余万”，这是各路出征军的合计；受降图籍另列吴兵二十三万，属于接收的全国兵籍数字。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"k":"起因","v":"魏灭蜀后，吴成为长江以南主要的独立政权。西晋取代魏，继续准备向南进攻。羊祜在荆州经营边防，王濬在四川造船、训练水军，使上游顺流而下与沿江多路进攻能够配合。晋廷虽对出兵时机有不同意见，晋武帝最终决定调集各路军队，攻取吴的沿江重镇与都城。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"k":"结果与影响","v":"吴王孙皓投降，三国主要政权长期分立的局面结束，西晋建立起跨越长江的统一统治。晋廷安置吴王室，留用部分地方官员，接收人口、土地和军队。胜利来自上游舟师与沿江诸军的共同推进，受降后王濬、王浑等也因节度与功劳发生争执。南方纳入晋朝以后，地方治理仍需逐步整合，新的统一并未消除宗室和边疆的政治矛盾。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"k":"史料说明","v":"《晋书》各传分别着重记本传人物的进军和受降功劳；伐吴军总数与战后接收的吴兵籍属于两种统计。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]}],"steps":[{"t":"279年冬，晋军分路出动。王濬、唐彬率巴蜀水军顺长江东下，杜预进攻江陵，王浑等从中下游方向进军。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"t":"吴军在江中布置铁锁和障碍。王濬军设法清除，继续攻取沿岸据点，舟师逐步进入长江中游。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"t":"杜预攻克江陵，荆州沿江守军相继动摇。上游舟师与各路陆军推进，使吴军难以维持上下游之间的支援。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"t":"张悌、沈莹等率吴军渡江迎战，在与王浑、周浚部的交锋中失败，张悌等战死，建业失去重要的外围野战力量。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]},{"t":"王濬继续东下，抵达江苏南京（建业）石头城一带。孙皓出降，晋军接收图籍，战争转入安置吴王室和官民的阶段。","s":["《晋书·武帝纪》","《晋书·王濬传》","《晋书·卷34·羊祜、杜预传》","《三国志·卷48·孙皓传》及裴松之注"]}],"gloss":[],"cities":["洛阳（秦汉至隋唐）","成都","江陵","南京（建业、建康、金陵、应天、天京）"],"people":["西晋武帝","吴末帝","王濬","杜预","羊祜"],"src":["《晋书·卷3·武帝纪》","《晋书·卷34·羊祜、杜预传》","《晋书·卷42·王濬传》","《三国志·卷48·孙皓传》及裴松之注"],"line":"西晋水陆各军沿长江进攻，王濬率舟师抵达建业，孙皓投降，三国分立局面结束。","leaders":[{"side":"甲方","t":"王濬、杜预、王浑、司马伷、胡奋、王戎。","s":["《晋书·武帝纪》","《晋书·王濬传》"]},{"side":"乙方","t":"孙皓、张悌、沈莹、孙震、诸葛靓；孙皓是决策与受降主体，野战部队由诸将指挥。","s":["《三国志·孙皓传》"]}],"short":"灭吴","timeShort":"279—280","placeShort":"长江中下游及江苏南京","sides":"西晋／吴","result":"孙皓降，吴亡","sideA":"甲方","sideB":"乙方"},{"name":"永嘉之乱与洛阳陷落","group":"第三组·三国至南北朝","tags":["改朝换代","攻城守城"],"g":"部分待核","lat":34.7,"lon":112.7,"f":[{"k":"时间","v":"311，西晋永嘉五年六月洛阳陷落（原书历月）。","s":["《晋书·怀帝纪》"]},{"k":"地点","v":"河南省洛阳市汉魏洛阳故城一带，古名洛阳。","s":["《晋书·怀帝纪》"]},{"k":"交战双方","v":"刘聪所统汉政权军（后世常归入汉赵、前赵）对西晋。311年刘聪的国号仍是“汉”，“赵”是后来的称呼。","s":["《晋书·刘聪载记》"]},{"k":"起因","v":"八王之乱后，西晋朝廷与诸军之间联系破裂，洛阳的粮食和外援日益匮乏。东海王司马越率军离开京城，死后部队又在宁平城一带被石勒击溃。京城失去重要的外围军力，城内饥困加深。刘聪乘势派军进逼洛阳，试图控制西晋皇帝和中央机构。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]},{"k":"结果与影响","v":"洛阳失守，晋怀帝被俘，西晋原有的中央指挥体系受到沉重打击，中原政局进一步瓦解。晋室在长安另立朝廷，直到316年长安陷落，西晋才结束；317年司马睿在江南建立新的中枢。失都、俘帝与此后的南迁前后相接，却经历数年。洛阳的破坏和人口流散，也使原来依靠京城维持的官僚、军队和地方联系发生更深变化。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]},{"k":"史料说明","v":"洛阳陷落发生在311年，西晋长安朝廷延续至316年；晋室在江南建立东晋又在317年。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]}],"steps":[{"t":"呼延晏先向洛阳推进，在外围接连击败晋军。城外防御受损，晋廷难以组织有效的反击。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]},{"t":"司马越部在宁平城一带遭石勒攻击而溃败，洛阳期望中的外援进一步减少，皇帝和官员陷入孤立。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]},{"t":"刘曜、王弥等带兵会合，继续进攻城门。城内粮食紧张，晋怀帝曾考虑离开洛阳，却未能落实迁避安排。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]},{"t":"攻军突破城防，进入洛阳。宫室与官署遭破坏，晋怀帝被俘，官员和居民遭受杀戮、劫掠。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]},{"t":"晋方残部转向长安，后来拥立晋愍帝，重新组织朝廷。洛阳陷落后，晋室仍在关中继续抵抗。","s":["《晋书·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"]}],"gloss":[],"cities":["洛阳（秦汉至隋唐）","长安"],"people":["西晋怀帝","司马越","刘聪","刘曜","石勒","西晋愍帝"],"src":["《晋书·卷5·怀帝纪、愍帝纪》","《晋书·卷102·刘聪载记》","《资治通鉴·卷87》"],"line":"汉赵军攻陷洛阳，晋怀帝被俘，西晋朝廷遭受重创，残存朝廷后来迁至长安。","leaders":[{"side":"甲方","t":"呼延晏、刘曜、王弥；石勒此前在外围打击晋军主力。","s":["《晋书·刘聪载记》","《资治通鉴·卷87》"]},{"side":"乙方","t":"晋怀帝朝廷及城防诸部；司马越所部此前在外行动。","s":["《晋书·怀帝纪》"]}],"short":"永嘉之乱","timeShort":"311","placeShort":"河南洛阳汉魏故城","sides":"汉赵（时国号汉）／西晋","result":"洛阳陷，晋怀帝被俘","sideA":"甲方","sideB":"乙方"},{"name":"淝水之战","group":"第三组·三国至南北朝","tags":["战法典型","关键转折"],"g":"部分待核","lat":32.6,"lon":116.8,"f":[{"k":"时间","v":"383，东晋太元八年；主要战事在该年秋冬。","s":["《晋书·谢玄传》","《晋书·苻坚载记下》"]},{"k":"地点","v":"安徽省淮南市寿县一带，古名寿阳、淝水；古河道与具体渡水位置仍有定位问题。〔待核〕","s":[]},{"k":"交战双方","v":"东晋对前秦。","s":["《晋书·苻坚载记下》"]},{"k":"兵力与伤亡","v":"《晋书·苻坚载记下》记苻坚自长安出发时戎卒六十余万、骑二十七万，苻融先领步骑二十五万；同篇记晋援军水陆七万。分别是出征、前锋和援军数字，存在层级重叠。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"k":"起因","v":"前秦控制北方主要地区后，苻坚决定大举进攻东晋。朝臣中有人反对，担心部众来源复杂、远征补给困难，苻坚仍下令征发各地军队。诸路部队陆续南下，尚未全部会合，前锋已抵淮南。东晋由谢安在朝主持，谢石、谢玄等率军迎击，准备阻止秦军压向长江。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"k":"结果与影响","v":"东晋守住江淮防线，前秦的南征计划失败。苻坚退回北方后，原来归附的多支政治军事力量相继起事，北方重新陷入分裂。前秦政权仍继续存在，却已难维持此前的统合。淝水交战时，秦各路军队尚未到齐，洛涧前锋被破、两军退渡约定和秦军退阵失序先后相连，使动员庞大的远征转成一场难以收拾的溃退。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"k":"史料说明","v":"《苻坚载记下》记晋军水陆七万，具体淝水临阵部队又称“数万”；秦方各路兵力同样有抵达先后，出征数与会战数口径不同。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]}],"steps":[{"t":"苻融率前锋攻取安徽寿县（寿阳），梁成在洛涧部署部队，阻断东晋援军的行进道路。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"t":"苻坚获悉前线有利，留下大军，带轻骑赶赴寿阳。秦军诸部仍在途中，前线尚未得到全部兵力支援。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"t":"刘牢之率精兵夜袭洛涧，击破梁成部，梁成等战死。晋军渡过这一阻碍，继续向寿阳推进。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"t":"苻坚派朱序劝降晋军。朱序暗中告知谢石等，秦军尚未集齐，宜趁早进攻，晋军遂决定求战。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"t":"双方隔淝水布阵，晋军请求秦军稍退，让出渡河交战的地方。秦方打算在晋军半渡时反击，下令后撤。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"t":"秦军后退时失去秩序，军阵难以控制。晋军渡水追击，苻融在整顿部队时战死，前线崩溃。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]},{"t":"苻坚中箭北逃，收拢散兵退回北方。晋军乘胜推进，秦军南征由此失败，原来的进攻部署被打断。","s":["《晋书·苻坚载记下》","《晋书·卷79·谢玄传》"]}],"gloss":[],"cities":["长安","南京（建业、建康、金陵、应天、天京）"],"people":["苻坚","谢安","谢石","谢玄","刘牢之","东晋孝武帝"],"src":["《晋书·卷79·谢玄传》","《晋书·卷114·苻坚载记下》"],"line":"前秦南下攻晋，两军隔淝水对峙，秦军后退时阵脚大乱，东晋渡河进攻获胜。","leaders":[{"side":"甲方","t":"谢石、谢玄、谢琰、桓伊、刘牢之；谢安在朝主持。","s":["《晋书·谢玄传》"]},{"side":"乙方","t":"苻坚、苻融、梁成、张蚝等；朱序原为晋将，降秦后在本役中影响军情与退阵过程。","s":["《晋书·苻坚载记下》"]}],"short":"淝水","timeShort":"383","placeShort":"安徽淮南寿县一带","sides":"东晋／前秦","result":"前秦前线溃败","sideA":"甲方","sideB":"乙方"},{"name":"邙山之战","group":"第三组·三国至南北朝","tags":["关键转折"],"g":"部分待核","lat":34.8,"lon":112.5,"f":[{"k":"时间","v":"543，西魏大统九年、东魏武定元年春。","s":["《周书·文帝纪下》","《资治通鉴·卷158》"]},{"k":"地点","v":"河南省洛阳市北部邙山一带，行动涉及洛阳、虎牢与黄河渡口，具体阵地仍有定位问题。〔待核〕","s":[]},{"k":"交战双方","v":"东魏对西魏，双方分别以高欢、宇文泰控制军政，二人当时都没有称帝。","s":["《周书·文帝纪下》"]},{"k":"起因","v":"北魏分裂后，东魏、西魏围绕洛阳与黄河通道反复争夺。东魏高仲密据虎牢投向西魏，给宇文泰向东扩展提供机会。宇文泰率军接应，试图巩固这一新据点，高欢则率东魏军西来阻止。虎牢、洛阳和渡河道路相互牵连，双方主力逐渐集中到洛阳北面的邙山一带。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]},{"k":"结果与影响","v":"西魏此次东进失败，东魏保住洛阳方向的重要据点，但未能继续进取关中、消灭西魏。宇文泰回军后需要补充兵员，广募关陇豪右加入军旅，军队的组织基础随之扩展。邙山之战中，双方都曾面临败退，将领能否重新集结部队直接影响后续胜负。战后东西分立继续，洛阳和黄河道路仍是两国争夺的前线。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]},{"k":"史料说明","v":"这里的邙山之战发生于543年；538年的河桥交战及其他年份的邙山战事各有独立经过。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]}],"steps":[{"t":"西魏接收虎牢后，宇文泰率军向东推进，并处理黄河浮桥与渡口，以保证军队能够通行。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]},{"t":"高欢率东魏军渡河，据邙山列阵。宇文泰连夜趋近，准备发起袭击，东魏方面已有防备。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]},{"t":"彭乐率骑兵突入西魏阵地，西魏初战受挫。宇文泰收拢部队，再次交战，战局并未就此停止。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]},{"t":"西魏中军、右翼一度击败东魏部队，高欢也遭追迫。随后赵贵等所部失利，西魏各部难以共同维持攻势。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]},{"t":"东魏重新集结反击，宇文泰撤退，独孤信、于谨等掩护并收拢散卒。西魏最终返回关中，东魏恢复洛阳、虎牢方向的控制。","s":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"]}],"gloss":[],"cities":["长安","洛阳（秦汉至隋唐）","邺城","晋阳"],"people":["高欢","宇文泰","侯景"],"src":["《周书·卷2·文帝纪下》","《资治通鉴·卷158》"],"line":"东西魏在洛阳北面的邙山交战，西魏军失利撤退，东魏保住洛阳，双方继续对峙。","leaders":[{"side":"甲方","t":"高欢、彭乐、段韶、侯景等，侯景另涉虎牢方向行动。","s":["《资治通鉴·卷158》"]},{"side":"乙方","t":"宇文泰、赵贵、若干惠、贺拔胜、独孤信、于谨。","s":["《资治通鉴·卷158》"]}],"short":"邙山","timeShort":"543","placeShort":"河南洛阳北部","sides":"东魏／西魏","result":"西魏退，东魏保洛阳","sideA":"甲方","sideB":"乙方"},{"name":"台城之战","group":"第三组·三国至南北朝","tags":["内战叛乱","攻城守城"],"g":"部分待核","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"548—549，梁太清二年至三年；549三月台城陷落（原书历月）。","s":["《资治通鉴·卷161—162》","《资治通鉴·卷162》"]},{"k":"地点","v":"江苏省南京市玄武湖以南相关地区，古名建康台城；六朝宫城与今日同名城墙分属不同时代。〔待核〕","s":[]},{"k":"交战双方","v":"侯景军对梁朝守军及各路援军。","s":["《资治通鉴·卷161—162》","《资治通鉴·卷162》"]},{"k":"起因","v":"侯景由东魏投梁后，北方作战失利，梁廷又与东魏交涉，他担心自己成为交易对象。侯景以寿阳为据点起兵，联络梁宗室萧正德，利用朝廷内部矛盾向南推进。南京建康一带准备不足，侯景渡江后迅速逼近宫城，试图抓住皇帝、控制梁朝中央机构。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]},{"k":"结果与影响","v":"侯景取得梁朝中枢，皇帝与中央官员失去自主，江南政治秩序遭受重创。梁国号和各地宗室、军队仍在延续，地方力量随后继续与侯景交战。551年侯景才另建汉政权，之后又被击败。台城长期围守中，守城器械尚能抵挡部分进攻，城外援军却未能送入足够的支援；粮食、疾病与指挥分裂共同耗尽了城内继续抵抗的条件。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]}],"steps":[{"t":"548年，侯景由寿阳南下，借萧正德内应渡过长江，进入南京（建康）。梁军退守宫城，侯景开始围攻台城。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]},{"t":"羊侃等组织守军，针对冲车、楼车、堆土等攻势应战。侯景未能迅速破城，转而持续围困。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]},{"t":"萧纶等从外部赴援，接战失利，未能打通入城道路。更多援军陆续会合，围城仍未解除。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]},{"t":"柳仲礼等统率的援军驻在外围，各部指挥不一，无法形成持续的合力，城内可得到的粮食与人员越来越少。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]},{"t":"梁廷与侯景一度议和，侯景却未真正撤去包围。城内粮尽、疫病与伤亡加重，守御能力不断下降。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]},{"t":"549年三月，台城被攻破，梁武帝等受侯景控制。武帝随后去世，侯景开始操纵朝廷的任命和政令。","s":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"]}],"gloss":[],"cities":["南京（建业、建康、金陵、应天、天京）"],"people":["萧衍","侯景"],"src":["《资治通鉴·卷161》","《资治通鉴·卷162》","《资治通鉴·卷163》"],"line":"侯景围攻南京台城，梁军多路救援未能解围，城破后梁武帝受制，朝廷权力崩解。","leaders":[{"side":"甲方","t":"侯景、王伟；萧正德为内应。","s":["《资治通鉴·卷161》"]},{"side":"乙方","t":"羊侃、柳津等守城；萧纶、柳仲礼、韦粲等率外围援军。","s":["《资治通鉴·卷161—162》","《资治通鉴·卷162》"]}],"short":"台城","timeShort":"548—549","placeShort":"江苏南京","sides":"侯景军／梁","result":"台城陷，梁武帝受制","sideA":"甲方","sideB":"乙方"},{"name":"隋灭陈之战","group":"第三组·三国至南北朝","tags":["改朝换代","统一战争"],"g":"部分待核","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"588—589，隋开皇八年至九年；589正月陈都陷落（原书历月）。","s":["《隋书·高祖纪下》","《隋书·韩擒虎、贺若弼传》"]},{"k":"地点","v":"长江沿线及江苏省南京市，主要地名有建康、京口、横江。","s":["《隋书·韩擒虎、贺若弼传》"]},{"k":"交战双方","v":"隋对陈。","s":["《隋书·高祖纪下》"]},{"k":"兵力与伤亡","v":"《隋书·高祖纪下》记伐陈合总管九十、兵五十一万八千，皆受晋王节度；这是横跨多个进攻方向的出征编组数字。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"k":"起因","v":"隋取代北周、整顿北方后，隋文帝把统一目标转向长江以南的陈。隋军在上游造船、沿江集兵，也用反复调动影响陈方判断。陈依靠长江和建康周边防线抵御，必须同时照应上游、下游与都城。588年隋廷正式部署多路进攻，试图从多个方向打开渡江通道。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"k":"结果与影响","v":"陈亡，隋建立跨越南北的统一统治，南北朝主要政权长期分立的局面结束。陈王室被安置，江南官民逐渐纳入隋的行政体系，地方反抗与制度调整仍在后续发生。作战中，上游舟师牵制、多点渡江和建康外围野战相互配合；都城失去外围部队后，中枢很快被控制。隋军取得军事统一，也由此面对如何治理原南朝地区的新任务。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"k":"史料说明","v":"《韩擒虎传》《贺若弼传》分别突出入城受降和城外获胜，对建康失守经过的叙述侧重点不同。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]}],"steps":[{"t":"隋以晋王杨广等统领诸军，杨素在上游出动，下游各路分别向长江靠近，形成从四川到江海的进攻线。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"t":"杨素率舟师突破上游陈军据点，使陈难以把各处兵力集中到下游，都城方向承受的压力逐步增大。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"t":"贺若弼从广陵方向渡江，攻取江苏镇江（京口）；韩擒虎从横江一线渡江，向南京（建康）推进。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"t":"陈军在都城外围集结，萧摩诃等与贺若弼交战失利，陈的野战防御被击破，城内与前线的联系更加混乱。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"t":"韩擒虎率部入城，陈叔宝被俘。贺若弼等随后进入建康，隋军控制宫城和中央机构。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]},{"t":"隋接收陈王室、官员及地方图籍，各地陆续归附。军事征服之后，朝廷继续安排江南的行政和人口事务。","s":["《隋书·卷2·高祖纪下》","《隋书·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"]}],"gloss":[],"cities":["长安","江陵","南京（建业、建康、金陵、应天、天京）"],"people":["隋文帝","隋炀帝","杨素","高颎","韩擒虎","贺若弼"],"src":["《隋书·卷2·高祖纪下》","《隋书·卷52·韩擒虎、贺若弼传》","《陈书·卷6·后主纪》"],"line":"隋军多路渡过长江，在建康城外击败陈军并俘获陈后主，南北分立局面由此结束。","leaders":[{"side":"甲方","t":"杨广、杨素、韩擒虎、贺若弼、高颎；杨广以晋王身份统摄诸军。","s":["《隋书·高祖纪下》","《隋书·韩擒虎、贺若弼传》"]},{"side":"乙方","t":"陈叔宝、萧摩诃、任忠、鲁广达等，陈叔宝主持朝廷，诸将领兵迎战。","s":["《陈书·后主纪》","《隋书·贺若弼传》"]}],"short":"灭陈","timeShort":"588—589","placeShort":"长江沿线及江苏南京","sides":"隋／陈","result":"陈后主被俘，陈亡","sideA":"甲方","sideB":"乙方"},{"name":"虎牢之战","group":"第四组·隋唐五代","tags":["改朝换代","统一战争"],"g":"部分待核","lat":34.8,"lon":113.2,"f":[{"k":"时间","v":"621，唐武德四年五月为决战月（原书历月）；围攻洛阳始于此前。","s":["《资治通鉴·卷189》"]},{"k":"地点","v":"河南省郑州市荥阳市汜水镇一带，古名虎牢、武牢，战事联系洛阳与成皋方向。","s":["《资治通鉴·卷189》"]},{"k":"交战双方","v":"唐军对窦建德夏军及王世充郑军；虎牢正面主要为唐夏交战，郑军仍受围于洛阳。","s":["《资治通鉴·卷189》"]},{"k":"兵力与伤亡","v":"《资治通鉴》记窦建德与所会部队合十余万人，“号三十万”；前者是书中所记集结规模，后者是号称人数。","s":["《资治通鉴·卷189》"]},{"k":"起因","v":"唐军围攻王世充控制的洛阳，城中粮食日益短缺。窦建德担心洛阳失守后，唐军会转攻自己的河北根据地，决定率军西援。唐军面临两面作战的压力，李世民主张留部继续围城，自己率军据守河南荥阳（虎牢），阻止窦军与洛阳守军会合，再寻找机会击败援军。","s":["《资治通鉴·卷189》"]},{"k":"结果与影响","v":"窦建德被俘、王世充投降，夏、郑两政权相继失去统治核心，唐在河南和河北的地位大为加强。河北随后仍有刘黑闼等起兵，唐还需要继续作战才能巩固地方。虎牢的胜利与洛阳围城紧密相连：城中缺粮迫使外援来救，唐军又以关隘阻断两军会合。击败援军后，长期围城终于取得结果，唐统一战争的进程由此向前推进。","s":["《资治通鉴·卷189》"]}],"steps":[{"t":"窦建德沿黄河向西进军，部队与运输船相伴，到达虎牢以东。王世充派人往来联络，希望援军迫唐解围。","s":["《资治通鉴·卷189》"]},{"t":"李世民据虎牢，派兵侦察并不断挑战，观察窦军的兵势与作息；洛阳方向的唐军继续围困王世充。","s":["《资治通鉴·卷189》"]},{"t":"窦方有人建议绕向河北、山西，牵动唐军后方。窦建德没有采纳，继续把主力留在虎牢前线。","s":["《资治通鉴·卷189》"]},{"t":"夏军在关前布阵，久候未战，士卒疲倦，队伍开始松动。李世民观察后率骑兵出击，随后投入更多部队。","s":["《资治通鉴·卷189》"]},{"t":"夏军阵形瓦解，窦建德受伤被俘。消息送到洛阳，王世充失去外援后投降，唐军先后控制两国的统治中心。","s":["《资治通鉴·卷189》"]}],"gloss":[],"cities":["长安","洛阳（秦汉至隋唐）"],"people":["唐高祖","唐太宗","李勣","窦建德","王世充"],"src":["《资治通鉴·卷189》"],"line":"李世民围攻洛阳，又在虎牢击败前来救援的窦建德，王世充随后投降，唐势扩大。","leaders":[{"side":"甲方","t":"李世民、李世勣、程知节、秦叔宝等；李世民即后来的唐太宗。","s":["《资治通鉴·卷189》"]},{"side":"乙方","t":"窦建德；王世充在洛阳主持守御。","s":["《资治通鉴·卷189》"]}],"short":"虎牢","timeShort":"621","placeShort":"河南郑州荥阳汜水一带","sides":"唐／窦建德、王世充","result":"窦被俘，王随后降","sideA":"甲方","sideB":"乙方"},{"name":"唐灭东突厥之战","group":"第四组·隋唐五代","tags":["边疆与对外"],"g":"部分待核","lat":40.8,"lon":111.9,"f":[{"k":"时间","v":"629—630，唐贞观三年至四年；630年初为主攻阶段。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"k":"地点","v":"内蒙古自治区中部及今蒙古国南部相关地区，主要古地名有定襄、阴山、铁山、碛口。","s":["《旧唐书·李靖传》"]},{"k":"交战双方","v":"唐对东突厥颉利可汗所属部众，突厥内部另有离叛与归附力量。","s":["《资治通鉴·卷193》"]},{"k":"起因","v":"唐初屡受东突厥进攻，唐太宗即位时还曾面对兵临渭水的局势。此后东突厥内部诸部离叛，灾害又使牧业和人口供养更加困难，颉利可汗的控制力下降。唐廷一面接纳来降部众，一面恢复边防力量，最终任命李靖等分路北进，利用汗国内部动摇的时机发动进攻。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"k":"结果与影响","v":"颉利被俘，东突厥汗国原有的统治体系瓦解，唐在漠南的影响显著扩大。唐廷围绕归附部众如何安置展开讨论，继而设置相关军政机构，并任用部分首领管理其众。草原人口仍保有部落联系，边疆统治采取了不同于内地州县的安排。后来突厥势力重新兴起，唐与草原诸部的关系继续变化，630年的胜利开启的是新的边疆格局。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]}],"steps":[{"t":"唐廷组织多路进军，李靖率骑兵从马邑方向出动，快速逼近定襄。颉利没有料到唐军深入，仓促转移营地。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"t":"唐军持续进击与招降，东突厥部分首领归附，隋萧后、杨政道等被送入唐境，颉利能调动的力量进一步减少。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"t":"颉利派使者求和，唐使前往营地交涉。李靖与李世勣判断其防备放松，准备继续突袭。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"t":"苏定方率前锋接近颉利营地，唐军随后投入进攻。东突厥军溃散，颉利带少数部众逃走。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"t":"张宝相所部最终擒获颉利，将其送往唐廷。军事进攻与追捕结束后，唐开始安置大批归附的突厥部众。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]}],"gloss":[],"cities":["长安"],"people":["唐太宗","李靖","李勣"],"src":["《旧唐书·卷67·李靖传》","《资治通鉴·卷193》"],"line":"李靖等率唐军北进，突袭东突厥牙帐，颉利可汗随后被俘，汗国原有统治瓦解。","leaders":[{"side":"甲方","t":"李靖、李世勣、苏定方、张宝相；各负责不同进军或追捕阶段。","s":["《旧唐书·李靖传》","《资治通鉴·卷193》"]},{"side":"乙方","t":"颉利可汗及所属诸部首领。","s":["《资治通鉴·卷193》"]}],"short":"灭东突厥","timeShort":"629—630","placeShort":"内蒙古及今蒙古国南部","sides":"唐／东突厥","result":"颉利可汗被俘","sideA":"甲方","sideB":"乙方"},{"name":"白江口之战","group":"第四组·隋唐五代","tags":["水战","边疆与对外"],"g":"部分待核","lat":36.0,"lon":126.7,"f":[{"k":"时间","v":"663，唐龙朔三年八月（原书历月）。","s":["《旧唐书·刘仁轨传》"]},{"k":"地点","v":"今韩国忠清南道、全北特别自治道之间的锦江河口一带，古名白江口、白村江，具体交锋水域仍有定位问题。〔待核〕","s":[]},{"k":"交战双方","v":"唐、新罗对倭国援军及百济复国军；在朝鲜半岛上，新罗与唐同一阵营，百济复国军与倭军同一阵营。","s":["《旧唐书·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"k":"兵力与伤亡","v":"《旧唐书·刘仁轨传》记白江口“四战捷，焚其舟四百艘”，四百艘是唐方记载的焚毁敌船战果，属于船数口径。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"k":"起因","v":"660年唐与新罗攻破百济都城后，百济地方势力继续抵抗，拥立从倭国返回的扶余丰，试图恢复政权。倭国派兵和船队来援，复国军据周留城等地作战。唐留驻军队必须维持据点与海上补给，新罗也要继续推进。663年，双方围绕百济复国军的存亡展开海陆交战。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"k":"结果与影响","v":"百济复国军失去重要的海上外援，扶余丰离去，原来依靠周留城等据点恢复政权的努力失败。倭国在半岛的军事干预遭受打击，唐军则继续驻守、接收人口与地方据点。此后唐与新罗之间又发生冲突，半岛权力格局继续调整。白江口的结果首先改变了复国军的生存条件，水军交战、陆上推进和战后各地归附共同结束了这一轮主要抵抗。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"k":"史料说明","v":"《旧唐书》着重记唐军连续获胜与焚船，《日本书纪》着重记倭军分次来援和退却，交战次序各有详略。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]}],"steps":[{"t":"唐、新罗军向周留城方向推进。刘仁轨与杜爽、扶余隆率水军、粮船自熊津江出发，准备同陆军会合。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"t":"倭国援军船队抵达今韩国锦江河口一带（白江口），与唐水军遭遇，双方开始接战。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"t":"《旧唐书》记唐军连续交锋并纵火焚船；《日本书纪》记倭方前军初战不利，后续部队仍继续进攻。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"t":"倭军船队在水面进退受阻，败军相互拥挤，人员落水，海上援军的攻势瓦解。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]},{"t":"扶余丰逃离战区，周留城等据点相继投降。唐军又招抚、进攻其他抵抗据点，部分百济人员随倭方撤离。","s":["《旧唐书·卷84·刘仁轨传》","《日本书纪·天智天皇二年》"]}],"gloss":[],"cities":["长安"],"people":["唐高宗","刘仁轨"],"src":["《旧唐书·卷84·刘仁轨传》","《日本书纪·卷27·天智天皇二年》"],"line":"唐与新罗军在白江口击败倭国和百济复国军，百济复国行动失去重要的海上支援。","leaders":[{"side":"甲方","t":"刘仁轨、杜爽、扶余隆；新罗军另参与陆上协同。","s":["《旧唐书·刘仁轨传》"]},{"side":"乙方","t":"扶余丰；倭方有朴市田来津等，见《日本书纪》。〔待核〕","s":["《日本书纪·天智天皇二年》"]}],"short":"白江口","timeShort":"663","placeShort":"韩国锦江河口一带","sides":"唐、新罗／倭、百济复国军","result":"唐、新罗胜","sideA":"甲方","sideB":"乙方"},{"name":"怛罗斯之战","group":"第四组·隋唐五代","tags":["边疆与对外"],"g":"部分待核","lat":42.9,"lon":71.4,"f":[{"k":"时间","v":"751，唐天宝十载七月（原书历月）。","s":["《资治通鉴·卷216》"]},{"k":"地点","v":"今哈萨克斯坦江布尔州塔拉兹至吉尔吉斯斯坦塔拉斯河流域，古名怛罗斯、恒逻斯，具体交战点仍有不同说法。〔待核〕","s":[]},{"k":"交战双方","v":"唐安西军及盟属部队对大食阿拔斯王朝军及相关地方力量；葛逻禄部在战中转向大食。","s":["《资治通鉴·卷216》"]},{"k":"兵力与伤亡","v":"《资治通鉴》记高仙芝率蕃、汉三万人，战败后“所余才数千人”；三万是此次西进部队的记数，数千是败后余众的概数。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"k":"起因","v":"高仙芝进攻石国并俘获其王后，石国王子逃出求援，向周围诸国和大食控诉唐军。当地原有的联盟随之变化，阿拔斯势力也在中亚扩展。高仙芝获悉各方可能联合进攻安西，决定率军西行迎击。唐安西军与大食军及其盟友由此在怛罗斯一带直接交战。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"k":"结果与影响","v":"唐军此次西进失败，人员损失严重，与中亚地方势力的关系受到冲击。安西军镇仍继续存在，唐在西域的军政活动也延续了一段时间；后来的安史之乱和东调兵力，又进一步改变当地局势。怛罗斯显示高仙芝在石国的行动引发了连锁反应，盟部转向又直接影响战场。败后收拢残部、打通归路，使部分军队得以回到安西，结束这次远征。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"k":"史料说明","v":"所引汉文史料详记唐军与葛逻禄部行动，对大食方面的统帅和军队编组记载较少。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]}],"steps":[{"t":"高仙芝率唐军及蕃部向西深入，抵达今塔拉斯河流域一带（怛罗斯、恒逻斯），与大食军相遇。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"t":"双方相持数日，唐军远离安西的主要据点，需要维持与盟部之间的协同，等待打破对阵局面。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"t":"葛逻禄部在交战中倒向大食，与大食军从两面攻击唐军。唐方的联盟破裂，军队遭到重创。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"t":"李嗣业劝高仙芝夜间撤离，归路又被拔汗那部的人畜堵塞，李嗣业强行开路，带队退出。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]},{"t":"段秀实劝李嗣业收拢散卒，抵御追兵，部分军队由此返回安西，西进攻势结束。","s":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"]}],"gloss":[],"cities":["长安"],"people":["唐玄宗","高仙芝"],"src":["《资治通鉴·卷216》","《新唐书·卷135·高仙芝传》"],"line":"高仙芝率唐军西进怛罗斯，与阿拔斯军交战，葛逻禄倒戈后唐军战败，余部东撤。","leaders":[{"side":"甲方","t":"高仙芝、李嗣业、段秀实。","s":["《资治通鉴·卷216》"]},{"side":"乙方","t":"大食（阿拔斯）军，所引汉文原典未载主将姓名。","s":[]}],"short":"怛罗斯","timeShort":"751","placeShort":"今哈萨克斯坦、吉尔吉斯斯坦交界地区（定位待核）","sides":"唐及盟军／阿拔斯军及盟军","result":"唐军败退","sideA":"甲方","sideB":"乙方"},{"name":"潼关之战","group":"第四组·隋唐五代","tags":["内战叛乱","关键转折"],"g":"部分待核","lat":34.6,"lon":110.2,"f":[{"k":"时间","v":"756，唐天宝十五载六月，灵宝战败后潼关陷落（原书历月）。","s":["《资治通鉴·卷218》"]},{"k":"地点","v":"河南省三门峡市灵宝市西部至陕西省渭南市潼关县，野战在灵宝西原，关城失守在潼关。","s":["《资治通鉴·卷218》"]},{"k":"交战双方","v":"唐对安禄山燕政权军。","s":["《资治通鉴·卷218》"]},{"k":"兵力与伤亡","v":"《资治通鉴》记唐军前部精兵五万、后续十万、河北岸三万，败后进入潼关者八千余人；前三数是分部部署，八千余是退入关城的人数。","s":["《资治通鉴·卷218》"]},{"k":"起因","v":"安禄山起兵后攻取洛阳，潼关成为保护关中的主要屏障。哥舒翰接掌守军，主张凭险固守，等待其他方向牵制叛军。朝廷得到敌军示弱的消息，又因杨国忠与统帅之间的猜疑，反复催促出战。哥舒翰最终奉命离开关隘，向河南灵宝西部推进，在狭窄道路上迎击崔乾祐。","s":["《资治通鉴·卷218》"]},{"k":"结果与影响","v":"潼关失守，唐朝保护关中的重要屏障被打破。唐玄宗离开长安，途中发生马嵬事件，唐肃宗随后在灵武即位，唐军重新组织各地力量反攻。燕军后来进入长安，关中政治与军事中心易手。灵宝的道路条件限制了大军展开，伏兵、火烟和侧后骑兵进攻又接连放大混乱，使原本依关据守的部队在关外野战中迅速瓦解。","s":["《资治通鉴·卷218》"]},{"k":"史料说明","v":"同卷又载火拔归仁以“二十万众”责问哥舒翰；这段人物言语与分部部署的十八万合计，属于不同记数层次。","s":["《资治通鉴·卷218》"]}],"steps":[{"t":"哥舒翰带军出潼关，向灵宝西原行进。战场南靠山、北临黄河，道路狭窄，大队人马难以展开。","s":["《资治通鉴·卷218》"]},{"t":"崔乾祐把精兵伏在险处，正面以疏散队形示弱。唐军看到对方兵少，继续向前，进入伏击地段。","s":["《资治通鉴·卷218》"]},{"t":"伏兵从高处投下木石，唐军前部受阻，后续仍在狭道中拥挤，长兵器难以发挥，阵形开始混乱。","s":["《资治通鉴·卷218》"]},{"t":"唐军用毡车开路，燕军以草车纵火。烟焰遮蔽视线，唐军误判敌方位置，弓弩不断向烟中发射。","s":["《资治通鉴·卷218》"]},{"t":"燕骑从南山绕到唐军后方，前后夹击。唐军溃退，许多人在挤压中坠河，哥舒翰带少数骑兵退回关中。","s":["《资治通鉴·卷218》"]},{"t":"崔乾祐攻克潼关。哥舒翰想收集散卒再守，却被火拔归仁等劫持，送往燕军，关中防线由此崩溃。","s":["《资治通鉴·卷218》"]}],"gloss":[],"cities":["长安","洛阳（秦汉至隋唐）","成都"],"people":["唐玄宗","安禄山","杨国忠","郭子仪","李光弼"],"src":["《资治通鉴·卷218》"],"line":"哥舒翰率唐军出潼关迎战，灵宝战败后关隘失守，唐玄宗离开长安，局势急转。","leaders":[{"side":"甲方","t":"哥舒翰、王思礼、庞忠、田良丘等，诸部所处位置与任务不同。","s":["《资治通鉴·卷218》"]},{"side":"乙方","t":"崔乾祐；安禄山在洛阳统摄。","s":["《资治通鉴·卷218》"]}],"short":"潼关","timeShort":"756","placeShort":"陕西潼关、河南灵宝","sides":"唐／安禄山军","result":"唐军败，潼关失守","sideA":"甲方","sideB":"乙方"},{"name":"睢阳之战","group":"第四组·隋唐五代","tags":["内战叛乱","攻城守城"],"g":"部分待核","lat":34.4,"lon":115.6,"f":[{"k":"时间","v":"756—757；756年为雍丘等前期战事，睢阳核心围城在757年，至德二载十月城陷（原书历月）。","s":["《旧唐书·张巡传》"]},{"k":"地点","v":"河南省商丘市睢阳区一带，古名睢阳；此前雍丘战事在今河南杞县。","s":["《旧唐书·张巡传》"]},{"k":"交战双方","v":"唐守军对安史燕军；757主攻时安庆绪已取代安禄山。","s":["《旧唐书·张巡、许远传》"]},{"k":"起因","v":"安史军向河南推进，争夺通往江淮的交通。张巡此前坚守河南杞县（雍丘），后来转移，与许远合守河南商丘（睢阳）。守住睢阳能够牵制这一方向的燕军，但城中必须依靠粮食与外围援军才能持续抵抗。尹子奇大军来攻，各路唐军未能形成稳定援助，战事逐渐转入长期围困。","s":["《旧唐书·张巡传》"]},{"k":"结果与影响","v":"睢阳陷落，守军覆败，居民在围困中也遭受饥饿与死亡。《旧唐书》记城内粮尽后发生食人，留下了平民灾难的沉重记录。守军长期抵抗牵制燕军，唐朝其他战线则继续反攻，并在同年收复两京。睢阳的经过显示，城墙和临阵抵抗能延缓进攻，但在粮道被断、外援不到的情况下，守军最终失去了继续支撑的条件。","s":["《旧唐书·张巡传》"]},{"k":"史料说明","v":"《旧唐书》对守将有鲜明的忠义评价，也记食人等惨事；关于人数及责任的叙述，尚有史料讨论。","s":["《旧唐书·张巡传》"]}],"steps":[{"t":"张巡到睢阳后，与许远分工守城。许远处理城政和供给，张巡主持作战，共同抵挡尹子奇的进攻。","s":["《旧唐书·张巡传》"]},{"t":"燕军反复攻城，守军依靠城垣和器械抵抗，也出城接战，试图打乱围城部队的部署。","s":["《旧唐书·张巡传》"]},{"t":"张巡组织夜袭和袭营等行动，暂时减轻城防压力。燕军仍继续围困，城内粮食不断减少。","s":["《旧唐书·张巡传》"]},{"t":"南霁云出城向外求援，没有带回足以解围的军队。城内外联系受阻，饥饿与伤亡使守军越来越少。","s":["《旧唐书·张巡传》"]},{"t":"757年十月，城防终于被攻破。张巡、南霁云等被杀，许远被送往洛阳后遇害，长期守御结束。","s":["《旧唐书·张巡传》"]}],"gloss":[],"cities":["长安","洛阳（秦汉至隋唐）"],"people":["张巡","安禄山","唐玄宗"],"src":["《旧唐书·卷187下·张巡、许远传》"],"line":"张巡、许远坚守睢阳，长期围城耗尽城中粮食，城破后二人遇害，守军抵抗结束。","leaders":[{"side":"甲方","t":"张巡、许远、南霁云、雷万春等；许远偏重城政供给，张巡主持作战。","s":["《旧唐书·张巡、许远传》"]},{"side":"乙方","t":"尹子奇。","s":["《旧唐书·张巡传》"]}],"short":"睢阳","timeShort":"756—757（核心围城为757）","placeShort":"河南商丘","sides":"唐／安史叛军","result":"睢阳陷","sideA":"甲方","sideB":"乙方"},{"name":"黄巢攻陷长安","group":"第四组·隋唐五代","tags":["内战叛乱","攻城守城"],"g":"部分待核","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"唐广明元年十二月，传统纪年作880年，公历跨入881年初。具体公历日待核。〔待核〕","s":["《资治通鉴·卷254》"]},{"k":"地点","v":"陕西省西安市唐长安城区域，进军经过洛阳、潼关及灞上。","s":["《资治通鉴·卷254》"]},{"k":"交战双方","v":"黄巢军对唐军。","s":["《资治通鉴·卷254》"]},{"k":"起因","v":"黄巢起兵后转战南北，唐朝各道军队未能合围，河南防线又因兵变、粮饷短缺和部队退散而失去衔接。黄巢军由南向北进入洛阳，进一步威胁潼关。唐廷急调神策军与关外部队守关，但军粮和援兵都未准备充分，京城前面能够依靠的屏障越来越薄弱。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]},{"k":"结果与影响","v":"唐失去京城，黄巢以长安为中心建立大齐，唐僖宗则在四川继续维持朝廷。各地军镇随后参与反攻，长安又多次易手，唐中央对地方军队的依赖进一步加深。黄巢入城使京城秩序和官僚体系受到严重破坏，也改变了诸军之间的权力关系。唐朝仍延续到907年，大齐与唐廷的争夺只是晚唐政治军事重组中的一个重要阶段。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]},{"k":"史料说明","v":"陷城记于唐广明元年十二月，对应公历跨入881年初；传统“880年陷长安”沿用旧历所属年份。具体回推日期尚有历法换算问题。〔待核〕","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]}],"steps":[{"t":"黄巢军进入洛阳，继续向关中推进。唐廷派张承范等赶赴潼关，守军急需粮食，求援却迟迟未获满足。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]},{"t":"齐克让所部退到潼关，关内外兵员增多，供给更加困难。黄巢军随即进攻，守军勉强抵挡。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]},{"t":"黄巢军从正面和旁路突破，唐军溃退，部分退军又为其引路，潼关防线瓦解。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]},{"t":"田令孜带唐僖宗离开长安，向四川逃去。城内秩序混乱，柴存等前锋先入，黄巢随后进入京城。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]},{"t":"黄巢在含元殿称帝，国号大齐、改元金统，任命官员。初入城时有安抚，随后又发生抢掠与杀戮。","s":["《资治通鉴·卷253》","《资治通鉴·卷254》"]}],"gloss":[],"cities":["长安","洛阳（秦汉至隋唐）","成都"],"people":["黄巢","唐僖宗","朱温"],"src":["《资治通鉴·卷253》","《资治通鉴·卷254》"],"line":"黄巢军突破潼关进入长安，唐僖宗奔成都，黄巢建立大齐，唐廷随后组织反攻。","leaders":[{"side":"甲方","t":"黄巢、尚让、柴存。","s":["《资治通鉴·卷254》"]},{"side":"乙方","t":"齐克让、张承范、王师会、赵珂；分别在潼关及相关防线行动，唐僖宗、田令孜负责京城决策与撤离。","s":["《资治通鉴·卷254》"]}],"short":"黄巢入长安","timeShort":"880（旧历纪年；公历跨881年初，详见卡）","placeShort":"陕西西安","sides":"黄巢军／唐","result":"长安陷，后立大齐","sideA":"甲方","sideB":"乙方"},{"name":"高平之战","group":"第四组·隋唐五代","tags":["关键转折"],"g":"部分待核","lat":35.7,"lon":112.9,"f":[{"k":"时间","v":"954，后周显德元年三月（原书历月），周世宗即位后不久。","s":["《资治通鉴·卷291》"]},{"k":"地点","v":"山西省晋城市高平市南部至巴公一带，古名高平、巴公原，另有向北追击。","s":["《资治通鉴·卷291》"]},{"k":"交战双方","v":"后周对北汉及辽援军，辽军参战程度应据具体行动，不与北汉混写为一支军队。","s":["《资治通鉴·卷291》"]},{"k":"起因","v":"后周太祖去世，周世宗即位不久，北汉刘崇认为新君初立、局势未稳，联合辽军南下。后周朝臣对皇帝亲征有疑虑，世宗仍决定亲自迎击，阻止北汉军深入。双方围绕山西南部交战，北汉希望借外援打开进入中原的道路，后周则需要保住边防并巩固新君的统治。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]},{"k":"结果与影响","v":"后周击退北汉与辽的进攻，周世宗即位初年的局势得到稳定。战中出现的逃将、降卒与临阵整队，使世宗进一步整饬军纪、选练士卒。北汉仍据晋阳，后周接着进围，也未能攻克。赵匡胤在战中立功，后来继续在后周军中上升。高平之战的前后变化说明，初战失利后能否稳住队伍，以及后军何时到达，都会改变一场会战的结局。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]}],"steps":[{"t":"北汉、辽军向南推进，周世宗率前军北上，在山西高平以南接敌，后军尚未全部赶到。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]},{"t":"张元徽率北汉军攻击后周右翼，樊爱能、何徽带部逃走，部分步卒投降，周军一度陷入危局。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]},{"t":"世宗继续督战，赵匡胤、张永德等重整部队，组织反击，阻止败退扩大到全军。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]},{"t":"张元徽战死，北汉阵线动摇，辽将杨衮未能有效投入救援，联军之间的协同受到影响。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]},{"t":"刘词率后军赶到，继续攻击北汉余部，刘崇退向晋阳。周军获胜后，世宗追究逃将责任，并整顿军队。","s":["《资治通鉴·卷291》","《资治通鉴·卷292》"]}],"gloss":[],"cities":["开封（汴州、东京、大梁）","晋阳"],"people":["后周世宗","北宋太祖","张永德","李重进"],"src":["《资治通鉴·卷291》","《资治通鉴·卷292》"],"line":"后周军与北汉、辽军在高平交战，周世宗重整退却的部队反击获胜，稳住即位局势。","leaders":[{"side":"甲方","t":"后周世宗、张永德、赵匡胤、李重进、向训、刘词。","s":["《资治通鉴·卷291》"]},{"side":"乙方","t":"刘崇、张元徽、杨衮；杨衮名在《通鉴》作杨兖等，《通鉴》另作杨兖。","s":["《资治通鉴·卷291》"]}],"short":"高平","timeShort":"954","placeShort":"山西晋城高平市","sides":"后周／北汉、辽","result":"后周胜","sideA":"甲方","sideB":"乙方"},{"name":"高梁河之战","group":"第五组·两宋辽金元","tags":["边疆与对外"],"g":"部分待核","lat":39.9,"lon":116.3,"f":[{"k":"时间","v":"979，宋太平兴国四年、辽乾亨元年；主要接战在七月（原书历月）。","s":["《宋史·太宗纪》","《辽史·景宗纪下》"]},{"k":"地点","v":"北京市西直门外至西北郊相关地区，古名高梁河、幽州，古河道与具体阵线仍有定位问题。〔待核〕","s":[]},{"k":"交战双方","v":"宋对辽。","s":["《宋史·太宗纪》","《辽史·景宗纪下》"]},{"k":"起因","v":"宋灭北汉后，宋太宗决定乘势北进，夺取辽控制的北京（幽州）及燕云地区。此前围攻太原已消耗兵员和物资，继续出征还需要组织粮草与攻城器械。宋军很快抵达幽州城下，希望在辽援军集齐之前破城；辽则调动各路部队赴援，准备在城外反击。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]},{"k":"结果与影响","v":"宋夺取幽州的行动失败，辽继续控制燕云要地。灭北汉后的连续远征，在城池久攻不下、援军到达的情况下转成败退，宋廷必须重新安排北方防御。此后宋辽仍有多次交战，边境关系继续变化。高梁河把一场攻城行动与城外援军的机动交战连在一起，宋军尚未解决补给和破城问题，就已需要应对辽军在外围的集中反击。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]},{"k":"史料说明","v":"《宋史》与《辽史》各自着重本方行动，对会战部署和败退细节记载详略不同。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]}],"steps":[{"t":"宋军由北汉故地继续北上，抵达北京（幽州），围攻城池。城内辽军坚守，宋军未能迅速打开缺口。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]},{"t":"辽援军陆续靠近，先到的部分部队与宋军交战不利，幽州的围困仍在继续。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]},{"t":"耶律休哥、耶律斜轸等继续组织援军，从不同方向接近宋军，准备配合城内守军解围。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]},{"t":"双方在高梁河一带交战，辽骑兵发起反击。宋军原来的围城与野战部署遭到冲击，部队向南败退。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]},{"t":"宋太宗脱离战区，剩余军队陆续撤回。幽州之围解除，宋军未能保持此次北进取得的前沿阵地。","s":["《宋史·太宗纪》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"]}],"gloss":[],"cities":["开封（汴州、东京、大梁）","晋阳","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["北宋太宗","辽景宗","耶律休哥","耶律斜轸","曹彬","潘美"],"src":["《宋史·卷4·太宗纪一》","《辽史·卷9·景宗纪下》","《辽史·卷83·耶律休哥传》"],"line":"宋太宗灭北汉后进攻幽州，在高梁河遭辽军反击，宋军败退，收取幽州的行动受挫。","leaders":[{"side":"甲方","t":"宋太宗；曹彬、潘美等参与本轮北征。〔待核〕","s":["《宋史·太宗纪》"]},{"side":"乙方","t":"耶律休哥、耶律斜轸、耶律沙等。","s":["《辽史·耶律休哥传》"]}],"short":"高梁河","timeShort":"979","placeShort":"北京西北一带","sides":"宋／辽","result":"宋军败退","sideA":"甲方","sideB":"乙方"},{"name":"澶州之战","group":"第五组·两宋辽金元","tags":["边疆与对外","攻城守城"],"g":"部分待核","lat":35.7,"lon":115.0,"f":[{"k":"时间","v":"1004，宋景德元年、辽统和二十二年；辽军进至澶州及宋帝到达在该年冬，议和书信跨入原书十二月。","s":["《宋史·真宗纪》","《辽史·圣宗纪》"]},{"k":"地点","v":"河南省濮阳市濮阳县一带，古名澶州、澶渊，战事涉及黄河两岸城防。","s":["《宋史·真宗纪》"]},{"k":"交战双方","v":"宋对辽。","s":["《宋史·真宗纪》","《辽史·圣宗纪》"]},{"k":"起因","v":"宋辽在北边长期交战，辽圣宗与萧绰于1004年率军大举南下，绕过部分坚城，深入河北，直逼黄河边的河南濮阳（澶州）。宋廷对迁避还是亲征意见不同，寇准等主张皇帝到前线稳定军心。宋真宗遂北上，澶州的城防、黄河通道与两国的议和接触同时成为局势关键。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]},{"k":"结果与影响","v":"宋辽在澶州对峙后议和，订立澶渊之盟，辽军北撤，宋按约定向辽输送岁币，两国边境关系进入新的阶段。澶州未被攻破，皇帝赴前线也帮助宋军稳住防守。辽方深入河北，仍须考虑背后的宋军据点与补给，双方都面对继续作战的成本。战场上的相持为谈判提供了条件，此后使节往来与边境贸易逐渐成为维持关系的重要渠道。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]},{"k":"史料说明","v":"《宋史》侧重宋帝亲征和朝廷决策，《辽史》侧重辽军南下与和约，两方叙述视角不同。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]}],"steps":[{"t":"辽军南下穿过河北，向澶州推进，宋各地守军据城抵抗。辽军深入后，后方仍有宋军据点。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]},{"t":"辽军抵近澶州，宋将李继隆等组织守御，在城外与渡河方向布置兵力，阻止其继续向南。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]},{"t":"萧挞凛在前线中弩身亡，辽军失去重要将领。双方继续对峙，城防没有迅速被打破。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]},{"t":"宋真宗在寇准、高琼等催促和护卫下到达前线，登临北城，士卒见皇帝到来，军心受到鼓舞。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]},{"t":"两国使者往返，商谈停战条件。双方随后达成和约，辽军撤回，澶州交战转入较长期的边境议和安排。","s":["《宋史·卷7·真宗纪二》","《辽史·卷14·圣宗纪五》","《宋史·卷281·寇准传》"]}],"gloss":[],"cities":["开封（汴州、东京、大梁）","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["北宋真宗","寇准","辽圣宗","萧绰","萧挞凛"],"src":["《宋史·卷7·真宗纪二》","《宋史·卷281·寇准传》","《辽史·卷14·圣宗纪五》","《辽史·卷85·萧挞凛传》"],"line":"辽军南下抵达澶州，宋真宗赴前线督战，两军对峙后议和，宋辽订立澶渊之盟。","leaders":[{"side":"甲方","t":"宋真宗、李继隆、高琼等；寇准参与决策并督促亲征。","s":["《宋史·寇准传》","《宋史·真宗纪》"]},{"side":"乙方","t":"辽圣宗、萧绰、萧挞凛等。","s":["《辽史·圣宗纪》","《辽史·萧挞凛传》"]}],"short":"澶州","timeShort":"1004","placeShort":"河南濮阳","sides":"宋／辽","result":"战线对峙后议和","sideA":"甲方","sideB":"乙方"},{"name":"好水川之战","group":"第五组·两宋辽金元","tags":["边疆与对外","战法典型"],"g":"部分待核","lat":35.6,"lon":106.1,"f":[{"k":"时间","v":"1041，宋庆历元年二月（原书历月）。","s":["《宋史·任福传》"]},{"k":"地点","v":"宁夏回族自治区固原市隆德县及六盘山相关地区，古名好水川，常见定位在隆德好水一带。〔待核〕","s":[]},{"k":"交战双方","v":"宋对西夏。","s":["《宋史·任福传》"]},{"k":"兵力与伤亡","v":"《宋史·任福传》记任福出征统兵一万八千；同篇叙朱观、武英等部交战，记士卒死六千余。前者是此次出动规模，后者属于该段战斗的伤亡记录。","s":["《宋史·卷325·任福传及附传》"]},{"k":"起因","v":"李元昊称帝后，宋夏关系转入大规模战争，西夏军威胁宋的泾原边地。韩琦派任福等出兵，希望利用敌军深入的机会，寻找有利位置伏击其归路。他要求各部合兵，形势不利便据险待机。任福等前进时遇敌获小胜，继续追赶，逐渐离开原定的行动条件，粮食和接应也越来越困难。","s":["《宋史·卷325·任福传及附传》"]},{"k":"结果与影响","v":"宋在泾原方向遭受严重损失，多名将领死亡，原来寻机出击的部署落空。韩琦预定的合兵、据险与等待归敌，在前线追击中没有贯彻，山谷道路又削弱了各部之间的联络。西夏得以集中攻击先后进入的宋军，宋廷随后继续调整边防与将领任用。宋夏战争仍延续数年，后来的和议还涉及其他战场与双方政治选择。","s":["《宋史·卷325·任福传及附传》"]}],"steps":[{"t":"任福率军出动，以桑怿等为前锋。宋军初遇西夏部队，获得小胜，继续沿山谷道路追击。","s":["《宋史·卷325·任福传及附传》"]},{"t":"西夏军边退边引，宋军向好水川一带深入。各部在狭窄道路中分散行进，难以随时互相接应。","s":["《宋史·卷325·任福传及附传》"]},{"t":"宋军粮食不足，仍继续前进，进入西夏主力可以集中攻击的位置。伏兵出现，前后多部相继投入战斗。","s":["《宋史·卷325·任福传及附传》"]},{"t":"任福、桑怿所部遭到重击，两人战死。朱观、武英等在另一处迎敌，王珪等赶来作战，也未能恢复局势。","s":["《宋史·卷325·任福传及附传》"]},{"t":"宋军各部继续抵抗，伤亡扩大，王珪、武英等先后死去。朱观带余部退回，此次出击最终失败。","s":["《宋史·卷325·任福传及附传》"]}],"gloss":[],"cities":["开封（汴州、东京、大梁）","兴庆府"],"people":["北宋仁宗","西夏景宗","韩琦","任福"],"src":["《宋史·卷325·任福传及附传》"],"line":"宋将任福率军追击西夏军，在好水川陷入包围，任福战死，宋军此次出击遭重创。","leaders":[{"side":"甲方","t":"任福、桑怿、朱观、武英、王珪；韩琦负责方面部署。","s":["《宋史·任福传》"]},{"side":"乙方","t":"李元昊。","s":["《宋史·任福传》"]}],"short":"好水川","timeShort":"1041","placeShort":"宁夏固原隆德等地（定位待核）","sides":"宋／西夏","result":"宋军败，任福死","sideA":"甲方","sideB":"乙方"},{"name":"靖康之战与汴京陷落","group":"第五组·两宋辽金元","tags":["改朝换代","攻城守城"],"g":"部分待核","lat":34.8,"lon":114.3,"f":[{"k":"时间","v":"1126—1127；第一次围城在1126年，第二次城破记靖康元年闰十一月，公历已入1127年初，二帝北迁在1127年春。具体换算日待核。〔待核〕","s":["《宋史·钦宗纪》"]},{"k":"地点","v":"河南省开封市，古名东京、汴京，宋代城防包括外城、内城与宫城。","s":["《宋史·钦宗纪》"]},{"k":"交战双方","v":"金对北宋。","s":["《宋史·钦宗纪》","《金史·宗望、宗翰传》"]},{"k":"起因","v":"宋金结盟后，在燕云交割、边地归属和接纳降人等问题上发生冲突。金军分路南下，宋朝边防迅速失守，宋徽宗退位，钦宗即位。朝廷在守战与议和之间反复，开封虽有城防，仍需要可靠军队、粮饷和外援。第一次围城暂时解除后，双方争端未平，金军又准备发动新一轮进攻。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"k":"结果与影响","v":"北宋东京朝廷结束，皇室、官员和居民遭俘迁，京城人口、财物与制度机构蒙受巨大损失。金在中原取得重要优势，曾扶立张邦昌政权；赵构随后在南方即位，重建宋朝中枢，南宋由此开始。两次围城之间的交涉、城破后的控制和春季北迁前后延续，灾难逐步扩大。宋金战争并未结束，双方继续围绕中原和江淮展开争夺。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"k":"史料说明","v":"第二次城破记于靖康元年闰十一月，对应公历已入1127年初；俘帝北迁在其后春季。具体换算日仍待核。〔待核〕","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]}],"steps":[{"t":"1126年，金东路军逼近河南开封（汴京），李纲等组织城防，种师道率部赴援，守军抵御金军攻势。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"t":"宋军尝试出击，姚平仲夜袭金营失败。金军未能攻破都城，双方转入交涉，围城暂时解除。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"t":"宋廷答应割地、赔款，金军退去，但交地与履约仍有争议。朝廷调整守战官员，边境防御未能稳定恢复。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"t":"金两路军再次南下，太原等要地相继失守。宗翰、宗望所部在开封方向会合，把都城重新包围。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"t":"宋各路援军未能解围，城内防御与粮饷日益困难。孙傅等依赖郭京所称的“六甲”出战，守城部署受到影响。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"t":"郭京出城作战失利，金军乘守备混乱登城，汴京外部防线崩溃。宋廷此后仍不断交涉，试图保全皇室与朝廷。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]},{"t":"金军控制徽宗、钦宗及大批宗室、官民，索取财物。1127年春，俘虏陆续被押往北方，北宋中枢覆亡。","s":["《宋史·钦宗纪》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》","《宋史·高宗纪》"]}],"gloss":[],"cities":["开封（汴州、东京、大梁）","晋阳","会宁"],"people":["北宋徽宗","北宋钦宗","李纲","种师道","完颜宗望","完颜宗翰","南宋高宗"],"src":["《宋史·卷23·钦宗纪》","《宋史·卷24·高宗纪一》","《宋史·卷358·李纲传》","《金史·卷74·宗望、宗翰传》"],"line":"金军两度围攻汴京，城破后掳走宋徽宗、钦宗，北宋朝廷覆亡，南宋随后建立。","leaders":[{"side":"甲方","t":"完颜宗望、完颜宗翰。","s":["《金史·宗望、宗翰传》"]},{"side":"乙方","t":"李纲、种师道、姚平仲等参与第一次守御；第二次由孙傅等组织城防，郭京率部出战。","s":["《宋史·钦宗纪》","《宋史·李纲传》"]}],"short":"靖康之战","timeShort":"1126—1127","placeShort":"河南开封","sides":"金／北宋","result":"宋徽宗、钦宗被俘","sideA":"甲方","sideB":"乙方"},{"name":"郾城之战","group":"第五组·两宋辽金元","tags":["边疆与对外","战法典型"],"g":"部分待核","lat":33.6,"lon":114.0,"f":[{"k":"时间","v":"1140，南宋绍兴十年七月（原书历月）。","s":["《宋史·岳飞传》"]},{"k":"地点","v":"河南省漯河市郾城区一带，古名郾城；稍后颍昌作战在今河南许昌。","s":["《宋史·岳飞传》"]},{"k":"交战双方","v":"南宋岳飞军对金完颜宗弼军。","s":["《宋史·岳飞传》"]},{"k":"起因","v":"宋金此前议和，金内部政局变化后，完颜宗弼重新向河南、陕西进攻。宋军各路迎战，岳飞所部进入河南，分兵占守多处城邑。金军看到岳飞部队分散，向河南漯河（郾城）集中兵力，希望击破他所在的主力。这一方向的交锋与顺昌、颍昌等地战事相连，宋金都在争夺河南的主动。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]},{"k":"结果与影响","v":"据《岳飞传》，宋军击退了金军对郾城的进攻，接着又在颍昌作战，保住这一轮推进中的部分阵地。各部后来奉命撤回，宋金继续交涉，最终形成绍兴和议。郾城的胜利反映步骑配合及前线应援的作用，也发生在多路宋军共同迎战的背景中。金方本传对河南行动另有叙述重点，两方材料对具体战术与战果保留的信息并不相同。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]},{"k":"史料说明","v":"《宋史·岳飞传》叙述较详，《金史·宗弼传》未同样展开郾城战术；宋传所记“三马相联”的拐子马形象，其装备与编组解释仍有争议。〔待核〕","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]}],"steps":[{"t":"岳飞军向河南推进，分别占守各地，岳飞驻郾城。完颜宗弼等集中军队来攻，准备打破宋军部署。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]},{"t":"岳飞派岳云率骑兵接战，鼓励各部坚守，金军骑兵反复冲击，双方在城外持续交战。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]},{"t":"宋步兵与骑兵配合抵抗。《岳飞传》记步卒持麻扎刀攻击马足，金军进攻受阻。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]},{"t":"金军未能击破郾城阵地，转而调整进攻方向。杨再兴在随后的小商桥交战中战死。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]},{"t":"金军又攻颍昌，岳云赶去支援王贵，宋军继续迎战。郾城、颍昌的攻守相继展开，河南战线仍在变化。","s":["《宋史·岳飞传》","《金史·卷77·宗弼传》"]}],"gloss":[],"cities":["杭州（临安）","开封（汴州、东京、大梁）","许昌"],"people":["岳飞","南宋高宗","完颜宗弼"],"src":["《宋史·卷365·岳飞传》","《金史·卷77·宗弼传》"],"line":"金军进攻郾城，岳飞率军迎战并守住阵地，宋金在河南的战事随后仍然继续。","leaders":[{"side":"甲方","t":"岳飞、岳云、杨再兴等；王贵在颍昌部署。","s":["《宋史·岳飞传》"]},{"side":"乙方","t":"完颜宗弼、韩常及龙虎大王、盖天大王等原书记载的统帅。","s":["《宋史·岳飞传》"]}],"short":"郾城","timeShort":"1140","placeShort":"河南漯河郾城区","sides":"南宋／金","result":"岳飞军守住郾城","sideA":"甲方","sideB":"乙方"},{"name":"采石之战","group":"第五组·两宋辽金元","tags":["水战","边疆与对外"],"g":"部分待核","lat":31.7,"lon":118.5,"f":[{"k":"时间","v":"1161，南宋绍兴三十一年十一月（原书历月）。","s":["《宋史·虞允文传》"]},{"k":"地点","v":"安徽省马鞍山市雨山区采石矶及对岸和县一带，涉及采石、杨林渡和两岸江面。","s":["《宋史·虞允文传》"]},{"k":"交战双方","v":"南宋对金。","s":["《宋史·虞允文传》","《金史·海陵纪》"]},{"k":"兵力与伤亡","v":"《宋史·虞允文传》称金军“实四十万”、宋军一万八千；四十万是该传对金方大军的记数，一万八千是采石宋方部队数。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"k":"起因","v":"完颜亮率金军大举南侵，宋淮西军退却，长江沿岸出现部队散乱、指挥未接的空当。虞允文奉命到安徽马鞍山（采石）犒军，发现新任主将尚未抵达，金军却即将渡江。他决定临时召集现有水陆部队，组织防守，阻止金军在南岸站稳，再向南京建康方向推进。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"k":"结果与影响","v":"宋军守住采石一线，金军未能由此渡江直趋建康，沿江防御获得重新部署的时间。完颜亮随后转向瓜洲，其南侵还受到金国内部另立皇帝、军心变化与其他战场失利的影响，最终失败。采石交战中，虞允文把临时集结的部队组织起来，江中拦截与岸上阻击相互支援，阻止对方将北岸的军力转化为南岸的稳定据点。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"k":"史料说明","v":"“实四十万”是《虞允文传》的原文表述；同篇另记金船数百艘渡江、七十艘一度抵南岸，渡江部队与北岸大军口径不同。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]}],"steps":[{"t":"虞允文抵达采石，召集散卒，鼓励将士守江。岸上部队列阵，水军按江中、沿岸与伏舟分层布置。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"t":"完颜亮在北岸督促渡江，金军乘船向南岸冲来，部分船只靠近滩岸，宋军一度动摇。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"t":"虞允文进入阵中催促作战，时俊等率部迎击。宋水军截击江中船队，岸上部队抵挡已经登陆的金兵。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"t":"金军渡江受阻，船队遭损失，宋军继续追击。虞允文又调整伏舟，防备第二天的进攻。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]},{"t":"金军再次行动仍未取得突破，随后转向其他渡江方向。虞允文赴镇江检查防务，完颜亮后来在瓜洲一带被部下杀死。","s":["《宋史·虞允文传》","《金史·卷5·海陵纪》"]}],"gloss":[],"cities":["南京（建业、建康、金陵、应天、天京）","杭州（临安）","开封（汴州、东京、大梁）"],"people":["虞允文","南宋高宗","金海陵王","陈康伯"],"src":["《宋史·卷383·虞允文传》","《金史·卷5·海陵纪》"],"line":"完颜亮率金军南下，虞允文在采石组织宋军水陆迎击，金军渡江受阻，战局生变。","leaders":[{"side":"甲方","t":"虞允文、时俊等；虞允文奉命犒师，到达后组织水陆部队迎战。","s":["《宋史·虞允文传》"]},{"side":"乙方","t":"完颜亮及渡江各部。","s":["《宋史·虞允文传》"]}],"short":"采石","timeShort":"1161","placeShort":"安徽马鞍山采石一带","sides":"南宋／金","result":"金军渡江受阻","sideA":"甲方","sideB":"乙方"},{"name":"钓鱼城之战","group":"第五组·两宋辽金元","tags":["攻城守城","边疆与对外"],"g":"部分待核","lat":30.0,"lon":106.3,"f":[{"k":"时间","v":"1259，南宋开庆元年、蒙古蒙哥汗九年；攻城主要在该年春夏，蒙哥七月死（原书历月）。","s":["《元史·宪宗纪》"]},{"k":"地点","v":"重庆市合川区钓鱼山，古名合州钓鱼城，依山地及嘉陵江等水系设防。","s":["《元史·宪宗纪》"]},{"k":"交战双方","v":"南宋对蒙古；1259尚未改国号元。","s":["《元史·宪宗纪》"]},{"k":"兵力与伤亡","v":"《元史·宪宗纪》记1259年七月留精兵三千继续守围，其余军队转攻重庆；三千是调整部署后留下的部队数。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"k":"起因","v":"蒙古组织多路攻宋，蒙哥亲率军队进入四川，希望突破宋军的山城防线，再与其他方向相配合。南宋此前在四川经营山城和水路据点，合州钓鱼城凭借山地与嘉陵江等水系设防。蒙古军接近合州后，王坚率守军抵抗，山城与周边交通成为双方持续争夺的目标。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"k":"结果与影响","v":"钓鱼城在本轮围攻中得以守住，蒙哥亲征被其死亡打断，宋军获得防御时间。蒙古最高权力的继承随后引发竞争，各战场的行动也受到政治变化影响。合州一带并未从此停战，宋蒙双方仍长期攻守。山城的地形、外城与主城分层防御，使攻方多次局部得手后仍难继续深入；持续降雨也直接影响了夜袭和梯具使用。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"k":"史料说明","v":"《元史·宪宗纪》先记六月“不豫”，再记七月去世；炮石、箭伤及具体疾病等死因说法的对应证据仍待核。〔待核〕","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]}],"steps":[{"t":"蒙哥军向合州推进，遣人招降王坚，王坚拒绝。蒙古军渡过鸡爪滩，到石子山一带，开始逼城。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"t":"1259年二月、三月，蒙古军接连攻击一字城、镇西门及东新门等处，试图从不同部位打破防线。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"t":"四月雷雨持续，蒙古军仍进攻护国门，并曾夜登外城。局部突破后，守军继续抵抗，主城没有失守。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"t":"六月，攻方再选兵夜登外城马军寨，王坚率部来战。天亮遇雨，攻城梯折断，后军未能跟进。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]},{"t":"《宪宗纪》记蒙哥六月患病，七月去世。蒙古军随后撤离、调整部署，这一轮围攻结束，守军保住城寨。","s":["《元史·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"]}],"gloss":[],"cities":["杭州（临安）","哈拉和林"],"people":["元宪宗","南宋理宗","余玠"],"src":["《元史·卷3·宪宗纪》","《元史·卷155·汪世显传附汪德臣》","《宋史·卷416·余玠传》"],"line":"蒙古军围攻钓鱼城，守将王坚据城抵抗，蒙哥在围城期间去世，蒙古军随后撤退。","leaders":[{"side":"甲方","t":"王坚；张珏参与守城，其具体职掌有待核实。〔待核〕","s":["《元史·宪宗纪》"]},{"side":"乙方","t":"蒙哥、汪德臣、汪良臣等所属攻城部队。","s":["《元史·宪宗纪》","《元史·汪世显传附汪德臣》"]}],"short":"钓鱼城","timeShort":"1259","placeShort":"重庆合川","sides":"南宋／蒙古","result":"蒙古攻城未克，蒙哥死后撤军","sideA":"甲方","sideB":"乙方"},{"name":"襄阳之战","group":"第五组·两宋辽金元","tags":["攻城守城","关键转折"],"g":"部分待核","lat":32.0,"lon":112.1,"f":[{"k":"时间","v":"1268—1273；蒙古1268起长期围困，1271改国号元，1273樊城破、襄阳降。","s":["《宋史·度宗纪》","《元史·阿术传》"]},{"k":"地点","v":"湖北省襄阳市襄城区、樊城区，襄阳与樊城分处汉水两岸。","s":["《元史·阿术传》"]},{"k":"交战双方","v":"南宋对蒙古军，1271以后称元军。","s":["《宋史·度宗纪》","《元史·阿术传》"]},{"k":"兵力与伤亡","v":"《元史·阿术传》记张顺、张贵装军衣百船入援，张贵出城后余众败死；百船是这次运送军需的船队规模。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"k":"起因","v":"蒙古此前进攻南宋受阻，转而加强舟师和长期封锁，选择汉水两岸的襄阳、樊城作为重点。两城互相支援，扼守汉水通向长江的道路，宋军可以凭城防和江面运输维持抵抗。刘整等建议训练水军、断绝援路，蒙古军于是筑堡围城，将争夺变成一场持续数年的水陆消耗。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"k":"结果与影响","v":"襄樊失守，南宋荆襄防线的重要支点落入元军手中，元军获得沿汉水进入长江的有利条件。吕文焕等降将熟悉当地形势，又参与后续进军。南宋仍继续抵抗，长江战事、临安投降与海上朝廷的转移还在其后。五年围困中，城中储粮能延长守御，浮桥和水路援助却不断受打击，最后攻樊、断援与襄阳投降相继发生。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"k":"史料说明","v":"《阿术传》《阿里海牙传》对樊城陷落的月次有不同记法；1273年为樊城破、襄阳降的通行系年。“回回炮”指大型抛石器。","s":["《元史·阿术传》","《宋史·度宗纪》"]}],"steps":[{"t":"1268年起，蒙古军在襄樊周围筑堡，控制陆路与汉水通道。宋军组织增援，受到围军与舟师拦截。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"t":"围困逐渐收紧，宋方依靠储粮继续守城，外援虽多次进攻，却未能建立稳定的运输路线。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"t":"1272年，张顺、张贵率船运送军需冲入包围。张顺战死，张贵一度进城，襄阳获得一批补给。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"t":"张贵后来出城联络，元军预先在江上拦截，张贵被俘遇害，援军再次失败，封锁仍未解除。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"t":"元军集中进攻樊城，破坏两城之间的浮桥，使用大型抛石器攻城。樊城失去对岸接应，最终被攻破。","s":["《元史·阿术传》","《宋史·度宗纪》"]},{"t":"吕文焕据守的襄阳孤立，随后投降。元军控制汉水两岸据点，开始准备进一步向长江推进。","s":["《元史·阿术传》","《宋史·度宗纪》"]}],"gloss":[],"cities":["杭州（临安）","江陵","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["南宋度宗","元世祖","阿术","贾似道","史天泽"],"src":["《宋史·卷46·度宗纪》","《元史·卷128·阿术、阿里海牙传》"],"line":"蒙古军长期围困襄樊，攻破樊城后迫使吕文焕献襄阳投降，南宋长江防线出现缺口。","leaders":[{"side":"甲方","t":"吕文焕、范天顺、牛富；李庭芝、范文虎等参与外援，张顺、张贵率舟突破围困。","s":["《宋史·度宗纪》","《元史·阿术传》"]},{"side":"乙方","t":"阿术、刘整、阿里海牙等。","s":["《元史·阿术传》","《元史·阿里海牙传》"]}],"short":"襄阳","timeShort":"1268—1273","placeShort":"湖北襄阳","sides":"南宋／蒙古（1271后称元）","result":"樊城陷，襄阳降","sideA":"甲方","sideB":"乙方"},{"name":"崖山海战","group":"第五组·两宋辽金元","tags":["改朝换代","水战"],"g":"部分待核","lat":22.3,"lon":113.1,"f":[{"k":"时间","v":"1279，南宋祥兴二年、元至元十六年二月癸未（原书历月日）。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》"]},{"k":"地点","v":"广东省江门市新会区崖门水道及崖山一带，古名崖山、厓山，古海口与今岸线已有变化。","s":["《宋史·张世杰传》"]},{"k":"交战双方","v":"元对南宋海上朝廷及其军民船队。","s":["《宋史·张世杰、陆秀夫传》"]},{"k":"兵力与伤亡","v":"《宋史·张世杰传》记宋方结大舶千余成水寨，张世杰最后以十余舰脱出；两数分别是联船水寨和突围船队的规模。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"k":"起因","v":"1276年临安降元后，宋臣拥立二王，带着朝廷沿福建、广东海岸转移。端宗死后，群臣拥立帝昺，最后驻在广东江门（崖山）。张世杰希望借联结船队稳定军心，保护幼帝与随行官民，元军则沿海追来，准备控制海口，消灭这个仍在运作的宋朝政治中心。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"k":"结果与影响","v":"帝昺死亡，南宋最后的朝廷失去政治与军事中心，元完成消灭宋中央政权的主要步骤。部分部队虽然脱出，已难重新组成原来的海上朝廷。张世杰以后还试图收集残军，随后遇风身亡。崖山的作战围绕联船水寨、海口与淡水通道展开；元军封锁使随行军民共同陷入困境，最后的突破又压缩了中军撤离与护送幼帝的机会。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"k":"史料说明","v":"宋方船队载有士卒、官员与家属，船数、随行人口与战斗员人数属于不同统计；浮尸记载同样涉及军民。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]}],"steps":[{"t":"张世杰把大船联结成水寨，选择固守崖山。有人建议先据海口、保留退路，他担心移动后人员离散，没有采纳。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"t":"张弘范等元军抵达，控制海口与进出道路。宋船队的樵采、取水受阻，长期停泊的人员开始缺水缺粮。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"t":"宋军与元军反复交战，张世杰仍不接受招降。联结的船队虽能集中防御，转移和突围却越来越困难。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"t":"元军从不同方向攻击水寨，逐渐逼近宋军中部，宋军队列遭突破。具体潮汐与各路进攻次序仍有讨论。〔待核〕","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]},{"t":"张世杰割断船缆，带部分舰船脱出。陆秀夫负帝昺投海，海上朝廷覆亡；张世杰后来又在风浪中溺死。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》","《元史·卷129·李恒传》"]}],"gloss":[],"cities":["杭州（临安）","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["南宋帝昺","张世杰","陆秀夫","元世祖"],"src":["《宋史·卷451·张世杰、陆秀夫传》","《元史·卷156·张弘范传》","《元史·卷129·李恒传》"],"line":"南宋最后的朝廷退至崖山，张弘范率元军进攻，宋军战败，陆秀夫负宋末帝投海。","leaders":[{"side":"甲方","t":"张弘范、李恒。","s":["《元史·张弘范传》","《元史·李恒传》"]},{"side":"乙方","t":"张世杰、苏刘义等；陆秀夫主持朝政并护帝。","s":["《宋史·张世杰、陆秀夫传》"]}],"short":"崖山","timeShort":"1279","placeShort":"广东江门新会","sides":"元／南宋","result":"宋军败，宋末帝死","sideA":"甲方","sideB":"乙方"},{"name":"鄱阳湖之战","group":"第六组·明清","tags":["水战","关键转折"],"g":"部分待核","lat":29.1,"lon":116.2,"f":[{"k":"时间","v":"1363，元至正二十三年；七月至八月为主要作战阶段（原书历月）。","s":["《明史·太祖本纪》"]},{"k":"地点","v":"江西省鄱阳湖及湖口通道，主要古地名有鄱阳湖、康郎山，水位与岸线随时代变化。","s":["《明史·太祖本纪》"]},{"k":"交战双方","v":"朱元璋所属军队对陈友谅汉政权军；1363朱元璋尚未建立明朝。","s":["《明史·太祖本纪》"]},{"k":"兵力与伤亡","v":"《明史·太祖本纪》记陈友谅军“号六十万”，这是陈方号称兵力；同篇记一次火攻中使用敢死船七艘，属于具体攻击编组。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"k":"起因","v":"元末各方争夺长江流域，朱元璋据南京应天，陈友谅控制长江中游，双方围绕江西和江上交通反复交战。1363年，陈友谅率大军围攻南昌洪都，守军坚持数月。朱元璋决定亲自率军救援，并先部署湖口等地，准备在陈军撤围后截击其舟师，阻断回到上游的道路。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"k":"结果与影响","v":"陈友谅战死，陈汉主力遭受重创，朱元璋在长江中游的主要竞争对手由此削弱。陈理仍在武昌继位，直到1364年才向朱元璋投降。朱元璋随后继续整合江西、湖广资源，再转向其他对手。鄱阳湖的胜负经过连续船战、火攻和封锁逐步形成，湖口控制使败军难以返回根据地，粮食耗尽又迫使其在不利条件下突围。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"k":"史料说明","v":"“六十万”原文冠以“号”；《太祖本纪》《陈友谅传》对船战、火攻与出湖突围的叙述各有侧重。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]}],"steps":[{"t":"朱元璋率军救洪都，在湖口和相关水道预设兵力。陈友谅得知援军到来，撤去围城，在鄱阳湖迎战。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"t":"两军在康郎山一带接战。陈军以大型战船联结布阵，朱军船较小，仰攻困难，战斗多次反复。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"t":"张定边突击朱元璋坐船，坐船一度搁浅。常遇春、俞通海等来援，朱元璋得以脱险，继续督战。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"t":"风势转强后，朱军用装载引火物的船只实施火攻。陈方联船受到延烧，朱军趁乱冲击，陈军损失扩大。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"t":"朱军接着扼守出湖通道，陈军退泊相持，部分将领投降，粮食越来越少，陈友谅决定突围。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]},{"t":"双方在出湖方向再次激战，陈友谅中箭身亡。张定边护陈理等退回武昌，朱军取得这一轮水上决战的胜利。","s":["《明史·太祖本纪》","《明史·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"]}],"gloss":[],"cities":["南京（建业、建康、金陵、应天、天京）"],"people":["明太祖","徐达","常遇春","陈友谅"],"src":["《明史·卷1·太祖本纪一》","《明史·卷123·陈友谅传》","《明史·卷133·俞通海传》","《明史·卷129·廖永忠传》"],"line":"朱元璋与陈友谅在鄱阳湖交战，火攻和封锁相继展开，陈友谅战死，陈汉主力受挫。","leaders":[{"side":"甲方","t":"朱元璋、徐达、常遇春、廖永忠、俞通海等，参战时段与水陆职掌不同。","s":["《明史·太祖本纪》","《明史·俞通海传》","《明史·廖永忠传》"]},{"side":"乙方","t":"陈友谅、张定边、陈友仁等。","s":["《明史·陈友谅传》"]}],"short":"鄱阳湖","timeShort":"1363","placeShort":"江西鄱阳湖","sides":"朱元璋／陈友谅汉","result":"陈友谅死，其军败","sideA":"甲方","sideB":"乙方"},{"name":"明军攻占大都","group":"第六组·明清","tags":["改朝换代","统一战争","攻城守城"],"g":"部分待核","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1368，明洪武元年、元至正二十八年八月（原书历月），明军进入大都。","s":["《明史·徐达传》","《元史·顺帝纪》"]},{"k":"地点","v":"北京市元大都城区域，明军从通州等方向接近。","s":["《明史·徐达传》"]},{"k":"交战双方","v":"明对元；明已在本年正月建立，不是占大都之后才取得国号。","s":["《明史·太祖本纪》"]},{"k":"起因","v":"朱元璋在南方击败主要竞争势力后，派徐达、常遇春北伐。明军先取山东、河南，再向河北推进，逐渐削弱元廷与腹地的联系。元朝中央与北方军阀彼此牵制，难以统一调集力量。明军接近北京大都时，元顺帝在守城与北迁之间作出选择，京畿的防御局势随之变化。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]},{"k":"结果与影响","v":"元失去大都和中原统治中心，明取得北方具有重大政治意义的都城，为扩大统治提供了条件。元顺帝北走后，北方元政权及其军队仍继续存在，明还需要长期处理北边战事。占领大都以后，明廷一面接收人口和财赋，一面筹划其他地区的统一。1368年的都城易手标志中原王朝统治的转移，后续征服与边防建设则延续多年。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]}],"steps":[{"t":"徐达等先攻取山东、河南要地，切断部分南北交通，再向河北发展，逐渐把战线推进到大都南面。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]},{"t":"明军进入通州方向，大都受到直接威胁。元廷议论守御与退避，朝廷未能组织足以挡住明军的京畿防线。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]},{"t":"元顺帝携后妃、太子等离开大都，向上都方向转移。留守官员与部队继续面对明军进逼。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]},{"t":"徐达率军进入大都，接收宫城、官署与府库，留城的抵抗力量被控制，城市转入明军掌握。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]},{"t":"徐达整顿军纪，清理图籍，城市改称北平。元廷仍在北方活动，明军随后继续向其他元军据点进攻。","s":["《明史·徐达传》","《元史·顺帝纪》","《明史·卷2·太祖本纪二》"]}],"gloss":[],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）","开平／元上都","南京（建业、建康、金陵、应天、天京）"],"people":["明太祖","徐达","常遇春","元顺帝"],"src":["《明史·卷2·太祖本纪二》","《明史·卷125·徐达传》","《元史·卷47·顺帝纪》"],"line":"徐达率明军北伐进入大都，元顺帝北走，元朝在中原的统治结束，北方政权继续。","leaders":[{"side":"甲方","t":"徐达、常遇春。","s":["《明史·徐达传》"]},{"side":"乙方","t":"元顺帝朝廷及京城留守诸部；元顺帝在明军入城前北走。","s":["《元史·顺帝纪》"]}],"short":"攻占大都","timeShort":"1368","placeShort":"北京","sides":"明／元","result":"明占大都，元帝北走","sideA":"甲方","sideB":"乙方"},{"name":"靖难之役","group":"第六组·明清","tags":["内战叛乱","关键转折"],"g":"部分待核","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"1399—1402，明建文元年至四年；1402六月燕军进入南京（原书历月）。","s":["《明史·成祖本纪》"]},{"k":"地点","v":"河北、山东至江苏南京，战场涉及北平、白沟河、济南、东昌及长江沿线。","s":["《明史·成祖本纪》"]},{"k":"交战双方","v":"燕王朱棣军对建文皇帝中央军，均属明朝内部势力。","s":["《明史·成祖本纪》"]},{"k":"兵力与伤亡","v":"《明史·成祖本纪》记朱棣起事前潜纳勇士八百入府，又记李景隆一阶段“合兵五十万”；分别是起事准备和一轮朝廷军集结数字。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"k":"起因","v":"明太祖分封诸王，北方藩王掌握军队和地方影响。建文帝即位后削藩，数位宗王先后被处置，燕王朱棣担心自身地位受到威胁。他与僧道衍等筹划，以“清君侧”“靖难”为名起兵，矛头指向建文朝廷。朝廷则调集大军征讨，皇室内部的权力冲突迅速扩大为南北多年的战争。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"k":"结果与影响","v":"朱棣取得皇位，建文朝廷败亡，明朝仍以原国号延续。战争重组了中央与将领集团，靖难功臣得到封赏，建文旧臣遭到政治清算。朱棣此后经营北京，逐渐把权力重心移向北方。战争中燕军曾在济南、东昌受阻，后来通过绕过坚城、直趋南京取得胜利，说明争夺首都与控制沿途每一座城，并非同步完成。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"k":"史料说明","v":"《成祖本纪》依据的胜利者材料较多；建文帝在宫火中的结局与出亡说，在《恭闵帝纪》中保留了不同层次的记载。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]}],"steps":[{"t":"1399年，朱棣在北平夺取城门和军队，控制周边关口。耿炳文率朝廷军来讨，遭燕军击败，朝廷改派李景隆。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"t":"李景隆进攻北平，朱棣则向永平、大宁等处行动，再回师迎击。战争从北平周边扩大到河北多地。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"t":"1400年，燕军在白沟河击败李景隆，继续南攻济南。铁铉、盛庸等坚守，朱棣久攻未下，只得撤围。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"t":"燕军在东昌再战失利，张玉战死。此后双方仍在河北、山东反复交锋，朝廷的坚城继续阻挡燕军南进。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"t":"朱棣改变逐城攻取的办法，绕过部分据点，向淮河、长江方向快速推进。1402年，燕军突破阻击并渡江。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]},{"t":"燕军逼近南京，城门被打开，朱棣入城，宫中起火。建文帝下落留下不同记载，朱棣随后即位，改定朝廷秩序。","s":["《明史·成祖本纪》","《明史·卷4·恭闵帝纪》","《明史·卷130·耿炳文传》","《明史·徐达传》"]}],"gloss":[],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）","南京（建业、建康、金陵、应天、天京）"],"people":["明惠帝","明成祖","姚广孝","方孝孺"],"src":["《明史·卷4·恭闵帝纪》","《明史·卷5·成祖本纪一》","《明史·卷125·徐辉祖传》","《明史·卷130·耿炳文传》"],"line":"燕王朱棣起兵与建文朝廷争夺皇位，转战河北山东后攻入南京，随后即皇帝位。","leaders":[{"side":"甲方","t":"朱棣、张玉、朱能、丘福、朱高煦等。","s":["《明史·成祖本纪》"]},{"side":"乙方","t":"耿炳文、李景隆、盛庸、平安、铁铉、徐辉祖等，指挥权随阶段更替。","s":["《明史·成祖本纪》","《明史·耿炳文传》"]}],"short":"靖难","timeShort":"1399—1402","placeShort":"河北、山东至江苏南京","sides":"燕王朱棣／建文朝廷","result":"朱棣入南京即位","sideA":"甲方","sideB":"乙方"},{"name":"土木堡之战","group":"第六组·明清","tags":["边疆与对外","关键转折"],"g":"部分待核","lat":40.4,"lon":115.5,"f":[{"k":"时间","v":"1449，明正统十四年八月（原书历月）；英宗亲征、撤军及土木堡溃败相接。","s":["《明史·英宗前纪》"]},{"k":"地点","v":"河北省张家口市怀来县土木堡一带。","s":["《明史·英宗前纪》"]},{"k":"交战双方","v":"明对瓦剌部军，亦涉及蒙古各部不同进攻方向。","s":["《明史·英宗前纪》","《明史·王振传》"]},{"k":"兵力与伤亡","v":"《明史纪事本末·土木之变》记亲征官军五十余万人，属于该书所记出征总数。","s":["《明史纪事本末·卷32·土木之变》","《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"k":"起因","v":"瓦剌与明在边境使团、贸易及政治关系上发生冲突，也先大举进攻。明英宗在王振推动下仓促亲征，部队出发后遇到风雨与道路困难，粮草准备也不足。明军抵达大同方向，发现局势不利，决定返回北京。瓦剌追击使后卫接连失利，主力最终退到河北怀来（土木堡）一带。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"k":"结果与影响","v":"明英宗被俘，随征主力和大批官员损失，北京受到更直接的军事威胁。朝廷随后拥立景泰帝，于谦等组织保卫北京，阻止瓦剌进一步控制京城。英宗以后获释回国，皇位关系又成为朝廷内部的新问题。土木堡发生在远征撤回途中，粮水、后卫接应和移营秩序的困难连续叠加，使仓促出发的军队在接近本方城池时仍遭到严重失败。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"k":"史料说明","v":"《明史》本纪与《王振传》对回师、议和和移营详略不同；出征总数也与土木堡被围时的实到队伍属于不同口径。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]}],"steps":[{"t":"明军自北京出发，经居庸关、宣府向大同行进。连日风雨，运输不畅，随军将士逐渐缺粮疲惫。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"t":"前方军事形势恶化，明军改向东退。瓦剌沿途追击，后卫部队受创，撤军队伍难以保持有序接应。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"t":"朱勇等率兵迎击后败死，主力退到土木堡驻扎。驻地缺少便利水源，周围又受到瓦剌控制。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"t":"双方出现议和接触，明军随后移动营地，争取水源或继续撤走。疲惫拥挤的队伍在移动时难以保持阵形。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]},{"t":"瓦剌发起攻击，明军溃乱，英宗被俘，张辅与多名随征官员死亡。败讯传到北京，朝廷开始另行组织防御。","s":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"]}],"gloss":[],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）","平城"],"people":["明英宗","王振","于谦","明代宗"],"src":["《明史·卷10·英宗前纪》","《明史·卷304·王振传》"],"line":"明英宗亲征瓦剌，回师途中在土木堡被围，明军溃败、皇帝被俘，北京面临危机。","leaders":[{"side":"甲方","t":"明英宗、朱勇、张辅等；王振以宦官身份干预出征决策。","s":["《明史·英宗前纪》","《明史·王振传》"]},{"side":"乙方","t":"也先等。","s":["《明史·英宗前纪》"]}],"short":"土木堡","timeShort":"1449","placeShort":"河北张家口怀来县","sides":"瓦剌／明","result":"明军败，明英宗被俘","sideA":"甲方","sideB":"乙方"},{"name":"萨尔浒之战","group":"第六组·明清","tags":["边疆与对外","关键转折"],"g":"部分待核","lat":41.9,"lon":124.2,"f":[{"k":"时间","v":"1619，明万历四十七年、后金天命四年三月（原书历月）。","s":["《明史·杨镐传》","《清史稿·太祖本纪》"]},{"k":"地点","v":"辽宁省抚顺市及附近地区，各路战场涉及萨尔浒、界藩、尚间崖等地。","s":["《明史·杨镐传》"]},{"k":"交战双方","v":"明及朝鲜、叶赫等协同力量对后金；1619尚不称清。","s":["《明史·杨镐传》","《清史稿·太祖本纪》"]},{"k":"兵力与伤亡","v":"《明史·杨镐传》记明军“号大兵四十七万”，并记战后文武将吏死三百一十余、军士死四万五千八百余；分别是号称兵力和该传记录的人员损失。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"k":"起因","v":"后金建立后进攻抚顺，明廷调兵征讨，希望恢复辽东主动。杨镐计划分四路向后金中心赫图阿拉推进，期待各军会合。辽东山川、雪天与补给增加了协同困难，各路出发和到达时间并不一致。努尔哈赤获悉明军分进，决定集中主力，先打最早深入的部队，再迅速转击其他方向。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"k":"结果与影响","v":"明军征讨失败，三路遭到重大打击，后金守住根据地，取得继续向辽东扩张的有利条件。明廷追究杨镐等责任，之后又面对开原、铁岭相继失守的危机。四路分进原本希望形成包围，实际各路距离、时间与消息难以衔接，使后金能够在不同战场连续集中兵力。明军的总规模因此没有同时转化为同一阵地上的力量，辽东攻守关系随之改变。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"k":"史料说明","v":"李如柏一路奉令退回，其他三路先后失败；四路的战斗发生在不同地点和时段。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]}],"steps":[{"t":"明军四路出动，杜松西路进展较快，在萨尔浒、界藩一带分兵设营和进攻，率先接近后金主力。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"t":"努尔哈赤集中军队，先攻杜松营地，再打其前出部队。杜松战死，西路军溃败，四路会合计划被打断。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"t":"后金随即转向马林北路，利用兵力集中和高地攻击，击破马林各营，明军又一路败退。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"t":"刘綎东路继续深入，未能及时获知其他各路完整败情。后金转兵来攻，刘綎战死，朝鲜姜弘立等所部随后投降。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]},{"t":"杨镐急令尚在前进的部队收兵，李如柏南路撤回。明军此次征讨结束，后金则继续争夺辽东其他据点。","s":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》"]}],"gloss":[],"cities":["赫图阿拉","辽阳","沈阳","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["明神宗","清太祖","清太宗","代善"],"src":["《明史·卷259·杨镐传》","《清史稿·卷1·太祖本纪》","《明史纪事本末·卷32·土木之变》"],"line":"明军分路进攻后金，努尔哈赤集中兵力逐路迎击，明军多路战败，辽东攻守局势改变。","leaders":[{"side":"甲方","t":"杨镐统筹，杜松、马林、刘綎、李如柏分领四路；姜弘立率朝鲜军随刘綎方向行动。","s":["《明史·杨镐传》"]},{"side":"乙方","t":"努尔哈赤、代善、皇太极等。","s":["《清史稿·太祖本纪》"]}],"short":"萨尔浒","timeShort":"1619","placeShort":"辽宁抚顺","sides":"后金／明及盟军","result":"后金击败明多路军","sideA":"甲方","sideB":"乙方"},{"name":"李自成攻陷北京","group":"第六组·明清","tags":["改朝换代","攻城守城"],"g":"部分待核","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1644，明崇祯十七年三月十九日北京陷落（旧历）。","s":["《明史·庄烈帝纪》"]},{"k":"地点","v":"北京市明北京城及周边，崇祯帝死亡地点为煤山。","s":["《明史·李自成传》"]},{"k":"交战双方","v":"李自成大顺军对明北京朝廷及守军。","s":["《明史·李自成传》"]},{"k":"起因","v":"明末灾荒、军饷短缺和持续内战相互加剧，西北主要军力遭到削弱。李自成在陕西建立大顺，随后沿山西向京畿快速推进，明军多处防线失守。北京朝廷急召勤王军，仍未能及时形成外围屏障。守城、谈判与皇室迁避的意见反复出现，城中粮饷和军心也日益脆弱。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]},{"k":"结果与影响","v":"明北京朝廷覆亡，大顺占据首都，却很快又在山海关失利，李自成退出北京，京城随后转入清军控制。明宗室在南京及其他南方地区继续建政，战争向更广地区发展。北京的陷落既是明中枢崩解的结果，又改变了吴三桂、清军与大顺之间的选择。短时间内首都反复易手，使1644年的王朝更替呈现多个前后相接的军事政治阶段。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]},{"k":"史料说明","v":"《明史》保存的城门失守记载仍需与同时人材料对读；崇祯帝死亡、大顺入京与清军入京各有先后。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]}],"steps":[{"t":"大顺军进入山西，取得多处要地，继续向宣府、大同及京畿方向推进，沿路明军降败，北京外援通道受到威胁。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]},{"t":"昌平、居庸关等地失守，大顺军抵达北京附近。崇祯帝催促调兵与守御，仍未等到足以解除危机的援军。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]},{"t":"城外进攻与议降同时进行，守军动摇，部分城门防御瓦解。各门开闭的时序和责任仍有不同记载。〔待核〕","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]},{"t":"李自成军进入北京，崇祯帝在煤山自缢，明朝在京的中央机构失去皇帝和统一指挥。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]},{"t":"大顺接收京城，随即面对山海关吴三桂部和关外清军的压力。明宗室则在南方另组朝廷，继续维持明的国号。","s":["《明史·庄烈帝纪》","《明史·李自成传》","《清史稿·世祖本纪》"]}],"gloss":[],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）","长安","南京（建业、建康、金陵、应天、天京）"],"people":["李自成","明思宗","吴三桂"],"src":["《明史·卷24·庄烈帝纪二》","《明史·卷309·李自成传》","《清史稿·卷4·世祖本纪一》"],"line":"李自成军攻入北京，崇祯帝自缢，明朝北京朝廷覆亡，明宗室随后在南方继续建政。","leaders":[{"side":"甲方","t":"李自成、刘宗敏、李过等；各部参与攻城。","s":["《明史·李自成传》"]},{"side":"乙方","t":"明思宗主持中枢决策，李国桢提督京营，王承恩等参与内廷与城防事务。","s":["《明史·庄烈帝纪》","《明史·李自成传》"]}],"short":"陷北京","timeShort":"1644","placeShort":"北京","sides":"大顺／明","result":"北京陷，崇祯帝死","sideA":"甲方","sideB":"乙方"},{"name":"山海关之战","group":"第六组·明清","tags":["改朝换代","关键转折"],"g":"部分待核","lat":40.0,"lon":119.7,"f":[{"k":"时间","v":"1644，清顺治元年四月二十二日为主要决战日（原书历月日），与北京陷落相隔一月余。","s":["《清史稿·世祖本纪》"]},{"k":"地点","v":"河北省秦皇岛市山海关区及石河一带。","s":["《清史稿·吴三桂传》"]},{"k":"交战双方","v":"清军、吴三桂部对大顺军；吴部从明军转入与清合作的政治过程须写明。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》"]},{"k":"起因","v":"北京陷落后，吴三桂驻在山海关方向，面对大顺招降和关外清军的压力。李自成希望取得吴部与关口，吴三桂则在归附与抵抗之间转变，最后向多尔衮求援。清军乘机向山海关接近，把救援条件与吴部归附相连。京城新局势、关口控制和军队去向，使三方迅速走向决战。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]},{"k":"结果与影响","v":"清军与吴三桂合作击败大顺，取得进入关内、控制北京的关键条件。大顺失去京畿主动，但其军队此后仍在西部和南方活动。清政权早已建立，战后逐步把中央迁入北京，又继续进攻各地。吴三桂的归附同时改变了军事与政治关系，使清军能够利用关口、明军部众和原有道路快速推进，山海关因而成为这一轮权力转移的重要节点。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]},{"k":"史料说明","v":"清在1636年已使用清国号；山海关获胜促进入关与占京，大顺的后续败亡仍有另外的过程。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]}],"steps":[{"t":"李自成自北京东进，吴三桂据山海关抵御，并向清军联络。多尔衮率军由关外向关口靠近。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]},{"t":"吴三桂急求援兵，多尔衮要求其归附，吴部接受政治条件，双方开始建立军事协作。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]},{"t":"吴军先与大顺军激战，战斗持续，双方主力在关外石河等区域争夺，吴军承受很大压力。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]},{"t":"清军随后投入进攻，冲击大顺阵线。大顺军无法保持原来的攻势，李自成率部向北京退却。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]},{"t":"大顺返回北京后继续西撤，清军经山海关进入关内，再向京城推进。北京易手，山海关获胜的成果转入清方手中。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》","《明史·李自成传》"]}],"gloss":[],"cities":["沈阳","北京（蓟、幽州、燕京、中都、大都、北平、京师）","长安"],"people":["清世祖","多尔衮","吴三桂","李自成"],"src":["《清史稿·卷4·世祖本纪一》","《清史稿·卷474·吴三桂传》","《明史·卷309·李自成传》"],"line":"吴三桂与大顺军在山海关交战，清军入战后击败大顺，随后进占北京，局势转折。","leaders":[{"side":"甲方","t":"多尔衮、吴三桂；清世祖未亲临前线。","s":["《清史稿·世祖本纪》"]},{"side":"乙方","t":"李自成、刘宗敏等。","s":["《明史·李自成传》"]}],"short":"山海关","timeShort":"1644","placeShort":"河北秦皇岛山海关","sides":"清、吴三桂／大顺","result":"大顺败退","sideA":"甲方","sideB":"乙方"},{"name":"收复台湾之战","group":"第六组·明清","tags":["边疆与对外","攻城守城"],"g":"部分待核","lat":23.0,"lon":120.2,"f":[{"k":"时间","v":"1661—1662；1661年渡海登陆，1662年荷方签约交出热兰遮城。","s":["《先王实录》","《清史稿·郑成功传》"]},{"k":"地点","v":"台湾台南地区，涉及鹿耳门、赤嵌普罗民遮城和热兰遮城。","s":["《先王实录》"]},{"k":"交战双方","v":"郑成功军对荷兰东印度公司在台驻军；不是清军对荷军。","s":["《先王实录》"]},{"k":"兵力与伤亡","v":"《先王实录》记郑成功出征前判断荷方“城中夷伙，不上千人”；这是郑方战前对城内荷方人员的估数。","s":["《先王实录》"]},{"k":"起因","v":"郑成功在大陆沿海与清军作战，进攻南京失败后，更需要稳定的军粮、人口与驻军基地。台湾西南部有荷兰东印度公司经营的城堡、商业和行政体系，也有熟悉当地的人员为郑方提供消息。郑成功筹备舟师渡海，决定夺取这一地区，建立能够长期屯军、耕作和供应沿海作战的根据地。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]},{"k":"结果与影响","v":"荷兰东印度公司在台湾西南部的主要据点被郑军夺取，郑氏由此建立在台的军政与屯垦基础。郑成功不久去世，后继政权继续经营当地，并保持与大陆沿海的联系。其实际控制以已占据的西部地区为中心，全岛仍有不同的地方社群与权力关系。1683年清郑战争又改变了台湾归属，与1661至1662年郑荷之间的围城各属不同阶段。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]},{"k":"史料说明","v":"《先王实录》出自郑方随征官员，详细记录军需与部署；荷方增援、谈判和人员损失另有本方记录，立场与统计各异。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]}],"steps":[{"t":"1661年，郑军从金厦方向出发，经澎湖趋向台湾，利用鹿耳门等水道接近台南，建立登陆据点。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]},{"t":"郑军上岸后攻击赤嵌及周边荷军阵地，切断部分交通。普罗民遮城守军随后投降，郑军取得一处重要据点。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]},{"t":"热兰遮城继续抵抗，郑成功分兵控制近郊、安排屯垦，同时围城，试图切断城堡的粮食和外部联系。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]},{"t":"荷方从海上增援并尝试反击，双方围绕舰船、城外阵地和补给持续交战，围困延续至次年。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]},{"t":"郑军夺取外围防御位置，加强对主堡的压力。揆一经过谈判投降，交出城堡，荷方人员依约撤离。","s":["《先王实录》","《清史稿·卷224·郑成功传》"]}],"gloss":[],"cities":["南京（建业、建康、金陵、应天、天京）","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["郑成功","清世祖"],"src":["杨英《先王实录·永历十五、十六年相关记事》","《清史稿·卷224·郑成功传》"],"line":"郑成功渡海进攻台湾，围攻荷兰东印度公司据点，荷方在次年投降，郑军控制台南。","leaders":[{"side":"甲方","t":"郑成功、杨朝栋、刘国轩、陈泽等，各部参与登陆、陆战与围城。","s":["《先王实录》"]},{"side":"乙方","t":"揆一及公司驻军各部；揆一（Frederick Coyett）为驻台长官。","s":["《先王实录》","《清史稿·郑成功传》"]}],"short":"收复台湾","timeShort":"1661—1662","placeShort":"台湾台南","sides":"郑成功军／荷兰东印度公司","result":"荷方据点投降","sideA":"甲方","sideB":"乙方"},{"name":"第一次鸦片战争","group":"第六组·明清","tags":["边疆与对外"],"g":"部分待核","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"依指定范围列1839—1842，1839为禁烟及局部冲突前奏；通常以1840英国远征军到来作为战争起点，至1842议和停战。","s":["《清史稿·宣宗本纪》"]},{"k":"地点","v":"广东、福建、浙江、江苏等沿海及长江下游，涉及虎门、厦门、定海、镇海、吴淞、镇江、江宁。","s":["《清史稿·宣宗本纪》"]},{"k":"交战双方","v":"清对英国。","s":["《清史稿·宣宗本纪》"]},{"k":"起因","v":"英国商人输入鸦片与清朝禁烟发生尖锐冲突，林则徐在广东收缴销毁鸦片，珠江口随后出现武装交火。英国政府决定派远征军，以武力要求赔偿和通商、外交安排。清廷先在广东组织防务，又随英军沿海北上而不断调兵，沿海多处炮台、港口和谈判逐步卷入战争。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"k":"结果与影响","v":"清在沿海和长江主要战场失利，被迫签订南京条约，割地、赔款与通商安排改变了对外关系。战争同时暴露舰队、炮台、弹药、训练、通信和指挥之间的差距，各地抵抗未能形成稳定的整体防御。英军依靠海上机动，在不同地点选择攻击，再利用长江交通施压。清廷此后需要应对新的通商口岸和外交要求，军事失败的影响延伸到财政、行政与沿海治理。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"k":"史料说明","v":"1839年为禁烟与局部交火前奏，英国远征军于1840年来华，战争通常断为1840—1842年；条目沿用含前奏的1839—1842年。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]}],"steps":[{"t":"1839年，广东禁烟，虎门销烟后珠江口局部交火。1840年，英国远征军封锁沿海，攻定海，再北上天津方向迫使清廷交涉。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"t":"1841年，战事回到珠江口，英军进攻虎门炮台，关天培战死。广东防线受损，清方继续派员交涉和调兵。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"t":"英军迫近广州，清军作战失利，双方谈判停战。局部停战后，英军继续沿海转移目标，战事仍在扩大。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"t":"英军攻取厦门，又进攻定海、镇海和宁波。葛云飞、裕谦等死，清军固定据点相继失守，援军难以统一行动。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"t":"1842年，清军在浙江发动反攻，未能扭转局势。英军继续攻击乍浦，再向吴淞、上海方向推进。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"t":"吴淞战斗中陈化成战死，英军进入长江下游。清军失去多处沿岸屏障，航运与内地交通受到直接威胁。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]},{"t":"英军攻取镇江，向南京江宁靠近。清廷派员议和，双方签订南京条约，主要军事行动结束。","s":["《清史稿·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"]}],"gloss":[],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）","南京（建业、建康、金陵、应天、天京）","番禺"],"people":["清宣宗","林则徐","关天培","琦善","耆英"],"src":["《清史稿·卷18、19·宣宗本纪》","《清史稿·卷19·宣宗本纪》","《清史稿·卷369·林则徐传》","《清史稿·卷372·关天培传》","《清史稿·卷154·邦交志·英国》"],"line":"英国舰队沿中国海岸和长江进攻，清军多处失利，清廷最终议和并签订南京条约。","leaders":[{"side":"甲方","t":"林则徐主持前期广东防务，关天培、葛云飞、裕谦、陈化成、海龄等分守各战场；奕山、奕经分别负责不同阶段的方面作战。","s":["《清史稿·林则徐传》","《清史稿·关天培传》","《清史稿·宣宗本纪》"]},{"side":"乙方","t":"懿律、伯麦、郭富等分别统领不同阶段海陆军；义律参与前期交涉。","s":["《清史稿·邦交志·英国》"]}],"short":"鸦片战争","timeShort":"1839—1842（前奏始于1839）","placeShort":"广东、浙江、江苏等沿海沿江","sides":"清／英国","result":"清战败议和","sideA":"甲方","sideB":"乙方"},{"name":"天京陷落","group":"第六组·明清","tags":["改朝换代","攻城守城"],"g":"部分待核","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"1864年7月19日（公历），清同治三年六月十六日（旧历）。","s":["《清史稿·曾国藩传》","《清史稿·曾国荃传》"]},{"k":"地点","v":"江苏省南京市明城墙及城内地区，太平天国称天京，主要爆破入城方向为太平门。","s":["《清史稿·曾国荃传》"]},{"k":"交战双方","v":"清军，主要为湘军对太平天国守军及朝廷。","s":["《清史稿·曾国藩传》","《清史稿·曾国荃传》"]},{"k":"兵力与伤亡","v":"《清史稿·曾国荃传》记破城后“毙贼十余万”、王将等三千余，另称解救难民数十万；这是清方报功叙述，所用敌我分类和各项人数属于不同口径。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"k":"起因","v":"湘军逐步夺取长江沿线据点，向南京天京收紧包围。太平天国失去周边补给区域，李秀成等虽试图解围和调动清军，仍未恢复持续交通。曾国荃在城外筑垒，逐段逼近城墙。1864年洪秀全去世，洪天贵福继位，城中粮食更加困难，守军仍继续抵抗最后的围攻。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"k":"结果与影响","v":"天京失守，太平天国主要中央机构瓦解，清军重新控制南京。各地太平军残部仍继续抵抗，战争并未在破城当天全部结束。城内居民遭到大规模杀戮与焚掠，人口和城市生活蒙受深重灾难。湘军取得胜利后，曾国藩、曾国荃等的政治地位进一步巩固；长期围城依靠地方募军、财赋和江上运输，也使晚清地方军事力量的影响更加突出。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"k":"史料说明","v":"《曾国荃传》又记最初误报幼天王已死，后来发现其仍在外转移；报功记录与人员实际结局出现出入。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]}],"steps":[{"t":"曾国荃率军围住天京，在城外建立营垒，收紧陆路和江面联系，守军的粮食运输越来越困难。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"t":"太平军多次试图从外围解围，未能打通稳定通道。清军继续夺取紫金山及周边阵地，把防线推进到城墙附近。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"t":"洪秀全在城破前去世，洪天贵福继位。城内政治交接时，清军仍在开掘地道、准备火药爆破。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"t":"清军炸开太平门附近城墙，李臣典、朱洪章等率部由缺口进入。城中继续发生抵抗、巷战和大规模混乱。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]},{"t":"李秀成护洪天贵福等突围，途中失散。李秀成后来被捕遇害，幼天王在外地继续转移，随后也被俘杀。","s":["《清史稿·卷405·曾国藩传》","《清史稿·曾国荃传》","《清史稿·洪秀全传》"]}],"gloss":[],"cities":["南京（建业、建康、金陵、应天、天京）","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["曾国藩","李秀成","洪秀全","清穆宗"],"src":["《清史稿·卷405·曾国藩传》","《清史稿·卷413·曾国荃传》","《清史稿·卷475·洪秀全传》"],"line":"湘军围攻天京并破城，太平天国都城失守、中央政权瓦解，各地部队仍继续作战。","leaders":[{"side":"甲方","t":"曾国荃、李臣典、朱洪章等负责城下作战，曾国藩统筹全局。","s":["《清史稿·曾国荃传》"]},{"side":"乙方","t":"李秀成、洪仁达等；洪秀全在城破前已死，幼天王洪天贵福为政权继承者。","s":["《清史稿·洪秀全传》"]}],"short":"天京陷落","timeShort":"1864","placeShort":"江苏南京","sides":"清／太平天国","result":"清军入城，太平天国都城失守","sideA":"甲方","sideB":"乙方"},{"name":"甲午黄海海战","group":"第六组·明清","tags":["水战","边疆与对外"],"g":"部分待核","lat":39.6,"lon":123.6,"f":[{"k":"时间","v":"1894年9月17日（公历），清光绪二十年八月十八日（旧历）。","s":["《清史稿·卷462·丁汝昌传》","《清史稿·卷460·邓世昌等传》","公历与旧历日期对照"]},{"k":"地点","v":"黄海北部、鸭绿江口外大东沟以南海域，古称大东沟海面。","s":["《清史稿·卷462·丁汝昌传》"]},{"k":"交战双方","v":"清北洋水师对日本联合舰队。","s":["《清史稿·卷462·丁汝昌传》"]},{"k":"兵力与伤亡","v":"《清史稿·邓世昌传》记清方“以铁舰十当敌舰十有二”；这是该传对接战舰数的记法，按船只计，具体编组范围另有差异。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"k":"起因","v":"清日围绕朝鲜的军事政治干预升级，1894年先后发生海陆冲突，继而正式开战。清方需要把援军送往朝鲜北部，北洋舰队护送运输船抵鸭绿江口附近。护运完成后，北洋舰队在黄海北部与日本联合舰队相遇，双方一面调整航向和队形，一面准备接战，海上行动与陆军增援因此直接相连。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"k":"结果与影响","v":"北洋舰队失去多舰和大批官兵，战后海上行动优势向日本倾斜。定远、镇远等剩余主力仍在，后来又参与港岸防御，直到1895年威海战役才遭最终覆败。黄海交战暴露了舰速、编队、信号与弹药等问题，具体责任在中日战报和军官记述中仍有不同说明。舰船损伤、指挥中断与各舰分散作战相互影响，削弱了北洋持续争夺制海权的能力。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"k":"史料说明","v":"《清史稿》卷462载丁汝昌传，卷460载邓世昌等传。卷460记致远中鱼雷、全船无人逃生，威海党史资料记舰载鱼雷爆炸、将士大多遇难；沉舰机制与人员结局的记载仍有差异。〔待核〕","s":["威海市党史研究院《邓世昌》","《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]}],"steps":[{"t":"北洋舰队完成护运后在鸭绿江口外活动，发现日本舰队接近。丁汝昌乘定远舰指挥，北洋各舰展开迎战。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"t":"双方接近后开炮，日舰以纵列等方式机动，北洋各舰依据原有部署应战，速度与位置影响彼此支援。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"t":"定远舰的指挥设施受损，丁汝昌受伤，舰队统一指挥受到影响。各舰继续射击、救火和调整航向。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"t":"超勇、扬威等舰受到猛烈打击，火灾与损伤扩大。致远、经远继续作战，邓世昌、林永升等在舰沉时死亡。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"t":"双方持续数小时炮战，日舰也有受损，北洋剩余主力仍能作战。战斗结束后，两支舰队相继脱离。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]},{"t":"北洋主力返回整修，广甲在撤退途中搁浅后毁弃。此后的旅顺、威海防御另行展开，舰队仍继续活动。","s":["《清史稿·卷460·邓世昌等传》","《清史稿·卷462·丁汝昌传》"]}],"gloss":[],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["清德宗","李鸿章","丁汝昌","邓世昌"],"src":["《清史稿·卷460·邓世昌、林永升等传》","外交部日期对照说明","《清史稿·卷462·丁汝昌传》"],"line":"北洋水师与日本联合舰队在黄海交战，致远等舰沉没，北洋舰队受损后返回基地。","leaders":[{"side":"甲方","t":"丁汝昌、刘步蟾、林泰曾、邓世昌、林永升等，分别承担舰队与各舰指挥。","s":["《清史稿·邓世昌等传》"]},{"side":"乙方","t":"伊东祐亨、坪井航三等；舰队具体指挥分工待核。〔待核〕","s":[]}],"short":"黄海海战","timeShort":"1894","placeShort":"黄海北部","sides":"清北洋水师／日本联合舰队","result":"北洋多舰损失，双方脱离","sideA":"甲方","sideB":"乙方"}],"systems":[{"title":"兵制的演变","t":"秦汉军队的征发与供养，同中央、郡国和边防相联。府兵通过军府组织，把番上宿卫、训练和出征连接起来；唐代长期边防需求增加，募兵逐步扩大。明代卫所以军户世籍补伍，后来又并用募兵和将领家丁。清朝八旗以旗籍组织人口与军队，绿营依省、镇、营、汛分布，晚清再兴勇营。同一朝代也存在不同兵源和供给方式，兵籍上的额数与临战到场人数各有口径。将领能否获得足够的训练时间、粮饷和补充兵员，直接影响制度在战场上发挥的作用。","s":["《汉书·卷23·刑法志》","《新唐书·卷50·兵志》","《明史·卷90·兵志二》","《清史稿·卷130、131·兵志》","《清史稿·卷131·兵志》","《清史稿·卷133·兵志》"]},{"title":"从车战到骑兵与步兵的战法变化","t":"城濮的车战已包含多部协同、佯退与侧击，战国赵武灵王推行胡服骑射，又反映对北方地形和对手的适应。到漠北远征，骑兵能深入沙漠以北，执行包围与追击，卫青仍用武刚车围营，为部队提供立足点。长平的营垒攻守依赖步兵，郾城则见步骑配合作战。车、骑、步在不同时代往往同时使用，各自承担任务；地形、马匹、兵员训练和补给能力，决定统帅如何搭配。一次交战中，先稳住营阵再用机动部队出击，也可能比单纯增加某一兵种更重要。","s":["《左传·僖公二十八年》","《史记·赵世家》","《史记·卫将军骠骑列传》","《史记·白起王翦列传》","《宋史·岳飞传》"]},{"title":"攻城与守城","t":"城墙把进攻者挡在外面，城内仍需粮水、守军轮换和城外援助。台城、睢阳都曾长期抵抗，随着补给耗尽和疾病增加，防守逐渐衰弱。攻方也会围绕城防条件选择办法：昆阳使用楼车、冲车与地道，秦攻大梁用水，湘军攻天京则在地道内安放火药爆破城墙。襄樊围困中，筑堡封路、江上截援与最后强攻相继展开，浮桥被毁又使双城难以互救。城墙厚度之外，粮道、水源和外援能否衔接，同样决定围攻持续多久以及守军还能支撑多少次进攻。","s":["《资治通鉴·卷162》","《旧唐书·张巡传》","《后汉书·光武帝纪上》","《史记·秦始皇本纪》","《清史稿·曾国荃传》","《元史·阿术传》"]},{"title":"水战与舟师","t":"赤壁的舟船与岸营相连，黄盖以火船接近，使火势从江面延伸到陆营；追击和疾疫又影响撤军。淝水则是临河列阵、退阵和渡水进攻，作战主体在陆上。采石把舟师拦截与南岸阻击结合，鄱阳湖又把连续船战、火攻与控制湖口连接起来。崖山联船水寨能集中防御，却受到海口与淡水封锁。到黄海海战，蒸汽舰船、舰炮、编队和信号改变了战斗条件。船舶性能、航道、风向、港岸与补给，在这些战事中各自发挥作用，也要求统帅协调水面与陆上行动。","s":["《三国志·周瑜传》","《晋书·苻坚载记下》","《宋史·虞允文传》","《明史·太祖本纪》","《宋史·张世杰、陆秀夫传》","《清史稿·卷462·丁汝昌传》"]},{"title":"粮道与后勤","t":"军队能否持续集中，依靠粮食、饮水、马料与运输，也依靠伤病和损耗能否得到补充。巨鹿楚军截断秦军甬道，官渡曹军焚毁乌巢，直接打击前线赖以维持的供应。襄樊援船一度入城，围军仍能截住后续运输，使守军逐渐孤立。街亭取水道路被断，崖山汲水与樵采受封，也都迅速影响战斗能力。漠北远征还要付出大量马匹损耗。仓储、路线、护送和接收是一条连续的供给链，任何一环长期中断，人数众多的军队也可能无法按原计划作战。","s":["《史记·项羽本纪》","《三国志·武帝纪》及裴松之注","《元史·阿术传》","《三国志·张郃传》","《宋史·张世杰、陆秀夫传》","《史记·卫将军骠骑列传》"]},{"title":"火药和火器进入战场","t":"引火物、火药弹、管形火器与机械抛石器有各自结构和用途。《宋史》记1259年寿春制作竹筒突火枪，利用火药发出子窠；襄樊的回回炮则是大型抛石机械。明代兵志记火铳、佛郎机、鸟铳等装备，显示不同来源与形式的武器进入军队。清代八旗、绿营也配置枪炮，晚清进一步购买新式舰炮。技术传播到战场以后，制造质量、弹药供应、训练和指挥仍需相互配合。天京的地道火药用于破墙，黄海舰炮用于海上射击，使用环境与组织条件已有很大差别。","s":["《宋史·卷197·兵志十一》","《明史·卷92·兵志四》","《清史稿·卷130、131·兵志》","《清史稿·卷131·兵志》","《清史稿·卷462·丁汝昌传》","《清史稿·曾国荃传》"]},{"title":"古代战争史料的偏差与数字问题","t":"史书中的征发、号称、实到和杀俘数字，描绘的是不同对象。官渡曹军人数过少，裴松之已据作战经过提出质疑；长平降卒四十万与全役斩首虏四十五万，又有统计重叠。淝水远征军、前锋和岸边部队分别到达，规模也各不相同。传记会突出本传人物，战报常带报功或归责的目的，读者可以比较各篇如何组织同一事件。兵力对比只有在时段、地点和人员类别能够对应时才有意义；胜负的形成，还要结合地形、粮水、军令与各部配合一并理解。","s":["《三国志·武帝纪》及裴松之注","《史记·白起王翦列传》","《晋书·苻坚载记下》"]},{"title":"改朝换代战役一览","t":"带此标签的15场战事如下；其中包含诸侯国、汗国、割据政权和朝廷中枢的兴亡。","s":[]}],"gcTable":[{"name":"牧野之战","from":"商王帝辛统治","to":"周","year":"约前1046","line":"商王败亡，周取得取代商王权的军事基础，后续东征另论。","s":["《史记·周本纪》"]},{"name":"秦灭六国之战","from":"韩、赵（含代）、魏、楚、燕、齐","to":"秦统一帝国","year":"前230—前221","line":"六国王权先后被消灭，不同国家的失都与最后抵抗分阶段。","s":["《史记·秦始皇本纪》"]},{"name":"巨鹿之战","from":"秦的关东主力受重创；不是当场亡国","to":"楚等反秦势力取得优势","year":"前207","line":"秦亡尚须入关受降等环节，此标签按指定保留。","s":["《史记·项羽本纪》"]},{"name":"垓下之战","from":"西楚","to":"汉","year":"前202","line":"楚军解体、项羽随后死，刘邦取得建立帝国的主要军事条件。","s":["《史记·项羽本纪》","《史记·高祖本纪》"]},{"name":"昆阳之战","from":"新的主要出征军；不是当场亡国","to":"更始政权，非25年才建的东汉","year":"23","line":"新军败后长安另陷、王莽被杀，标签按指定保留。","s":["《后汉书·光武帝纪上》","《汉书·王莽传下》"]},{"name":"西晋灭吴之战","from":"东吴","to":"西晋","year":"279—280","line":"孙皓投降，西晋完成对三国主要政权疆域的统一。","s":["《晋书·武帝纪》","《晋书·王濬传》"]},{"name":"永嘉之乱与洛阳陷落","from":"西晋洛阳朝廷；西晋仍续至316","to":"刘聪所统汉政权扩大控制","year":"311","line":"失都俘帝与西晋最终亡国分开，按指定保留标签。","s":["《晋书·怀帝纪、愍帝纪》"]},{"name":"隋灭陈之战","from":"陈","to":"隋","year":"588—589","line":"建康失守、陈后主被俘，南北主要分立格局结束。","s":["《隋书·韩擒虎、贺若弼传》"]},{"name":"虎牢之战","from":"窦建德夏、王世充郑","to":"唐","year":"621","line":"窦被俘、王继而降，唐已建国，本役扩展其统治。","s":["《资治通鉴·卷189》"]},{"name":"靖康之战与汴京陷落","from":"北宋东京朝廷","to":"金扩大中原控制；南宋另建中枢","year":"1126—1127","line":"两次围城、破城与二帝北迁不合为同一天。","s":["《宋史·钦宗纪》","《宋史·高宗纪》"]},{"name":"崖山海战","from":"南宋海上朝廷","to":"元","year":"1279","line":"帝昺死、最后朝廷覆亡，残部另论。","s":["《宋史·张世杰、陆秀夫传》","《元史·张弘范传》"]},{"name":"明军攻占大都","from":"元在中原的首都统治","to":"明","year":"1368","line":"元顺帝北走，北方元政权仍续，不写元室全部灭绝。","s":["《明史·徐达传》","《元史·顺帝纪》"]},{"name":"李自成攻陷北京","from":"明北京朝廷","to":"大顺占据北京，非此时才建国","year":"1644","line":"崇祯帝死，南明仍续，标签须注明统计对象。","s":["《明史·庄烈帝纪》","《明史·李自成传》"]},{"name":"山海关之战","from":"大顺京畿优势受挫；大顺未即日灭亡","to":"清入关并进取北京","year":"1644","line":"清已在1636使用清国号，本役不是清建国之战。","s":["《清史稿·世祖本纪》","《清史稿·吴三桂传》"]},{"name":"天京陷落","from":"太平天国首都及主要中枢","to":"清恢复控制南京","year":"1864","line":"以失都及中枢瓦解为口径，幼天王、各地残部后续另论。","s":["《清史稿·曾国荃传》","《清史稿·洪秀全传》"]}],"checks":[{"name":"牧野之战","q":"地点","why":"河南省新乡市北部一带，古名牧野，具体战场范围有不同定位。"},{"name":"长勺之战","q":"地点","why":"山东省济南市莱芜区一带，古名长勺，具体定位有不同说法。"},{"name":"城濮之战","q":"地点","why":"河南省濮阳市与山东省菏泽市鄄城县交界一带，古名城濮，具体定位有不同说法。"},{"name":"柏举之战","q":"地点","why":"湖北省东北部，古名柏举，有红安、麻城、汉川等不同定位说法。"},{"name":"桂陵之战","q":"地点","why":"河南省长垣市、山东省菏泽市相关地区，古名桂陵，具体定位有不同说法。"},{"name":"桂陵之战","q":"史料说明","why":"《孙子吴起列传》把桂陵获胜与赵围解除相连；《赵世家》《六国年表》另记魏攻取、归还邯郸的年份，各条纪年与解围过程的对应仍有疑问。"},{"name":"马陵之战","q":"地点","why":"山东省临沂市郯城县、河南省濮阳市范县等地有不同定位说法，古名马陵。"},{"name":"巨鹿之战","q":"地点","why":"河北省邢台市平乡县一带，古名巨鹿，具体城址与围城范围仍有定位问题。"},{"name":"垓下之战","q":"地点","why":"安徽省宿州市灵璧县及蚌埠市固镇县等地有不同定位说法，古名垓下；项羽随后经东城到乌江。"},{"name":"白登之战","q":"地点","why":"山西省大同市东北白登山一带，古名白登，具体围困范围仍有定位问题。"},{"name":"漠北之战","q":"地点","why":"主要在今蒙古国境内，涉及漠北多个战场；寘颜山、狼居胥山等古地名的现代对应有不同说法。"},{"name":"赤壁之战","q":"地点","why":"湖北省咸宁市赤壁市赤壁镇为通行定位，嘉鱼县等地另有定位说法；黄冈的黄州赤壁是文学纪念地。"},{"name":"淝水之战","q":"地点","why":"安徽省淮南市寿县一带，古名寿阳、淝水；古河道与具体渡水位置仍有定位问题。"},{"name":"邙山之战","q":"地点","why":"河南省洛阳市北部邙山一带，行动涉及洛阳、虎牢与黄河渡口，具体阵地仍有定位问题。"},{"name":"台城之战","q":"地点","why":"江苏省南京市玄武湖以南相关地区，古名建康台城；六朝宫城与今日同名城墙分属不同时代。"},{"name":"白江口之战","q":"地点","why":"今韩国忠清南道、全北特别自治道之间的锦江河口一带，古名白江口、白村江，具体交锋水域仍有定位问题。"},{"name":"白江口之战","q":"主要将领","why":"乙方：扶余丰；倭方有朴市田来津等，见《日本书纪》。"},{"name":"怛罗斯之战","q":"地点","why":"今哈萨克斯坦江布尔州塔拉兹至吉尔吉斯斯坦塔拉斯河流域，古名怛罗斯、恒逻斯，具体交战点仍有不同说法。"},{"name":"黄巢攻陷长安","q":"时间","why":"唐广明元年十二月，传统纪年作880年，公历跨入881年初。具体公历日待核。"},{"name":"黄巢攻陷长安","q":"史料说明","why":"陷城记于唐广明元年十二月，对应公历跨入881年初；传统“880年陷长安”沿用旧历所属年份。具体回推日期尚有历法换算问题。"},{"name":"高梁河之战","q":"地点","why":"北京市西直门外至西北郊相关地区，古名高梁河、幽州，古河道与具体阵线仍有定位问题。"},{"name":"高梁河之战","q":"主要将领","why":"甲方：宋太宗；曹彬、潘美等参与本轮北征。"},{"name":"好水川之战","q":"地点","why":"宁夏回族自治区固原市隆德县及六盘山相关地区，古名好水川，常见定位在隆德好水一带。"},{"name":"靖康之战与汴京陷落","q":"时间","why":"1126—1127；第一次围城在1126年，第二次城破记靖康元年闰十一月，公历已入1127年初，二帝北迁在1127年春。具体换算日待核。"},{"name":"靖康之战与汴京陷落","q":"史料说明","why":"第二次城破记于靖康元年闰十一月，对应公历已入1127年初；俘帝北迁在其后春季。具体换算日仍待核。"},{"name":"郾城之战","q":"史料说明","why":"《宋史·岳飞传》叙述较详，《金史·宗弼传》未同样展开郾城战术；宋传所记“三马相联”的拐子马形象，其装备与编组解释仍有争议。"},{"name":"钓鱼城之战","q":"主要将领","why":"甲方：王坚；张珏参与守城，其具体职掌有待核实。"},{"name":"钓鱼城之战","q":"史料说明","why":"《元史·宪宗纪》先记六月“不豫”，再记七月去世；炮石、箭伤及具体疾病等死因说法的对应证据仍待核。"},{"name":"崖山海战","q":"经过","why":"元军从不同方向攻击水寨，逐渐逼近宋军中部，宋军队列遭突破。具体潮汐与各路进攻次序仍有讨论。"},{"name":"李自成攻陷北京","q":"经过","why":"城外进攻与议降同时进行，守军动摇，部分城门防御瓦解。各门开闭的时序和责任仍有不同记载。"},{"name":"甲午黄海海战","q":"主要将领","why":"乙方：伊东祐亨、坪井航三等；舰队具体指挥分工待核。"},{"name":"甲午黄海海战","q":"史料说明","why":"《清史稿》卷462载丁汝昌传，卷460载邓世昌等传。卷460记致远中鱼雷、全船无人逃生，威海党史资料记舰载鱼雷爆炸、将士大多遇难；沉舰机制与人员结局的记载仍有差异。"}]};
